INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9888, 'koKR', 'Bezsilny przywódca', 'Uszedłem pewnej śmierci, przeżywszy tchórzliwy nocny napad ogrów Głazopięści na moją wioskę.$B$BAle pytam cię, $gnieznajomy:nieznajoma;: po co?$B$B<Jorin wskazuje na Garosza.>$B$BOn odmówił nam pomocy. Ogry pustoszą moje miasteczko, a on siedzi tu i płacze w ogień. Co się z nami stało? Co się z nami stanie?$B$BWysłałem zwiadowcę, Kilratha, do wioski, która jest teraz Ruinami Krwawiącego Oczodołu. Odszukasz go i udzielisz mu pomocy? Ukrywa się na granicy Nagrandu i Terokkaru.', 'Jorin Celnooki poprosił cię, żebyś $godnalazł:odnalazła; Kilratha i z nim $gporozmawiał:porozmawiała;.', '', '', '', '', '', '', 0),
(9889, 'koKR', 'Nie zabijaj grubasa', 'Obserwuję te bestie od wielu dni. Grubas mówi, że na coś czeka. Na co – tego nie wiadomo.$B$BMam plan, ale będzie wymagał od ciebie trochę przemocy. Musisz zabić kilku jego podwładnych, a potem stłuc go prawie na śmierć. Zrób to, a jestem pewien, że powie nam wszystko, co musimy wiedzieć.', 'Kilrath z Puszczy Terokkar poprosił cię, żebyś $gzabił:zabiła; 10 najeźdźców Głazopięści i $gtłukł:tłukła; Unkora Bezwzględnego, dopóki nie zacznie mówić.', 'Unkor się poddaje', 'Wróć do Unkora Bezwzględnego w Ruinach Krwawiącego Oczodołu w Puszczy Terokkar.', '', '', '', '', 0),
(9890, 'koKR', 'Sukces!', 'Przez wiele lat Głazopięści rządzili wszystkimi ogrami Rubieży. Ogry były zjednoczone pod władzą Krola i zadowolone z ziem, które dostały. W ostatnich miesiącach straciliśmy wiele ogrów przez nowy klan, zwany Wojennymi Maczugami. Wojenne Maczugi zajęły większość naszych ziem w Nagrandzie i wybiły wielu naszych.$B$BNie mieliśmy wyboru, musieliśmy zająć to miasteczko. Oni nas wytępiają...$B$BKrol zaginął, a wśród Głazopięści wrze. Pod jego nieobecność rządzi Lantresor od Ostrza.$B', 'Zanieś informacje, które $gwytłukłeś:wytłukłaś; z Unkora, Kilrathowi w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(9891, 'koKR', 'Bo Kilrath to tchórz', 'Zabierz to, czego się $gdowiedziałeś:dowiedziałaś;, i powiedz Jorinowi w Garadarze. Zapewniam cię, że nie ucieszy się, gdy usłyszy, że naszą wioskę zniszczono, a wielu naszych zabito tylko dlatego, że ogry potrzebowały więcej miejsca.$B$BNiech przodkowie mają cię w opiece... Będę się ukrywał w krzakach, gdybyś jeszcze czegoś ode mnie $gpotrzebował:potrzebowała;.', 'Zanieś informacje, które $gwytłukłeś:wytłukłaś; z Unkora, Jorinowi Celnookiemu w Garadarze w Nagrandzie.', '', '', '', '', '', '', 0),
(9929, 'koKR', 'Zaginiony kupiec', 'Chyba nie jesteś tu na tyle długo, żeby znać Dugara, co? To kupiec, który ma kontakty wśród różnych frakcji w Shattrath.$B$BNie pytaj mnie, jak on to robi, ale udaje mu się wymieniać z nimi towary, których nie mogą nam zapewnić nasi kwatermistrzowie.$B$BTrzy dni temu wyruszył do Shattrath i nie wrócił. Zwykle całą drogę pokonuje w krótszym czasie. Jeśli masz zamiar podróżować po puszczy, rozejrzysz się za nim?', 'Idź na północny zachód drogą w stronę Shattrath i poszukaj śladów tego, co się stało z Dugarem.', '', '', '', '', '', '', 0),
(9930, 'koKR', 'Zaginiony kupiec', 'Chyba nie jesteś tu na tyle długo, żeby znać Deiroma, co? To kupiec, który ma kontakty wśród różnych frakcji w Shattrath.$B$BNie pytaj mnie, jak on to robi, ale udaje mu się wymieniać z nimi towary, których nie mogą nam zapewnić nasi kwatermistrzowie.$B$BTrzy dni temu wyruszył do Shattrath i nie wrócił. Zwykle całą drogę pokonuje w krótszym czasie. Rozglądaj się za nim i o wszystkim, co znajdziesz, melduj dowódcy najemników, Thanderowi.', 'Idź na północny zachód drogą w stronę Shattrath i poszukaj śladów tego, co się stało z Deiromem.', '', '', '', '', '', '', 0),
(9941, 'koKR', 'Tropem sprawców', 'Ślady arakkoa, a obok nich para płytkich kolein, prowadzą na północ, w poprzek drogi. Wygląda na to, że arakkoa zawlekli coś z miejsca walki, być może do pobliskiej osady.$B$BRozbity wóz nosi ślady walki, ale niewiele mówi o losie Deiroma. Idź tropem arakkoa na północ i szukaj dalej kupca. Jeśli pojmano go żywcem, wciąż może być szansa, żeby go uratować.', 'Szukaj dalej śladów Deiroma w osadzie arakkoa na północ od rozbitego wozu.', '', '', '', '', '', '', 0),
(9942, 'koKR', 'Tropem sprawców', 'Ślady arakkoa, a obok nich para płytkich kolein, prowadzą na północ, w poprzek drogi. Wygląda na to, że arakkoa zawlekli coś z miejsca walki, być może do pobliskiej osady.$B$BRozbity wóz nosi ślady walki, ale niewiele mówi o losie Dugara. Idź tropem arakkoa na północ i szukaj dalej kupca. Jeśli pojmano go żywcem, wciąż może być szansa, żeby go uratować.', 'Szukaj dalej śladów Dugara w osadzie arakkoa na północ od rozbitego wozu.', '', '', '', '', '', '', 0),
(9943, 'koKR', 'Powrót do Thandera', 'Ładunek Deiroma wydaje się nietknięty, nikt go nawet nie otworzył. Wyraźnie ich interesował, ale najwidoczniej ważniejszy był jeniec. Nie wiadomo, co arakkoa chcieli zyskać, napadając na Deiroma i porywając go, ale z pewnością nie trzymają go tutaj.$B$BNie mając dalszych wskazówek, jak prowadzić poszukiwania, uznajesz, że to dobra pora, by zdać Thanderowi relację z tego, co $gustaliłeś:ustaliłaś;.', 'Wróć do Thandera w Forcie Alleriańskim i przekaż mu, czego się $gdowiedziałeś:dowiedziałaś;.', '', '', '', '', '', '', 0),
(9947, 'koKR', 'Powrót do Rokaga', 'Ładunek Dugara wydaje się nietknięty, nikt go nawet nie otworzył. Wyraźnie ich interesował, ale najwidoczniej ważniejszy był jeniec. Nie wiadomo, co arakkoa chcieli zyskać, napadając na Dugara i porywając go, ale z pewnością nie trzymają go tutaj.$B$BNie mając dalszych wskazówek, jak prowadzić poszukiwania, uznajesz, że to dobra pora, by zdać Rokagowi relację z tego, co $gustaliłeś:ustaliłaś;.', 'Wróć do Rokaga w Warowni Kamieniołamaczy i przekaż mu, czego się $gdowiedziałeś:dowiedziałaś;.', '', '', '', '', '', '', 0),
(9949, 'koKR', 'Z lotu ptaka', 'Nie mając dalszych informacji, jesteśmy w trudnym położeniu. Nie zamierzam rezygnować z odnalezienia i uratowania Deiroma. Jego porwanie to nie przypadek, $N.$B$BArakkoa coś knują, ale co takiego planują?$B$BAndarl z wieży magów wie to i owo o ich osobliwej magii. Z odpowiednimi narzędziami zdoła wydobyć dla nas nowe informacje. Będzie potrzebował kryształowych „oczu” z każdej z osad arakkoa na północ od Kościanych Pustkowi – z Zasłony Skith, Zasłony Reskk i Zasłony Shienor.', 'Przynieś Oko Zasłony Skith, Oko Zasłony Shienor i Oko Zasłony Reskk Andarlowi w Forcie Alleriańskim.', '', 'Wróć do Andarla w Puszczy Terokkar.', '', '', '', '', 0),
(9950, 'koKR', 'Z lotu ptaka', 'Nie mając dalszych informacji, jesteśmy w trudnym położeniu. Nie zamierzam rezygnować z odnalezienia i uratowania Dugara. Jego porwanie to nie przypadek, $N.$B$BArakkoa coś knują, ale co takiego planują?$B$BCzarnoksiężnik Kurgatok wie to i owo o ich osobliwej magii. Z odpowiednimi narzędziami zdoła wydobyć dla nas nowe informacje. Będzie potrzebował kryształowych „oczu” z każdej z osad arakkoa na północ od Kościanych Pustkowi – z Zasłony Skith, Zasłony Reskk i Zasłony Shienor.', 'Przynieś Oko Zasłony Skith, Oko Zasłony Shienor i Oko Zasłony Reskk Kurgatokowi w Warowni Kamieniołamaczy.', '', 'Wróć do Kurgatoka w Puszczy Terokkar.', '', '', '', '', 0),
(9951, 'koKR', 'Ono cię obserwuje!', 'Szybko, schowaj się! Oczy Naphthal\'ara są zwrócone na ciebie... na nas wszystkich!$B$BNie mam odwagi wejść na szczyt wieży, żeby z nim pomówić, ale ty... ty wyglądasz, jakbyś $gwiedział:wiedziała;, co powiedzieć. Tylko uważaj, on nie lubi żartów i nie znosi głupców.$B$BJeśli zdołasz, przekonaj go, żeby zszedł na herbatkę. Ale przede wszystkim spraw, żeby przestał się na mnie gapić!', 'Zabij Naphthal\'ara, a potem wróć do Strażnika Treelosa w Gąszczu Cenariona w Puszczy Terokkar.', '', 'Wróć do Strażnika Treelosa w Gąszczu Cenariona w Puszczy Terokkar.', '', '', '', '', 0),
(9952, 'koKR', 'Poszukiwacz Balmoral', 'Andarl jest więc pewien, że Deiroma przetrzymują w Zasłonie Shalas? To największa ze znanych nam osad arakkoa.$B$BZasłona Shalas leży na dalekim południu puszczy, blisko wschodniego skraju Kościanych Pustkowi. Niestety niewiele o niej wiem, ale obozuje tam członek Ligi Odkrywców, który może ci pomóc. Obóz Poszukiwacza Balmorala leży na samym krańcu lądu, na południowy zachód od Zasłony Shalas. Porozmawiaj z nim, zanim wystąpisz przeciw arakkoa.', 'Odszukaj Poszukiwacza Balmorala i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(9953, 'koKR', 'Obserwator Nodak', 'Kurgatok jest więc pewien, że Dugara przetrzymują w Zasłonie Shalas? To największa ze znanych nam osad arakkoa.$B$BZasłona Shalas leży na dalekim południu puszczy, blisko wschodniego skraju Kościanych Pustkowi. Niestety niewiele o niej wiem, ale obozuje tam nasz zwiadowca, który może ci pomóc. Obóz Obserwatora Nodaka leży na samym krańcu lądu, na południowy zachód od Zasłony Shalas. Porozmawiaj z nim, zanim wystąpisz przeciw arakkoa.', 'Odszukaj Obserwatora Nodaka i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(9958, 'koKR', 'Rozpoznanie obrony', 'Przez czas spędzony tutaj miałem kilka spotkań z arakkoa i żadne nie było przyjazne. Bardzo pilnują swojego terytorium, ale my chyba jesteśmy tacy sami, prawda?$B$BArakkoa władają pierwotną magią nieznaną nam w Azeroth i utkali z niej osłony wokół Zasłony Shalas. Zanim wystąpimy przeciw nim, rozsądnie byłoby rozpoznać ich obronę, żebyśmy wiedzieli, z czym mamy do czynienia.', 'Zbliż się do Zasłony Shalas i przyjrzyj się obronie osady.', '', 'Wróć do Poszukiwacza Balmorala w Puszczy Terokkar.', 'Zbadaj obronę Zasłony Shalas', '', '', '', 0),
(9959, 'koKR', 'Rozpoznanie obrony', 'Przez czas spędzony tutaj miałem kilka spotkań z arakkoa i żadne nie było przyjazne. Bardzo pilnują swojego terytorium, ale my chyba jesteśmy tacy sami, prawda? Nawet przodkowie nie wspominali o żadnych spotkaniach z ptasimi ludźmi.$B$BArakkoa władają pierwotną magią nieznaną naszym jasnowidzom i utkali z niej osłony wokół Zasłony Shalas. Zanim wystąpimy przeciw nim, mądrze byłoby rozpoznać ich obronę, żebyśmy wiedzieli, z czym mamy do czynienia.', 'Zbliż się do Zasłony Shalas i dowiedz się czegoś o magii, która chroni osadę.', '', 'Wróć do Obserwatora Nodaka w Górach Skethyl w Puszczy Terokkar.', 'Zbadaj obronę Zasłony Shalas', '', '', '', 0),
(9960, 'koKR', '', 'Hej, $N. Od dłuższego czasu nie mamy wieści od druidów z Gąszczu Cenariona.$B$BChcę, żebyś tam $gposzedł:poszła; i $gsprawdził:sprawdziła;, co się dzieje. Trafisz tam, idąc przez puszczę na północny zachód.', '', '', '', '', '', '', '', 0),
(9961, 'koKR', '', '$N, mam dla ciebie pilną sprawę. Od dłuższego czasu nie mamy wieści od druidów z Gąszczu Cenariona. To niezwykłe, bo zwykle odzywają się przynajmniej raz na kilka dni.$B$BChcę, żebyś tam $gposzedł:poszła; i $gupewnił:upewniła; się, że nic im nie jest. Gąszcz znajdziesz, idąc przez puszczę na północny zachód.', '', '', '', '', '', '', '', 0),
(9963, 'koKR', 'Pomoc u źródła', 'Osłony, na które $gtrafiłeś:trafiłaś;, to naprawdę potężna magia. Techniki, jakimi posługują się arakkoa, tak dalece wykraczają poza nasze pojmowanie, że możemy liczyć na znalezienie przeciwzaklęcia tylko z ich pomocą.$B$BWiem, co ci chodzi po głowie. Czemu wróg miałby nam pomóc pokonać własną obronę? Oczywiście, że by nie pomógł. $gSłyszałeś:Słyszałaś; opowieści o szalonym starym mędrcu arakkoa imieniem Kokorek? Mówią, że ukrywa się w Zasłonie Lithic, na zachodnim skraju Kościanych Pustkowi, i czeka na powrót utraconej epoki.', 'Odszukaj Kokoreka w Zasłonie Lithic i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(9964, 'koKR', 'Pomoc u źródła', 'Osłony, na które $gtrafiłeś:trafiłaś;, to naprawdę potężna magia. Techniki, jakimi posługują się arakkoa, tak dalece wykraczają poza nasze pojmowanie, że możemy liczyć na znalezienie przeciwzaklęcia tylko z ich pomocą.$B$BWiem, co ci chodzi po głowie. Czemu wróg miałby nam pomóc pokonać własną obronę? Oczywiście, że by nie pomógł. $gSłyszałeś:Słyszałaś; opowieści o szalonym starym mędrcu arakkoa imieniem Kokorek? Mówią, że ukrywa się w Zasłonie Lithic, na zachodnim skraju Kościanych Pustkowi, i czeka na powrót utraconej epoki.', 'Odszukaj Kokoreka w Zasłonie Lithic i porozmawiaj z nim.', '', '', '', '', '', '', 0),
(9965, 'koKR', 'Dowód dobrej woli', 'Proponuję coś w rodzaju wymiany: okaż dobre intencje, pomagając mi rozwiązać pewien drobny problem, a ja pomogę ci uratować twojego towarzysza.$B$BOgry to odwieczni wrogowie mojego ludu, a ostatnio zaczęły z powrotem przenikać do naszej puszczy z łąk Nagrandu.$B$BJeden ogr, Mug\'gok, to wielki śmiałek, choć niezbyt bystry. Na zmianę sprawia kłopoty swoim przyjaciołom w Ruinach Krwawiącego Oczodołu i próbuje prowokować nas.', 'Przynieś Głowę Mug\'goka Kokorekowi w Zasłonie Lithic.', '', 'Wróć do Kokoreka w Zasłonie Lithic w Puszczy Terokkar.', '', '', '', '', 0),
(9966, 'koKR', 'Dowód dobrej woli', 'Proponuję coś w rodzaju wymiany: okaż dobre intencje, pomagając mi rozwiązać pewien drobny problem, a ja pomogę ci uratować twojego towarzysza.$B$BOgry to odwieczni wrogowie mojego ludu, a ostatnio zaczęły z powrotem przenikać do naszej puszczy z łąk Nagrandu.$B$BJeden ogr, Mug\'gok, to wielki śmiałek, choć niezbyt bystry. Na zmianę sprawia kłopoty swoim przyjaciołom w Ruinach Krwawiącego Oczodołu i próbuje prowokować nas.', 'Przynieś Głowę Mug\'goka Kokorekowi w Zasłonie Lithic.', '', 'Wróć do Kokoreka w Zasłonie Lithic w Puszczy Terokkar.', '', '', '', '', 0),
(9968, 'koKR', 'Dziwna energia', 'Coś dziwnego odmieniło teroćmy z gąszczu.$B$BKiedyś panowała tam różnorodność życia, a teraz zostały tylko teroćmy. Dawniej były spokojne, teraz są pobudzone i bez wahania zaatakują, jeśli podejdziesz za blisko.$B$BMuszę porównać te okrutne ze zwykłymi. Zbierz dla mnie trochę próbek jednych i drugich. Nietknięte teroćmy znajdziesz zarówno na południu, jak i na północy.$B$BJestem pewien, że ma to związek z tym, co zabiło wszystkich druidów.', 'Zbierz 4 próbki teroćmy i 4 próbki okrutnej teroćmy. Potem wróć do Wiążącego ziemię Tavgrena, tuż przed Gąszczem Cenariona w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(9969, 'koKR', 'Ostatnie składniki', 'Mogę stworzyć przedmiot, który zneutralizuje zaklęcia ochronne strzegące Zasłony Shalas, ale ostrzegam cię, $N. Magia będzie działać tylko tak długo, jak długo twój przyjaciel jest w niewoli. Nie dam ci sposobu, byś $gmógł:mogła; atakować mój lud, kiedy zechcesz.$B$BMam większość materiałów potrzebnych do stworzenia amuletu, ale kilka musisz zebrać dla mnie, zanim skończę pracę. Potrzebuję trochę esencji łowcy wypaczenia i garści aronii z Terokkar. Jedno i drugie znajdziesz w okolicach zasłony.', 'Przynieś 5 esencji łowcy wypaczenia i 30 aronii z Terokkar Kokorekowi w Zasłonie Lithic.', '', 'Wróć do Kokoreka w Zasłonie Lithic w Puszczy Terokkar.', '', '', '', '', 0),
(9971, 'koKR', 'Poszlaki w gąszczu', 'Nie mam pojęcia, co zabiło tutejszych druidów. Przez kilka dni mnie nie było, badałem Kościane Pustkowia na południu.$B$BProszę, musisz mi pomóc odkryć, co stoi za tą straszną tragedią. Wejdź do gąszczu i poszukaj jakiejś poszlaki, która mogłaby nam coś wyjaśnić. Kiedy byłem tam przez chwilę, mógłbym przysiąc, że widziałem martwego Złamanego, a obok niego dziwny przedmiot.$B$BI nie przejmuj się Treelosem – to, co się stało, mogło doprowadzić go do obłędu, ale myślę, że jest raczej niegroźny.', 'Zbadaj dziwny przedmiot obok zwłok Złamanego, żeby ustalić, co mogło spotkać Gąszcz Cenariona. Potem wróć do Wiążącego ziemię Tavgrena, tuż przed gąszczem w Puszczy Terokkar.', '', '', 'Dziwny przedmiot zbadany', '', '', '', 0),
(9974, 'koKR', 'Ostatnie składniki', 'Mogę stworzyć przedmiot, który zneutralizuje zaklęcia ochronne strzegące Zasłony Shalas, ale ostrzegam cię, $N. Magia będzie działać tylko tak długo, jak długo twój przyjaciel jest w niewoli. Nie dam ci sposobu, byś $gmógł:mogła; atakować mój lud, kiedy zechcesz.$B$BMam większość materiałów potrzebnych do stworzenia amuletu, ale kilka musisz zebrać dla mnie, zanim skończę pracę. Potrzebuję trochę esencji łowcy wypaczenia i garści aronii z Terokkar. Jedno i drugie znajdziesz w okolicach zasłony.', 'Przynieś 5 esencji łowcy wypaczenia i 30 aronii z Terokkar Kokorekowi w Zasłonie Lithic.', '', 'Wróć do Kokoreka w Zasłonie Lithic w Puszczy Terokkar.', '', '', '', '', 0),
(9975, 'koKR', 'Pierwotna magia', 'Zamknąłem zaklęcie w tym talizmanie. Uwolnij je, stojąc w pobliżu totemów strzegących podejścia do Zasłony Shalas. Powinno wystarczyć, by rozplątać osłony.$B$B<Wspominasz, że postać na talizmanie niezbyt przypomina arakkoa.>$B$BMój lud nie zawsze wyglądał tak jak teraz. Byliśmy niegdyś wspaniałymi istotami, ale... dokonaliśmy wielu nierozważnych wyborów i zawiedliśmy w naszym świętym zadaniu. Kosztowało nas to piękno, moc i omal nie kosztowało nas życia. Nie powtarzaj naszych błędów, $N.', 'Użyj Talizmanu Kokoreka w pobliżu totemów strzegących ścieżki do Zasłony Shalas, a potem porozmawiaj z Poszukiwaczem Balmoralem.', '', 'Wróć do Poszukiwacza Balmorala w Puszczy Terokkar.', 'Użyj Talizmanu Kokoreka', '', '', '', 0),
(9976, 'koKR', 'Pierwotna magia', 'Zamknąłem zaklęcie w tym talizmanie. Uwolnij je, stojąc w pobliżu totemów strzegących podejścia do Zasłony Shalas. Powinno wystarczyć, by rozplątać osłony.$B$B<Wspominasz, że postać na talizmanie niezbyt przypomina arakkoa.>$B$BMój lud nie zawsze wyglądał tak jak teraz. Byliśmy niegdyś wspaniałymi istotami, ale... dokonaliśmy wielu nierozważnych wyborów i zawiedliśmy w naszym świętym zadaniu. Kosztowało nas to piękno, moc i omal nie kosztowało nas życia. Nie powtarzaj naszych błędów, $N.', 'Użyj Talizmanu Kokoreka w pobliżu totemów strzegących ścieżki do Zasłony Shalas, a potem porozmawiaj z Obserwatorem Nodakiem.', '', 'Wróć do Obserwatora Nodaka w Górach Skethyl w Puszczy Terokkar.', 'Użyj Talizmanu Kokoreka', '', '', '', 0),
(9978, 'koKR', 'Wszelkimi sposobami', 'Nie wiem, co o tym wszystkim myśleć, ale wiem, jak znaleźć więcej poszlak.$B$BEmpoor to kupiec ze Złamanych, który handluje wszelkiego rodzaju towarami i informacjami. Gdybyś $gnakłonił:nakłoniła; go do mówienia, na pewno miałby coś ciekawego do powiedzenia.$B$BPodróżuje tutejszą drogą między Tuurem a Shattrath. Uważaj jednak – ma przy sobie ochroniarza.', 'Odszukaj Empoora na drodze między Tuurem a Shattrath w Puszczy Terokkar. Przekonaj go, żeby powiedział ci, co wie.', '', '', '', '', '', '', 0),
(9980, 'koKR', 'Ratunek dla Deiroma!', 'Ruszaj jak najszybciej do Zasłony Shalas, $N! Liczy się czas. Jeśli arakkoa odkryją, co $gzrobiłeś:zrobiłaś; z ich obroną, mogą spróbować przenieść Deiroma albo nawet go zabić.$B$BJeśli możesz, weź ze sobą przyjaciela lub dwóch. Może być tam ciężko. Ptasi ludzie bardzo się postarali, żeby dobrze pilnować jeńca, i raczej nie oddadzą go łatwo. Kiedy już odnajdziesz Deiroma i rozprawisz się z jego porywaczem, wróć do Fortu Alleriańskiego i zawiadom Thandera.', 'Wyrusz do Zasłony Shalas, zabij Luangę i uwolnij Deiroma. Po wykonaniu zadania zgłoś się do Lady Deny Kennedy w Forcie Alleriańskim.', '', 'Wróć do Lady Deny Kennedy w Forcie Alleriańskim w Puszczy Terokkar.', '', 'Uwolnij Deiroma', '', '', 0),
(9981, 'koKR', 'Ratunek dla Dugara!', 'Ruszaj jak najszybciej do Zasłony Shalas, $N! Liczy się czas. Jeśli arakkoa odkryją, co $gzrobiłeś:zrobiłaś; z ich obroną, mogą spróbować przenieść Dugara albo nawet go zabić.$B$BJeśli możesz, weź ze sobą przyjaciela lub dwóch. Może być tam ciężko. Ptasi ludzie bardzo się postarali, żeby dobrze pilnować jeńca, i raczej nie oddadzą go łatwo. Kiedy już odnajdziesz Dugara i rozprawisz się z jego porywaczem, wróć do Warowni Kamieniołamaczy i zawiadom Rokaga.', 'Wyrusz do Zasłony Shalas, zabij Luangę i uwolnij Dugara. Po wykonaniu zadania zgłoś się do Rokaga w Warowni Kamieniołamaczy.', '', 'Wróć do Rokaga w Puszczy Terokkar.', '', 'Uwolnij Dugara', '', '', 0),
(9984, 'koKR', 'Zastępy Ukrytego Miasta', 'Nie potrafisz odczytać dziwnego pisma na zwoju, ale ozdobna pieczęć u dołu dokumentu sugeruje, że sporządził go arakkoa wysokiej rangi. Luanga mógł obmyślić pojmanie i przesłuchiwanie Deiroma, ale wygląda na to, że wykonywał czyjeś rozkazy.$B$BPamiętasz, jak Thander wspominał, że Andarl badał arakkoa. Może zdoła odcyfrować treść zwoju.', 'Zanieś Rozkazy Luangi Andarlowi w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(9985, 'koKR', 'Zastępy Ukrytego Miasta', 'Nie potrafisz odczytać dziwnego pisma na zwoju, ale ozdobna pieczęć u dołu dokumentu sugeruje, że sporządził go arakkoa wysokiej rangi. Luanga mógł obmyślić pojmanie i przesłuchiwanie Dugara, ale wygląda na to, że wykonywał czyjeś rozkazy.$B$BPamiętasz, jak Rokag wspominał, że Kurgatok badał arakkoa. Może zdoła odcyfrować treść zwoju.', 'Zanieś Rozkazy Luangi Kurgatokowi w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(9986, 'koKR', 'Powstrzymać arakkoa', 'Musimy pokazać arakkoa, że nie mogą bezkarnie atakować naszych ludzi. Jeśli nie powstrzymamy ich tutaj, drogi przestaną być bezpieczne dla naszych kupców, gońców i żołnierzy.$B$BMoi zwiadowcy ustalili, kto przewodzi każdej z większych osad arakkoa w okolicy. Odszukaj Ashkaza, Ayita i Urdaka w Zasłonie Reskk, Zasłonie Shienor i Zasłonie Skith i zabij ich.', 'Zabij Ashkaza w Zasłonie Reskk, Ayita w Zasłonie Shienor i Urdaka w Zasłonie Skith, a potem wróć do Thandera w Forcie Alleriańskim.', '', 'Wróć do Thandera w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(9987, 'koKR', 'Powstrzymać arakkoa', 'Musimy pokazać arakkoa, że nie mogą bezkarnie atakować naszych ludzi. Jeśli nie powstrzymamy ich tutaj, drogi przestaną być bezpieczne dla naszych kupców, gońców i żołnierzy.$B$BMoi zwiadowcy ustalili, kto przewodzi każdej z większych osad arakkoa w okolicy. Odszukaj Ashkaza, Ayita i Urdaka w Zasłonie Reskk, Zasłonie Shienor i Zasłonie Skith i zabij ich.', 'Zabij Ashkaza w Zasłonie Reskk, Ayita w Zasłonie Shienor i Urdaka w Zasłonie Skith, a potem wróć do Rokaga w Warowni Kamieniołamaczy.', '', 'Wróć do Rokaga w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(9988, 'koKR', 'Najlepszy przyjaciel dandysa', 'Nie daj się zwieść Thanderowi i jego kompanii. Mogą wyglądać na bandę groźnych wojowników, ale pod tą całą stalą to tylko gromada dandysów!$B$BI nie pokażą się publicznie bez kapeluszy. To wymyślne dzieła z filcu i futra, ozdobione najbardziej krzykliwymi piórami, jakie w życiu $gwidziałeś:widziałaś;.$B$BNajbardziej pożądane są oczywiście pióra arakkoa, a moje zapasy się kończą. Chętnie ci zapłacę, jeśli mi je zbierzesz.', 'Przynieś 30 piór arakkoa Ros\'eleth w Forcie Alleriańskim.', '', 'Wróć do Ros\'eleth w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(9989, 'koKR', 'Obce duchy', 'Kiedy przybyłem do Rubieży i otworzyłem uszy na głosy jej duchów, zdumiało mnie to, co usłyszałem. Z czasem zauważyłem też, których duchów nie słyszę.$B$BMimo wszelkich prób nigdy nie udało mi się nawiązać kontaktu z duchem przodka arakkoa. Ich magia zasadniczo różni się od naszej, ale nie jestem przekonany, że ich duchy są poza moim zasięgiem.$B$BPrzynieś mi pióra od wielu arakkoa. Może jakaś pamiątka po nich da mi potrzebną więź.', 'Przynieś 30 piór arakkoa Malukazowi w Warowni Kamieniołamaczy.', '', 'Wróć do Malukaza w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(9992, 'koKR', 'Nasiona olemby', 'Czy drzewa w tej puszczy nie są piękne? Często się zastanawiałam, czy przetrwałyby w Azeroth.$B$BWaham się jednak, czy wysyłać tam sadzonki. To ciężka podróż, a sadzonki dużo trudniej przewieźć niż, powiedzmy, worek nasion. Nasiona kryją się w twardych szyszkach, które spadają z gałęzi, gdy dojrzeją.$B$BJeśli podczas wędrówek natkniesz się na te szyszki, przyniesiesz mi trochę nasion?', 'Zbierz 30 nasion olemby i zanieś je Ros\'eleth w Forcie Alleriańskim.', '', 'Wróć do Ros\'eleth w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(9993, 'koKR', 'Olej z nasion olemby', 'Oleiste nasiona z tutejszych drzew olemby mogą okazać się bardzo cenne. Chciałabym zebrać ich więcej, wytłoczyć z nich olej i zobaczyć, co da się z nim zrobić.$B$BPomyśl tylko, cała puszcza pełna drzew, które produkują mnóstwo nasion, a te się marnują. Nieważne, czy wyjdzie z tego olej do gotowania, do lamp czy do broni – nie pozwolę, żeby się zmarnowały!$B$BPrzynoś mi wszystkie nasiona, które zbierzesz z szyszek olemby. Leżą wszędzie.', 'Przynieś 30 nasion olemby Rakorii w Warowni Kamieniołamaczy.', '', 'Wróć do Rakorii w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(9994, 'koKR', 'Co to za rzeczy?', 'Nie wiem jak ty, ale ja nie mam pojęcia, czym są te wszystkie rzeczy. Wiem za to jedno – wyglądają groźnie!$B$B$N, myślę, że $gpowinieneś:powinnaś; zanieść tę skrzynkę części Jenai Gwiezdnemu Szeptowi w Forcie Alleriańskim na południowym wschodzie. Może ona będzie wiedziała, co to jest.', 'Dostarcz skrzynkę części Jenai Gwiezdnemu Szeptowi w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(9995, 'koKR', 'Co to za rzeczy?', 'Nie wiem jak ty, ale ja nie mam pojęcia, czym są te wszystkie rzeczy. Wiem za to jedno – wyglądają groźnie!$B$B$N, myślę, że $gpowinieneś:powinnaś; zanieść tę skrzynkę części Tookiemu w Warowni Kamieniołamaczy na południowym wschodzie. Może on będzie wiedział, co to jest.', 'Dostarcz skrzynkę części Tookiemu w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(9996, 'koKR', 'Atak na Punkt Ognistego Skrzydła', 'Wiemy, że krwawe elfy z Punktu Ognistego Skrzydła pracują dla Kael\'thasa i Illidana. A z tego, co mi $gpowiedziałeś:powiedziałaś;, jasno wynika, że wykorzystują Złamanych z Tuurem jako przemytniczych pośredników przy tworzeniu jakiejś straszliwej broni.$B$BCokolwiek tam knują, najskuteczniej możemy teraz przerzedzić ich szeregi.$B$BKrwawe elfy z Ognistego Skrzydła trzeba wyeliminować! Ruszaj do Punktu Ognistego Skrzydła na północy i dopilnuj tego.', 'Zabij 10 obrońców Ognistego Skrzydła, 10 krwawych stróżów Ognistego Skrzydła i 10 czarnoksiężników Ognistego Skrzydła. Potem złóż meldunek Porucznikowi Meridianowi w Posterunku Alleriańskim w Puszczy Terokkar.', '', 'Wróć do Porucznika Meridiana w Posterunku Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(9997, 'koKR', 'Atak na Punkt Ognistego Skrzydła', 'Wiemy, że krwawe elfy z Punktu Ognistego Skrzydła pracują dla Kael\'thasa i Illidana. A z tego, co mi $gpowiedziałeś:powiedziałaś;, jasno wynika, że wykorzystują Złamanych z Tuurem jako przemytniczych pośredników przy tworzeniu jakiejś straszliwej broni.$B$BCokolwiek tam knują, najskuteczniej możemy teraz przerzedzić ich szeregi.$B$BKrwawe elfy z Ognistego Skrzydła trzeba wyeliminować! Ruszaj do Punktu Ognistego Skrzydła na północnym wschodzie i dopilnuj tego.', 'Zabij 10 obrońców Ognistego Skrzydła, 10 krwawych stróżów Ognistego Skrzydła i 10 czarnoksiężników Ognistego Skrzydła. Potem złóż meldunek Sierżant Chawni w Obozie Kamieniołamaczy w Puszczy Terokkar.', '', 'Wróć do Sierżant Chawni w Obozie Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(9998, 'koKR', 'Kłopotliwi sąsiedzi', 'Niedawne przybycie spaczonych orków do ruin na wschodzie zarówno dziwi, jak i niepokoi Thandera. Bez zwłoki zaczęli wznosić umocnienia i odbudowywać zabudowania.$B$BBudowa trwa dniem i nocą, $N. Wysłałem na zwiady jednego z moich najbardziej zaufanych agentów, ale nie możemy sobie pozwolić na zwlekanie. Uderz na ich robotników, a potem odszukaj Thelorię Cienisty Płaszcz w Posterunku Alleriańskim na północ od Ruin Szpikożerców. Ona da ci dalsze instrukcje.', 'Zabij 12 wypaczonych peonów, a potem zgłoś się do Thelorii Cienistego Płaszcza w Posterunku Alleriańskim.', '', 'Wróć do Thelorii Cienistego Płaszcza w Posterunku Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10000, 'koKR', 'Nieproszeni goście', 'Nasze siły w Thrallmarze sądziły, że zatrzymały spaczone orki w okolicach Cytadeli Piekielnego Ognia, ale niedawni przybysze w ruinach na wschodzie świadczą o czymś innym.$B$BNie możemy im pozwolić zdobyć tu przyczółka. Rokag wysłał Skrytotropiciela Kaidego do ruin, żeby miał na nich oko, ale musimy coś zrobić, żeby się tam nie okopali.$B$BIdź do ruin, przetrzeb ich peonów, a potem poszukaj Kaidego wśród drzew na północy. Powie ci, dokąd iść dalej.', 'Zabij 12 wypaczonych peonów, a potem zgłoś się do Skrytotropiciela Kaidego.', '', 'Wróć do Skrytotropiciela Kaidego w Obozie Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10002, 'koKR', 'Łączniczka Ognistego Skrzydła', 'Przez ostatnie dni obserwowałam krwawą elfkę, która kursuje do twierdzy spaczonych orków i z powrotem i rozmawia z ich przywódcą. Z jej postawy widać wyraźnie, że wydaje rozkazy. Ale dlaczego? Czyje rozkazy przekazuje?$B$BCiekawość wzięła górę nad rozsądkiem i śledziłam ją, gdy opuściła obóz spaczonych orków. Poszła na północ, do Punktu Ognistego Skrzydła. Zatrzymałam się, zanim dotarłam do granic tej placówki krwawych elfów.$B$BZabij ją, zanim znów opuści obóz spaczonych orków.$B', 'Odszukaj i zabij Lisaile Tkaczkę Ognia, a potem wróć do Thelorii Cienistego Płaszcza.', '', 'Wróć do Thelorii Cienistego Płaszcza w Posterunku Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10003, 'koKR', 'Łączniczka Ognistego Skrzydła', 'Przez ostatnie dni obserwowałem krwawą elfkę, która kursuje do twierdzy spaczonych orków i z powrotem i rozmawia z ich przywódcą. Z jej postawy widać wyraźnie, że wydaje rozkazy. Ale dlaczego? Czyje rozkazy przekazuje?$B$BCiekawość wzięła górę nad rozsądkiem i śledziłem ją, gdy opuściła obóz spaczonych orków. Poszła na północ, do Punktu Ognistego Skrzydła. Zatrzymałem się, zanim dotarłem do granic tej placówki krwawych elfów.$B$BZabij ją, zanim znów opuści obóz spaczonych orków.', 'Odszukaj i zabij Lisaile Tkaczkę Ognia, a potem wróć do Skrytotropiciela Kaidego.', '', 'Wróć do Skrytotropiciela Kaidego w Obozie Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10005, 'koKR', 'Wieści dla Wiążącego ziemię Tavgrena', '$N, kiedy skończysz tu świętować, myślę, że $gpowinieneś:powinnaś; wrócić do Gąszczu Cenariona i porozmawiać z Wiążącym ziemię Tavgrenem.$B$BJestem pewna, że zechce wiedzieć, co tam się naprawdę wydarzyło.', 'Porozmawiaj z Wiążącym ziemię Tavgrenem tuż przed Gąszczem Cenariona w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10006, 'koKR', 'Wieści dla Wiążącego ziemię Tavgrena', '$N, myślę, że kiedy skończysz tu świętować, $gpowinieneś:powinnaś; wrócić do Gąszczu Cenariona i porozmawiać z Wiążącym ziemię Tavgrenem.$B$BJestem pewien, że zechce wiedzieć, co tam się naprawdę wydarzyło.', 'Porozmawiaj z Wiążącym ziemię Tavgrenem tuż przed Gąszczem Cenariona w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10007, 'koKR', 'Przerzedzanie szeregów', 'Znając Thandera i Bertelma, nie będą tolerować tak dużego skupiska wrogich sił tuż pod naszym progiem. Prosić ich o wysłanie ludzi z garnizonu do ataku na obóz też nie ma sensu. Zostalibyśmy przez to zbyt narażeni na atak.$B$BDo nas należy zrobić, co się da, żeby zmniejszyć zagrożenie ze strony gromadzących się spaczonych orków. Zabij, ilu zdołasz, a ja poszukam sposobów, żeby opóźnić nadejście posiłków.', 'Zabij 10 niszczycieli Szpikożerców i 6 łamaczy grzbietów Szpikożerców, a potem wróć do Thelorii Cienistego Płaszcza.', '', 'Wróć do Thelorii Cienistego Płaszcza w Posterunku Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10008, 'koKR', 'Co się dzieje w Terokkarze, zostaje w Terokkarze', 'Jeśli do Thrallmaru dotrze wieść, że nie udało im się powstrzymać spaczonych orków, zwali nam się tu na głowę mnóstwo towarzystwa. Szczerze mówiąc, nie wiem, czy chcę aż tyle uwagi, więc ten mały problem zachowamy dla siebie, jasne?$B$BJeśli zadamy spaczonym orkom dość strat, jest szansa, że nikt spoza Kamieniołamaczy nigdy się o nich nie dowie. Skończmy więc z tym teraz.$B$BWkrocz tam, machaj bronią, wymachuj rękami czy co tam robisz – byle zabijać spaczone orki.', 'Skrytotropiciel Kaide chce, żebyś $gzabił:zabiła; 10 niszczycieli Szpikożerców i 6 łamaczy grzbietów Szpikożerców.', '', 'Wróć do Skrytotropiciela Kaidego w Obozie Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10012, 'koKR', 'Plany spaczonych orków', 'Pismo na planach jest zbyt delikatne i precyzyjne, by mógł je sporządzić którykolwiek ze spaczonych orków. Nie potrafisz odczytać tekstu, ale wymowa jest całkiem jasna: spaczone orki wykonują rozkazy krwawych elfów z Punktu Ognistego Skrzydła.$B$BCzemu te dwie siły miałyby ze sobą współpracować? Bertelm może coś wiedzieć o tym dziwnym sojuszu. Postanawiasz wrócić do Fortu Alleriańskiego i pokazać mu mapę.', 'Zanieś Plany spaczonych orków Bertelmowi w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10013, 'koKR', 'Niewidzialna ręka', 'Pismo na planach jest zbyt delikatne i precyzyjne, by mógł je sporządzić którykolwiek ze spaczonych orków. Nie potrafisz odczytać tekstu, ale wymowa jest całkiem jasna: spaczone orki wykonują rozkazy krwawych elfów z Punktu Ognistego Skrzydła.$B$BCzemu te dwie siły miałyby ze sobą współpracować? Rokag może coś wiedzieć o tym dziwnym sojuszu. Postanawiasz wrócić do Warowni Kamieniołamaczy i pokazać mu mapę.', 'Zanieś Plany spaczonych orków Rokagowi w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10014, 'koKR', 'Projekt Punktu Ognistego Skrzydła', 'Jak mówiłem, właśnie dostaliśmy nowe informacje wywiadowcze i mamy na głowie dużo większy problem.$B$BKrwawe elfy w Punkcie Ognistego Skrzydła pracują w pocie czoła nad budową drugiej bomby. Nie potrafię dość mocno podkreślić, co by oznaczało, gdyby ją ukończyły i użyły takiego urządzenia przeciw Fortowi Alleriańskiemu!$B$BMoi zwiadowcy donoszą, że kodów do urządzenia strzegą w czterech mniejszych budynkach otaczających centralny dziedziniec. Wejdź tam i zdobądź te kody, zanim będzie za późno!', 'Wykradnij cztery arkusze kodów bomby many i dostarcz je Porucznikowi Meridianowi w Posterunku Alleriańskim w Puszczy Terokkar.', '', 'Wróć do Porucznika Meridiana w Puszczy Terokkar.', '', '', '', '', 0),
(10015, 'koKR', 'Projekt Punktu Ognistego Skrzydła', 'Jak mówiłam, właśnie dostaliśmy nowe informacje wywiadowcze i mamy na głowie dużo większy problem.$B$BKrwawe elfy w Punkcie Ognistego Skrzydła pracują w pocie czoła nad budową drugiej bomby. Nie potrafię dość mocno podkreślić, co by oznaczało, gdyby ją ukończyły i użyły takiego urządzenia przeciw Warowni Kamieniołamaczy!$B$BMoi zwiadowcy donoszą, że kodów do urządzenia strzegą w czterech mniejszych budynkach otaczających centralny dziedziniec. Wejdź tam i zdobądź te kody, zanim będzie za późno!', 'Wykradnij cztery arkusze kodów bomby many i dostarcz je Sierżant Chawni w Obozie Kamieniołamaczy w Puszczy Terokkar.', '', 'Wróć do Sierżant Chawni w Puszczy Terokkar.', '', '', '', '', 0),
(10016, 'koKR', 'Ogony leśnych worgów', '$GNatknąłeś:Natknęłaś; się w swoich wędrówkach na leśne worgi? Miałem okazję je obserwować, gdy sporządzałem mapy północnych rubieży puszczy. Nie radzę się do nich zbliżać, jeśli nie jesteś $ggotów:gotowa; do walki.$B$BNie boją się nas i bez wahania bronią swojego terytorium.$B$BNic dziwnego, że takie stworzenie ma wspaniały ogon. Próbuję zebrać ich dość, żeby obszyć nowy płaszcz, ale worgi mają zwyczaj omijać moje sidła. Pomożesz?', 'Bertelm z Fortu Alleriańskiego chce, żebyś $gprzyniósł:przyniosła; mu 12 ogonów leśnych worgów. Ogony można zdobyć zarówno z leśnych worgów, jak i z samców alfa leśnych worgów.', '', 'Wróć do Bertelma w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10018, 'koKR', 'Szaty wilczego ducha', 'Przed wieloma pokoleniami, gdy Puszcza Terokkar była jeszcze domem orkowych klanów, wilczy duch odgrywał ważną rolę w ich życiu. Gdy orkowie odeszli, nie potrzebowali już ducha i zostawili go.$B$BZ czasem duch poczuł się samotny i on także opuścił puszczę.$B$BWierzę, że zdołam sprowadzić wilczego ducha z powrotem do jego rodzinnego domu, tak jak my, orkowie, wróciliśmy. Rytuał wymaga, bym sporządził szaty ze skór tutejszych wilków, które poprowadzą ducha z powrotem do domu.', 'Przynieś 12 skór leśnych worgów Malukazowi w Warowni Kamieniołamaczy.', '', 'Wróć do Malukaza w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10022, 'koKR', 'Nieuchwytny Żelaznoszczęki', 'Skoro mam już futro na obszycie, pomyślałem, że skóra pewnego wilka nadałaby się na kaptur do mojego płaszcza. Wyobraź sobie wroga odzianego w skórę najprzebieglejszego drapieżnika w puszczy!$B$BPróbowałem bez powodzenia złapać starego Żelaznoszczękiego w pułapkę. Próbowałem go osaczyć, przechytrzyć i zwabić przynętą. Nic nie zadziałało.$B$BKrąży po północno-wschodnich rubieżach puszczy i chętnie cię wynagrodzę, jeśli uda ci się tam, gdzie mnie się nie udało.', 'Przynieś Futro Żelaznoszczękiego Bertelmowi w Forcie Alleriańskim.', '', 'Wróć do Bertelma w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10023, 'koKR', 'Patriarcha Żelaznoszczęki', 'Dobrze się $gspisałeś:spisałaś;, zbierając pierwsze skóry.$B$BOstatnia część szat wymaga skóry, jakiej nie ma żadna inna. Jest pewien wilk, stary i przebiegły, który zasłużył na miano patriarchy leśnych wilków. Znają go jako Żelaznoszczękiego, potężnego łowcę.$B$BW wizjach widziałem, jak wędruje po północno-wschodniej części puszczy. Jego skóra wpleciona w szaty z pewnością oświetli wilczemu duchowi drogę.$B$BNie opłakuj Żelaznoszczękiego. Zostanie należycie uczczony.', 'Przynieś Futro Żelaznoszczękiego Malukazowi w Warowni Kamieniołamaczy.', '', 'Wróć do Malukaza w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10026, 'koKR', 'Magiczne zakłócenia', 'Wstyd się przyznać, ale tu, w Puszczy Terokkar, przydarzyło mi się coś, co nie zdarzało mi się od czasów, gdy byłem uczniem.$B$BCzasami moje zaklęcia spalają na panewce, choć wiem, że zrobiłem wszystko jak należy. Za pierwszym razem omal nie oszalałem.$B$BChyba znalazłem przyczynę. Puszcza jest pełna stworzeń zwanych tropicielami wypaczenia – demonicznych istot, które ciągnie do magii i które mają zwyczaj zakłócać jej przepływ. Najlepiej po prostu je zabić.', 'Andarl z Fortu Alleriańskiego chce, żebyś $gzabił:zabiła; 10 tropicieli wypaczenia.', '', 'Wróć do Andarla w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10027, 'koKR', 'Magiczne zakłócenia', 'Nie ma nic bardziej irytującego niż przygotowania do rzucenia zaklęcia, które przerywa jakaś niewidzialna siła. Za czwartym razem wiedziałem, że to nie może być przypadek, i wysłałem Keb\'ezila, żeby to zbadał.$B$BGwarantuję ci, że nie spotkasz chochlika, który bardziej by pyskował niż Keb.$B$BTak czy owak, udało mu się znaleźć źródło problemu – dokuczliwe stworzenie zwane tropicielem wypaczenia. Te stwory mają zwyczaj zakłócać energię magiczną wszędzie tam, gdzie się pojawią. Mam dość ich wtrącania się.', 'Zabij 10 tropicieli wypaczenia i wróć do Kurgatoka w Warowni Kamieniołamaczy.', '', 'Wróć do Kurgatoka w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10028, 'koKR', 'Naczynia mocy', 'W ruinach Tuurem jest sporo naczyń zawierających surową energię magiczną. Na szczęście Złamani, którzy opanowali miasto, nie wiedzą, jakie bogactwo mają pod nosem, ale nie możemy zakładać, że zawsze tak będzie.$B$BMając te naczynia i ich moc, rozproszeni ocaleli z mojego ludu zdołają oprzeć się pokusie demonicznej magii. Każdy quel\'dorei, którego ocalimy przed szaleństwem naszego księcia, to jeszcze jeden, który pomoże nam odzyskać utraconą chwałę. Przynieś mi te naczynia, $N.', 'Przynieś 8 draenejskich naczyń Ros\'eleth w Forcie Alleriańskim.', '', 'Wróć do Ros\'eleth w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10029, 'koKR', 'Wołanie duchów', 'Duchy zmarłych na Kościanych Pustkowiach wołają do mnie i cierpią!$B$B$N, musisz wyruszyć na Kościane Pustkowia na południu i odnaleźć mojego pomocnika, Soolaveena, przy Karawanie Uchodźców. On też musi to czuć i będzie potrzebował twojej pomocy, żeby ukoić tamtejsze duchy.$B$BJeśli się pospieszysz, może ich jeszcze zastaniesz. Wiem, że mieli zatrzymać się na jakiś czas w północnej części Kościanych Pustkowi, zanim ruszą dalej na południe, do Auchindoun.', 'Anachoretka Lyteera chce, żebyś $godnalazł:odnalazła; jej pomocnika, Soolaveena, przy Karawanie Uchodźców na Kościanych Pustkowiach w Puszczy Terokkar.$B$BWykonywanie zadań dla Aldorów obniży twoją reputację u Widzących.$B', '', '', '', '', '', '', 0),
(10030, 'koKR', 'Odzyskanie kości', 'Kościane Pustkowia usiane są kośćmi draenei, którzy zginęli w wybuchu Auchindoun. Ich duchy nie zaznają spokoju i nie mogą przejść do następnego życia.$B$B$N, musisz mi pomóc odzyskać ich kości i zanieść je na miejsce wiecznego spoczynku! Tylko wtedy zaznają spokoju, tylko wtedy znajdą ukojenie.$B$BZbieraj ostrożnie niespokojne kości i dostarcz je Ramdorowi Szalonemu w Auchindoun, pośrodku Kościanych Pustkowi. Mimo swojego przydomka będzie wiedział, jak się nimi zająć.', 'Zbierz 10 niespokojnych kości. Dostarcz je Ramdorowi Szalonemu, tuż przy zachodniej stronie Kręgu Obrzędów w Auchindoun, pośrodku Kościanych Pustkowi w Puszczy Terokkar.$B', '', 'Wróć do Ramdora Szalonego przy Kręgu Obrzędów w Auchindoun na Kościanych Pustkowiach.', '', '', '', '', 0),
(10031, 'koKR', 'Zagubionym wskazać drogę', 'Wybuch Auchindoun splugawił wiele duchów draenei. Teraz błąkają się po pustkowiach w męce.$B$B$N, błagam cię, pozwól im spocząć. Zniszcz zagubione duchy i szkielety Złamanych, które nawiedzają Kościane Pustkowia za murami Auchindoun.$B$BCo? Uważasz, że lepiej zostawić je, by błąkały się w ślepej agonii?$B$BPotem wróć do Soolaveena przy Karawanie Uchodźców i opowiedz mu, co $gzrobiłeś:zrobiłaś;.', 'Zniszcz 10 zagubionych duchów i 10 szkieletów Złamanych, a potem porozmawiaj z Soolaveenem przy Karawanie Uchodźców na Kościanych Pustkowiach w Puszczy Terokkar.$B', '', 'Wróć do Soolaveena w obozie uchodźców na Kościanych Pustkowiach.', '', '', '', '', 0),
(10032, 'koKR', 'Artefakty z Tuurem', 'Czy $gzauważyłeś:zauważyłaś;, jak zachowują się Zagubieni w Tuurem? Błąkają się po ruinach w poszukiwaniu ocalałych okruchów czegokolwiek, co wytworzyli draenei.$B$BIch panowie ze Złamanych są mądrzejsi. Porzucili dawne życie i tożsamość i stali się czymś zupełnie innym.$B$BMyślę, że możemy wykorzystać tę obsesję Zagubionych i zdobyć od nich stare draenejskie relikty. Po co ryzykować życie i zdrowie w walce ze Złamanymi, skoro możemy zyskać, rozważnie wybierając cele?', 'Zdobądź 6 artefaktów z Tuurem od padlinożerców z Tuurem i łowców z Tuurem i zanieś je Rakorii w Warowni Kamieniołamaczy.', '', 'Wróć do Rakorii w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10033, 'koKR', 'Poszukiwane: martwe kościosmagacze!', 'Wyznacza się nagrodę za kościosmagacze z Kościanych Pustkowi. Jako znani roznosiciele zarazy mają zostać niezwłocznie wytępieni!$B$BMożna je spotkać na całych pustkowiach, ale wiadomo, że gromadzą się na Wzgórzu Padliny na północy.$B$BPo wykonaniu zadania zgłoś się do Taeli Wiecznokrokiej po nagrodę.', 'Zabij 20 kościosmagaczy, a potem zgłoś się do Taeli Wiecznokrokiej w Forcie Alleriańskim w Puszczy Terokkar.', '', 'Wróć do Taeli Wiecznokrokiej w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10034, 'koKR', 'Poszukiwane: martwe kościosmagacze!', 'Kościosmagacze z Kościanych Pustkowi pogryzły Mawga i się rozchorował. Teraz chce, żeby wszystkie zostały zniszczone!$B$BMożna je spotkać na całych pustkowiach, ale wiadomo, że gromadzą się na Wzgórzu Padliny na północy.$B$BGdy już to zrobisz, wróć do Mawga Ponurostrzała, a da ci porządną nagrodę.', 'Zabij 20 kościosmagaczy, a potem zgłoś się do Mawga Ponurostrzała w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', 'Wróć do Mawga Ponurostrzała w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10035, 'koKR', 'Torgos!', 'Na Kościanych Pustkowiach żyje stworzenie tak straszne, że polować na nie ważą się tylko nieustraszeni.$B$BMówię o Torgosie, królu kościosmagaczy, który krąży nad Zasłoną Rhaze na zachodnim skraju pustkowi.$B$BSzkoda tylko, że stoi tam strach na wróble arakkoa, zwany Zgubą Torgosa, który trzyma go na dystans. Założę się, że gdybyś $gpołożył:położyła; truchło jego partnerki, Trachelii, u stóp tego stracha, i tak by zleciał. Znajdziesz ją na Wzgórzu Padliny na północy pustkowi.$B$BPrzynieś mi jedno z piór ogonowych Torgosa.', 'Zwab Torgosa na dół za pomocą Truchła Trachelii. Zdobądź Pióro ogonowe Torgosa i zanieś je Taeli Wiecznokrokiej w Forcie Alleriańskim w Puszczy Terokkar.', '', 'Wróć do Taeli Wiecznokrokiej w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10036, 'koKR', 'Torgos!', 'Chcę śmierci Torgosa, króla kościosmagaczy!$B$BNiedawno, gdy polowałem w Zasłonie Rhaze na zachodnim skraju pustkowi, rzucił się na mnie.$B$B<Mawg stuka palcem w przepaskę na oku.>$B$BZabrał mi oko, a teraz ja chcę jego życia! Przynieś mi jedno z jego piór ogonowych na dowód, a dam ci godną nagrodę.$B$BBędziesz jednak potrzebować truchła jego partnerki, Trachelii, żeby go zwabić na dół, bo śmiertelnie boi się starego stracha na wróble arakkoa, zwanego Zgubą Torgosa.$B$BZnajdziesz ją na Wzgórzu Padliny na północy pustkowi.', 'Zwab Torgosa na dół za pomocą Truchła Trachelii. Zdobądź Pióro ogonowe Torgosa i zanieś je Mawgowi Ponurostrzałowi w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', 'Wróć do Mawga Ponurostrzała w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10039, 'koKR', 'Porozmawiaj ze Zwiadowczynią Neftis', 'Doniesiono mi, że jedna z naszych zwiadowczyń w pobliżu Wioski Grangol\'var obserwuje właśnie tajemniczą bandę, która niedawno się tam osiedliła.$B$B$N, chcę, żebyś $gporozmawiał:porozmawiała; ze Zwiadowczynią Neftis i $gsprawdził:sprawdziła;, jak możesz jej pomóc ustalić, co knuje ta nieznana grupa.$B$BIdź stąd na południe, a potem prosto na zachód, omijając północny skraj Kościanych Pustkowi. Według ostatniego meldunku jest w pobliżu południowego wejścia do wioski.', 'Porozmawiaj ze Zwiadowczynią Neftis w pobliżu południowego wejścia do Wioski Grangol\'var w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10041, 'koKR', '', '', 'W przebraniu porozmawiaj z cienistym nowicjuszem, cienistym robotnikiem i cienistym doradcą. Potem wróć do Zwiadowczyni Neftis w Wiosce Grangol\'var w Puszczy Terokkar.', '', 'Wróć do Zwiadowczyni Neftis w Wiosce Grangol\'var w Puszczy Terokkar.', '', '', '', '', 0),
(10043, 'koKR', '', 'Co?! Ci goście to Rada Cieni?!$B$B$N, musisz tam wrócić i ich wykończyć! Masz zabić ich przywódcę i tylu katów i przywoływaczy, ilu zdołasz.$B$BKiedy już z tym skończysz, zgłoś się do Doradczyni Faili w Warowni Kamieniołamaczy.$B$BPowodzenia, $N!', 'Zabij 10 cienistych katów, 10 cienistych przywoływaczy i Mistrza cieni Grieve\'a, a potem wróć do Doradczyni Faili w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', 'Wróć do Doradczyni Faili w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10048, 'koKR', 'Garść magicznego pyłu', 'Będę potrzebował pyłu, ale nie byle jakiego.$B$BKrólewskie teroćmy zamieszkujące pobliską puszczę mają na skrzydłach magiczny pył, którym uspokajają tych, którzy na nie polują. Mogę wykorzystać tę właściwość pyłu, żeby złagodzić opór, jaki wyczuwam w oczach arakkoa, które $gzdobyłeś:zdobyłaś;. To z kolei pozwoli mi użyć ich do odnalezienia Deiroma.$B$BNie będę potrzebował dużo, może z pół tuzina garści.', 'Zbierz 7 garści uspokajającego pyłu dla Andarla w Forcie Alleriańskim.', '', 'Wróć do Andarla w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10049, 'koKR', 'Garść magicznego pyłu', 'Będę potrzebował pyłu, ale nie byle jakiego.$B$BKrólewskie teroćmy zamieszkujące pobliską puszczę mają na skrzydłach magiczny pył, którym uspokajają tych, którzy na nie polują. Mogę wykorzystać tę właściwość pyłu, żeby złagodzić opór, jaki wyczuwam w oczach arakkoa, które $gzdobyłeś:zdobyłaś;. To z kolei pozwoli mi użyć ich do odnalezienia Dugara.$B$BNie będę potrzebował dużo, może z pół tuzina garści.', 'Zbierz 7 garści uspokajającego pyłu dla Kurgatoka w Warowni Kamieniołamaczy.', '', 'Wróć do Kurgatoka w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10051, 'koKR', 'Ucieczka z Punktu Ognistego Skrzydła!', 'Dzięki niebiosom, że jesteś!$B$B$N, musisz mi pomóc uciec. Mam informacje kluczowe dla bezpieczeństwa Fortu Alleriańskiego, a pewnie i całej Rubieży!$B$BPrzybyłam tu z misją dyplomatyczną od Ekspedycji Cenariońskiej, ale jak widzisz, nie byli zbyt przyjaźni. Jeśli pomożesz mi dotrzeć w bezpieczne miejsce, zapewniam cię, że zostaniesz sowicie $gnagrodzony:nagrodzona;!$B$BSami nie damy rady – masz ze sobą drużynę, prawda?', 'Odprowadź Islę Gwiezdną Grzywę w bezpieczne miejsce, a potem zgłoś się do Kapitana Aurica Słońcogona w Forcie Alleriańskim w Puszczy Terokkar.', 'Odprowadź Islę Gwiezdną Grzywę w bezpieczne miejsce', 'Wróć do Kapitana Aurica Słońcogona w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10052, 'koKR', 'Ucieczka z Punktu Ognistego Skrzydła!', 'Dzięki niebiosom, że jesteś!$B$B$N, musisz mi pomóc uciec. Mam informacje kluczowe dla bezpieczeństwa Warowni Kamieniołamaczy, a pewnie i całej Rubieży!$B$BPrzybyłam tu z misją dyplomatyczną od Ekspedycji Cenariońskiej, ale jak widzisz, nie byli zbyt przyjaźni. Jeśli pomożesz mi dotrzeć w bezpieczne miejsce, zapewniam cię, że zostaniesz sowicie $gnagrodzony:nagrodzona;!$B$BSami nie damy rady – masz ze sobą drużynę, prawda?', 'Odprowadź Islę Gwiezdną Grzywę w bezpieczne miejsce, a potem zgłoś się do Doradczyni Faili w Warowni Kamieniołamaczy w Puszczy Terokkar.', 'Odprowadź Islę Gwiezdną Grzywę w bezpieczne miejsce', 'Wróć do Doradczyni Faili w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10094, 'koKR', 'Kodeks Krwi', 'Minęły dwa lata od przywołania Rady Cieni, które skończyło się wybuchem tego niegdyś wspaniałego mauzoleum i powstaniem Kościanych Pustkowi.$B$BTeraz toczą wojnę z niewiarygodnie potężną siłą w środku.$B$B$N, musisz dostać się do Labiryntu Cieni, ustalić, z czym się mierzą, i sprawdzić, czy stanowi to zagrożenie dla nas. Nasi szpiedzy mówią, że korzystają z zakazanej księgi bluźnierczych przywołań, znanej jedynie jako Kodeks Krwi.$B$BSzukaj odpowiedzi na jej stronach.', 'Przeczytaj Kodeks Krwi w Labiryncie Cieni w Auchindoun.', '', '', '', '', '', '', 0),
(10097, 'koKR', 'Brat przeciw bratu', 'Kiedy wybuchło Auchindoun, Sethekk opuścili Skettis z wielką pompą. Z pewnością był to znak nadejścia naszego pana.$B$BMój brat, Syth, był jednym z ich przywódców i powiedział nam, że naszym obowiązkiem jest wejść do ruin świątyni i stanąć przed naszym bogiem.$B$BKiedy zamieszkaliśmy w ruinach, nazwawszy je Salami Sethekk, zaczęły mnie nachodzić wątpliwości co do mojego brata i jego sojusznika, Ikissa.$B$BZ czasem Syth kazał mnie wygnać z Sal, ale nie pozwolił mi zabrać ze sobą naszej siostry, Lakki. Pomożesz mi ją uratować?', 'Zabij Tkacza Mroku Sytha w Salach Sethekk, a potem uwolnij Lakkę z niewoli. Kiedy już ją uratujesz, wróć do Isfara przed Salami Sethekk.', '', 'Wróć do Isfara na Kościanych Pustkowiach w Puszczy Terokkar.', '', 'Uwolnij Lakkę', '', '', 0),
(10098, 'koKR', 'Dziedzictwo Terokka', 'Mój lud czci starożytnego bohatera imieniem Terokk. Pisklęta arakkoa karmi się opowieściami o jego czynach i opisami jego pięknego upierzenia.$B$BŻył wśród mojego ludu przez setki lat, ale pewnego dnia w tajemniczy sposób zniknął, zostawiając po sobie tylko maskę, włócznię i pisma.$B$BArakkoa otaczają te relikwie czcią i serca im pękły, gdy Sethekk, odchodząc, zabrali je ze Skettis.$B$BNa tym zwoju masz to niewiele, co wiem o tym, gdzie w salach mogą się znajdować.', 'Przynieś Maskę Terokka, Pióro Terokka i Sagę o Terokku Isfarowi przed Salami Sethekk.', '', 'Wróć do Isfara na Kościanych Pustkowiach w Puszczy Terokkar.', '', '', '', '', 0),
(10164, 'koKR', 'Wszystko będzie dobrze', 'Sporo już $gprzeżyłeś:przeżyłaś;, $N. A to jeszcze zanim w ogóle $gpostawiłeś:postawiłaś; stopę w Kryptach Auchenai.$B$BJestem jednym z tych szczęśliwych duchów. Nie byłem związany z Levixusem ani nie padłem ofiarą nikczemnych nekromanckich eksperymentów Egzarchy Maladaara. Choć $gzniszczyłeś:zniszczyłaś; Levixusa, Maladaar wciąż żyje i dalej dręczy duchy w kryptach.$B$BMoja prośba jest prosta. Wejdź do Krypt Auchenai i zniszcz Egzarchę Maladaara, żeby uwięzione w nich duchy mogły wreszcie spocząć w pokoju.', 'Praojciec Aldrimus, który stoi przed Kryptami Auchenai w Auchindoun, poprosił cię, żebyś $gwszedł:weszła; do Krypt Auchenai i $gzniszczył:zniszczyła; Egzarchę Maladaara.', '', 'Wróć do Praojca Aldrimusa w Auchindoun w Puszczy Terokkar.', '', '', '', '', 0),
(10165, 'koKR', 'Podkopać konkurencję', 'Ten Shaffar to cwaniak – muszę mu to przyznać... Udało mu się trzymać Konsorcjum z dala, a sam spokojnie łupi tę kryptę ze wszystkiego, co cenne. Nie wierzę, że ci imbecyle naprawdę przebiją się przez obronę Shaffara, więc proponuję ci układ, $N.$B$BWejdź do Grobowców Many i zabij Księcia Nexusa Shaffara. Przynieś mi jego owijacze na dowód, a sowicie cię wynagrodzę.', 'Książę Nexusa Haramad, który stoi przed Grobowcami Many, chce, żebyś $gzabił:zabiła; Księcia Nexusa Shaffara i $gprzyniósł:przyniosła; mu Owijacze Shaffara.', '', 'Wróć do Księcia Nexusa Haramada na Kościanych Pustkowiach w Puszczy Terokkar.', '', '', '', '', 0),
(10178, 'koKR', 'Odnajdź Szpiega To\'guna', 'To\'gun, ten głupiec! Ledwo odpieramy tu ataki, a on wraca do środka po więcej informacji i żeby ratować innych szpiegów!$B$BSama nie wiem, czy go kochać, czy zabić!$B$BRada Cieni musiała nas wytropić magią, bo wszyscy nasi szpiedzy musieli w pośpiechu stamtąd uciekać. Większości z nas się nie udało.$B$BProszę, jeśli masz dość odwagi, by wejść do Labiryntu Cieni, wypatruj To\'guna. Minęło już sporo czasu i obawiam się najgorszego.', 'Odnajdź Szpiega To\'guna w Labiryncie Cieni w Auchindoun.', '', '', '', '', '', '', 0),
(10195, 'koKR', 'Najemnik widzi, najemnik chce', 'Odkąd $gprzyniosłeś:przyniosłaś; pierwszą partię piór, a ja skończyłam kapelusz Bertelma, wszyscy pozostali najemnicy domagają się własnych, łącznie z Thanderem. Powiedziałam im, że od razu się tym zajmę, ale do tego przedsięwzięcia potrzebuję stałych dostaw piór arakkoa.$B$BChętnie przyjmę każde, które zbierzesz podczas przygód w puszczy.', 'Przynieś 30 piór arakkoa Ros\'eleth w Forcie Alleriańskim.', '', 'Wróć do Ros\'eleth w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(10196, 'koKR', 'Więcej piór arakkoa', 'Udało mi się już nieco przyciągnąć do siebie duchy arakkoa, ale wciąż są bardzo płochliwe. Może jeśli ulepszę swoje przebranie, chętniej zbliżą się do mnie podczas transu.$B$BDo tego jednak potrzebuję więcej piór, takich jak te, które już mi $gprzyniosłeś:przyniosłaś;. Jeśli zdobędziesz ich więcej, chętnie je od ciebie wezmę.', 'Przynieś 30 piór arakkoa Malukazowi w Warowni Kamieniołamaczy.', '', 'Wróć do Malukaza w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10201, 'koKR', 'A teraz chwila prawdy', 'Olej jest wreszcie gotowy do pierwszej próby. Wydaje się dość gęsty, by posłużyć jako olej do broni wysokiej jakości.$B$BJedynym sposobem, żeby to sprawdzić, jest dać go do wypróbowania zawodowcowi. Widzisz Greka, tam przy listach gończych? Fakt, poetą nie jest, ale ten ork zna się na broni!$B$BZanieś mu próbkę oleju i poproś, żeby użył go na swojej broni. Gdy już go wypróbuje, daj mi znać, co o nim sądzi.', 'Odszukaj Greka i poproś go, żeby wypróbował olej na swojej broni. Gdy to zrobi, wróć z wynikami do Rakorii.', '', 'Wróć do Rakorii w Warowni Kamieniołamaczy w Puszczy Terokkar.', 'Grek wypróbował olej z olemby', '', '', '', 0),
(10216, 'koKR', 'Bezpieczeństwo przede wszystkim', 'Eterycy Shaffara całkowicie odcięli nam dostęp do Grobowców Many. Na szczęście mam plan. Choć nie wejdziemy frontowymi drzwiami, w środku na pewno jest kilka transporterów.$B$BNajpierw oczyść drogę dla mojej ekipy, a potem uruchom jeden z ich transporterów, żeby przeteleportować nas do środka.$B$BGdy droga będzie wolna, uruchom teleporter w komnacie tuż przed komnatami Shaffara. Nie martw się, opłaci ci się to...', 'Artefaktor Morphalius chce, żebyś $gzabił:zabiła; 10 eterycznych rabusiów krypt, 5 eterycznych czarowników, 5 tropicieli Nexusa i 5 eterycznych zaklinaczy.$B$BGdy to zrobisz, odszukaj eteryczny transporter w komnacie przed komnatą Shaffara i go uruchom.', '', 'Wróć do panelu sterowania eterycznego transportera na Polach Międzygórza w Międzygórzu.', '', '', '', '', 0),
(10218, 'koKR', 'Cudza ciężka praca się opłaca', 'A kogo się $gspodziewałeś:spodziewałaś;!? Tego idiotę Morphaliusa „zdegradowano w priorytetach”. Teraz jestem tu, żeby posprzątać po nim bałagan. Musisz tylko pilnować moich pleców, gdy będę obchodził zbieracze eteru Shaffara i wysysał z nich wszystko, co zgromadziły. Jeśli uda mi się wykonać misję, nagrodzi cię sam Haramad!$B$BCo ty na to? Odprowadzisz mnie przez Grobowce Many, a potem zgarniesz niesamowity skarb? I tak $godwaliłeś:odwaliłaś; już większość roboty! Za nami nic już nie żyje, prawda?', 'Odprowadź bezpiecznie Krioinżyniera Sha\'heena przez Grobowce Many, żeby mógł zebrać eter zgromadzony w zbieraczach eteru Shaffara.$B$BJeśli ci się uda, zgłoś się do Księcia Nexusa Haramada, który stoi przed Grobowcami Many w obozowisku Konsorcjum.', 'Odprowadź Krioinżyniera Sha\'heena', 'Wróć do Księcia Nexusa Haramada na Kościanych Pustkowiach w Puszczy Terokkar.', '', '', '', '', 0),
(10227, 'koKR', 'Widzę martwych draenei', 'Widzę martwych draenei. Są wszędzie wokół nas.$B$BEch, nikt mi nie wierzy, bo jestem dzieckiem. Nawet własna mamusia mi nie wierzy.$B$B<Ha\'lei wskazuje na Ramdora.>$B$BAle on mi wierzy... On też ich widzi. I ale się o to złości!$B$BTo nawet zabawne. Kiedy ja widzę duchy, ludzie tylko się uśmiechają i głaszczą mnie po głowie, żeby mnie uspokoić. Kiedy Ramdor widzi duchy, ludzie mówią, że jest szalony. Oby tylko nigdy nie dorosnąć!$B$BZanim wejdziesz do środka, lepiej porozmawiaj z Ramdorem. Był kiedyś kapłanem śmierci.', 'Porozmawiaj z Ramdorem Szalonym, który stoi na stosie kości przed Kryptami Auchenai.', '', '', '', '', '', '', 0),
(10253, 'koKR', 'Levixus, przywoływacz dusz', 'Idź już, $N. Levixusa znajdziesz na najwyższych ruinach Auchindoun. Wejdziesz tam od południowego krańca Kościanych Pustkowi. Stoi pośród burzy dusz...$B$BZniszcz go i zabierz księgę umarłych. Gdy przeklęta księga znajdzie się w twoich rękach, zniszcz ją! Zniszcz ją, by takie okrucieństwo nigdy więcej nie było możliwe.', 'Zniszcz Levixusa i odbierz mu Księgę Umarłych.$B$BDostarcz Księgę Umarłych Ramdorowi Szalonemu, który stoi przed wejściem do Krypt Auchenai w Auchindoun.$B$BUmowa to umowa, pamiętasz?', '', 'Wróć do Ramdora Szalonego przy Auchindoun w Puszczy Terokkar.', '', '', '', '', 0),
(10444, 'koKR', 'Meldunek w Posterunku Alleriańskim', 'To wymaga natychmiastowego działania!$B$BMamy w terenie, bliżej Punktu Ognistego Skrzydła, kogoś, z kim chcę, żebyś $gporozmawiał:porozmawiała;. On będzie lepiej wiedział, jaki powinien być nasz następny krok.$B$BZamelduj się u porucznika Meridiana w Posterunku Alleriańskim i przedstaw mu sytuację. Posterunek znajdziesz na północnym wschodzie, na południowym brzegu rzeki, tuż na południe od Punktu Ognistego Skrzydła.$B$BSzerokiej drogi, $N.', 'Jenai Gwiezdny Szept chce, żebyś $gzameldował:zameldowała; się u porucznika Meridiana w Posterunku Alleriańskim w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10446, 'koKR', 'Ostatni kod', 'Budują na dziedzińcu drugą bombę many. Według moich informacji ostatni kod do bomby ma Sharth Voldoun, nadzorca projektu w Punkcie Ognistego Skrzydła.$B$B$N, musisz tam wrócić i odebrać mu ostatni kod. Przebywa na szczycie najwyższej iglicy.$B$BZanieś ostatni kod do bomby many, nad którą pracują na centralnym dziedzińcu, i ją zdetonuj.$B$BDopiero wtedy będziemy mieć pewność, że Fort Alleriański jest bezpieczny.', 'Porucznik Meridian chce, żebyś $gużył:użyła; Ostatniego kodu, by zdetonować bombę many. Następnie zamelduj się u Jenai Gwiezdnego Szeptu w Forcie Alleriańskim w Puszczy Terokkar.', '', 'Wróć do Jenai Gwiezdnego Szeptu w Forcie Alleriańskim w Puszczy Terokkar.', '', 'Bomba many uruchomiona', '', '', 0),
(10447, 'koKR', 'Ostatni kod', 'Budują na dziedzińcu drugą bombę many. Według moich informacji ostatni kod do bomby ma Sharth Voldoun, nadzorca projektu w Punkcie Ognistego Skrzydła.$B$B$N, musisz tam wrócić i odebrać mu ostatni kod. Przebywa na szczycie najwyższej iglicy.$B$BZanieś ostatni kod do bomby many, nad którą pracują na centralnym dziedzińcu, i ją zdetonuj.$B$BDopiero wtedy będziemy mieć pewność, że Warownia Kamieniołamaczy jest bezpieczna.', 'Sierżant Chawni chce, żebyś $gużył:użyła; arkusza z ostatnim kodem, by zdetonować bombę many. Następnie zamelduj się u Tookiego w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', 'Wróć do Tookiego w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', 'Bomba many uruchomiona', '', '', 0),
(10448, 'koKR', 'Meldunek w Obozie Kamieniołamaczy', 'To wymaga natychmiastowego działania!$B$BMamy w terenie, bliżej Punktu Ognistego Skrzydła, kogoś, z kim chcę, żebyś $gporozmawiał:porozmawiała;. Ona będzie lepiej wiedziała, jaki powinien być nasz następny krok.$B$BZamelduj się u sierżant Chawni w Obozie Kamieniołamaczy i przedstaw jej sytuację.$B$BIdź drogą na północ od warowni. Ze środka Tuurem skręć drogą na wschód. Obóz znajdziesz na brzegu rzeki, tuż na południowy zachód od Punktu Ognistego Skrzydła.$B$BPowodzenia, $N.', 'Tooki chce, żebyś $gzameldował:zameldowała; się u sierżant Chawni w Obozie Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10649, 'koKR', 'Księga spaczonych imion', 'Rozumiem, że chcesz powstrzymać Varedisa i jego popleczników, ale nie masz z nim szans. Chyba że znajdziesz artefakt, który dał mu moc.$B$BPodobno Księga spaczonych imion jest w posiadaniu Czarnosercego Podżegacza w Labiryncie Cieni w Auchindoun. Zdobycie jej to twoja jedyna nadzieja w starciu z Varedisem.', 'Wypraw się do Labiryntu Cieni w Auchindoun i zdobądź Księgę spaczonych imion od Czarnosercego Podżegacza. Po wykonaniu zadania wróć do Altruisa w Nagrandzie.', '', 'Wróć do Altruisa Cierpiącego w Obozie Kuźniczym Nienawiść w Nagrandzie.', '', '', '', '', 0),
(10662, 'koKR', 'Kowal pustelnik', '<Ordinn ogląda efekty swojej próby obróbki metalu i kręci głową.>$B$BTo przerasta moje umiejętności, ale nie znaczy to, że nie da się odtworzyć tej broni dla ciebie.$B$BZ Synami Lothara przybył na Draenor utalentowany kowal, David Wayne. Był znakomitym kowalem, ale postanowił opuścić ekspedycję. Obecnie mieszka w niewielkim obozie na półwyspie na wschód od Punktu Ognistego Skrzydła w Puszczy Terokkar. Zanieś mu sztabki i sprawdź, czy zdoła ci pomóc z bronią.', 'Zanieś skrzynkę sztabek Davidowi Wayne\'owi w Schronieniu Wayne\'a w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10663, 'koKR', 'Kowal pustelnik', '<Ork kręci głową nad swoją porażką.>$B$BTo przerasta moje umiejętności, ale nie znaczy to, że tej broni nie da się odtworzyć.$B$BBoli mnie, że to mówię, ale twoją jedyną nadzieją może być ludzki kowal, niejaki David Wayne. To prawda, że należał kiedyś do ekspedycji Przymierza, ale to było dawno temu i od tamtej pory odszedł od Synów Lothara. Obecnie mieszka w niewielkim obozie na półwyspie na wschód od Punktu Ognistego Skrzydła w Puszczy Terokkar. Zanieś mu sztabki i sprawdź, czy zdoła ci pomóc.', 'Zanieś skrzynkę sztabek Davidowi Wayne\'owi w Schronieniu Wayne\'a w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10664, 'koKR', 'Dodatkowe materiały', 'Sztabki, które $gprzyniosłeś:przyniosłaś;, zawierają większość metalu potrzebnego do wykucia głowni miecza, ale do pozostałych części broni potrzebuję różnych innych rzeczy.$B$BZobaczmy... Brakuje mi tu między innymi ramy z adamantytu, ciężkiej sękatej skóry i totemu ochrony przed demonami. Wprawni rzemieślnicy powinni umieć wykonać dwie pierwsze rzeczy, ale totem sprzedaje tylko Fantei, sprzedawca odczynników w Dolnym Mieście w Shattrath. Znajdziesz go wśród innych kupców.', 'David Wayne w Schronieniu Wayne\'a chce, żebyś $gprzyniósł:przyniosła; mu ramę z adamantytu, 4 ciężkie sękate skóry i totem ochrony przed demonami.', '', 'Wróć do Davida Wayne\'a w Schronieniu Wayne\'a w Puszczy Terokkar.', '', '', '', '', 0),
(10665, 'koKR', 'Prosto z Mechanaru', 'Obróbka sztabek, które $gprzyniosłeś:przyniosłaś;, będzie wymagała ogromnego żaru – znacznie większego, niż może dać zwykła kuźnia.$B$BBędę potrzebował dodatkowego źródła ciepła dla kuźni, a na Rubieży niewiele rzeczy może dostarczyć takiej mocy.$B$BW Mechanarze, części Twierdzy Burz, wytwarza się ogniwa many, które zawierają niewiarygodną ilość energii. Znajdź jedno z przeładowanych ogniw many w stosach wokół mechanowładcy Capacitusa i przynieś je tutaj.', 'David Wayne w Schronieniu Wayne\'a chce, żebyś $gprzyniósł:przyniosła; mu przeładowane ogniwo many.', '', 'Wróć do Davida Wayne\'a w Schronieniu Wayne\'a w Puszczy Terokkar.', '', '', '', '', 0),
(10666, 'koKR', 'Lexicon Demonica', 'Odtworzenie zaklęć nałożonych na ostrze wymaga wypowiedzenia kilku formuł w języku demonów.$B$BNie uczono mnie tego, gdy terminowałem, ale nie da się tego obejść. Istnieje księga zwana Lexicon Demonica, w której jest większość potrzebnych mi słów, ale znajduje się w rękach potężnego czarnoksiężnika z Rady Cieni.$B$BStrzeże jej arcymistrz Vorpil, głęboko w salach Labiryntu Cieni w Auchindoun. Zrób, co musisz, by zdobyć księgę, i przynieś mi ją.', 'Zdobądź Lexicon Demonica od arcymistrza Vorpila i zanieś go Davidowi Wayne\'owi w Schronieniu Wayne\'a.', '', 'Wróć do Davida Wayne\'a w Schronieniu Wayne\'a w Puszczy Terokkar.', '', '', '', '', 0),
(10667, 'koKR', 'Ziemia z zaświatów', 'Rama, którą $gprzyniosłeś:przyniosłaś; mi wcześniej, bez wzmocnienia nie utrzyma stopionego metalu. Pewien rzadki rodzaj ziemi pozwala schłodzić i nasycić ramę, nadając adamantytowi nienaturalną wytrzymałość.$B$BZiemia z zaświatów, bo tak się ją nazywa, jest wysoko ceniona przez nagi. Mało która ją posiada, a na Rubieży znam tylko jedną nagę, która jej używa – hydromantkę Thespię, która przebywa w Krypcie Pary w Zbiorniku Żmijokolców.', 'Zdobądź fiolkę ziemi z zaświatów od hydromantki Thespii i zanieś ją Davidowi Wayne\'owi w Schronieniu Wayne\'a.', '', 'Wróć do Davida Wayne\'a w Schronieniu Wayne\'a w Puszczy Terokkar.', '', '', '', '', 0),
(10670, 'koKR', 'Łza Matki Ziemi', 'Zaklęcia miecza muszą zostać zamknięte w potężnym ognisku mocy, takim jak klejnot. Znam klejnot, którego możemy do tego użyć – niewiele jest takich, które pomieszczą tak potężną magię i nie pękną.$B$BPotrzebny nam klejnot nazywa się Łzą Matki Ziemi. To potężny artefakt w rękach ogrów, którzy go stworzyli, a Siewca Wojny O\'mrogg, który obecnie go posiada, ma wielu potężnych sojuszników w Strzaskanych Salach Cytadeli Piekielnego Ognia. Uważaj na siebie, gdy będziesz odbierać łzę, $N.', 'Odzyskaj Łzę Matki Ziemi od Siewcy Wojny O\'mrogga i zanieś ją Davidowi Wayne\'owi w Schronieniu Wayne\'a.', '', 'Wróć do Davida Wayne\'a w Schronieniu Wayne\'a w Puszczy Terokkar.', '', '', '', '', 0),
(10676, 'koKR', 'Zguba Illidari', '<David zbiera narzędzia kowalskie.>$B$BDobrze się $gspisałeś:spisałaś;, zdobywając wszystko, czego trzeba do przekucia ostrza przeciw demonom. Twoja ciężka praca i poświęcenie zaraz się opłacą.$B$BNadszedł czas, by wykuć miecz.', 'Zaczekaj, aż David Wayne skończy wykuwać dla ciebie miecz.', '', '', '', '', '', '', 0),
(10679, 'koKR', 'Hartowanie ostrza', 'Ostrze jest prawie gotowe!$B$BNiemal czujesz, jak magia zaczyna się zespalać wewnątrz stali, ale została jeszcze jedna rzecz do zrobienia.$B$BMusisz zanieść wykute ostrze do Wrzących Sadzawek w pobliżu szczytu Ręki Gul\'dana w Dolinie Cienistego Księżyca i zanurzyć je w lawie, by zahartować miecz. Gdy to zrobisz, wróć tutaj.', 'Udaj się do Wrzących Sadzawek w pobliżu szczytu Ręki Gul\'dana i użyj wykutego ostrza zguby Illidari, by zahartować je w lawie. Gdy zdobędziesz zahartowane ostrze zguby Illidari, wróć do Davida Wayne\'a w Schronieniu Wayne\'a.', '', 'Wróć do Davida Wayne\'a w Schronieniu Wayne\'a w Puszczy Terokkar.', '', '', '', '', 0),
(10791, 'koKR', 'Powitanie wilczego ducha', 'Prawie skończyłem szaty, które założę na ceremonię. Gdy będę nanosił ostatnie poprawki, chciałbym, żebyś $gpostawił:postawiła; to kadzidło przy świecach obok kamienia runicznego po mojej lewej.$B$BMyślę, że pomoże nam przyciągnąć uwagę wilczego ducha, bo zrobiono je jeszcze w czasach orczych klanów. Niemal widzę, jak moi przodkowie używają go podczas ceremonii ku czci wilczego ducha po udanym polowaniu.$B$BGdy postawisz kadzidło, rozpocznę ceremonię.', 'Użyj kadzidła obrzędowego przy świecach w chacie Malukaza i obserwuj ceremonię. Gdy ceremonia się zakończy, porozmawiaj ponownie z Malukazem.', '', 'Wróć do Malukaza w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', 'Pomóż Malukazowi przywołać wilczego ducha', '', '', 0),
(10839, 'koKR', 'Zasłona Skith: Mroczny kamień Terokka', 'Zasłona Skith leży na północny zachód od karawany i na południe od Shattrath, w ustronnym zagajniku puszczy. Podobno kolonia Skettis wzniosła tam złowrogi ołtarz. Ten Mroczny kamień Terokka trzeba oczyścić, jeśli arakkoa ze Skith mają kiedykolwiek dostąpić odkupienia.$b$bWeź tę Różdżkę oczyszczenia i użyj jej na Mrocznym kamieniu. Różdżka pobłogosławiona przez A\'dala może mieć w sobie dość czystości, by rozproszyć mrok kamienia. Idź już i niech Światłość świeci nad tobą.', 'Użyj Różdżki oczyszczenia na Mrocznym kamieniu Terokka w Zasłonie Skith i wróć do Kirrika Przebudzonego przy Karawanie Uchodźców na Kościanych Pustkowiach.', 'Spróbuj oczyścić Mroczny kamień Terokka', 'Wróć do Kirrika Przebudzonego przy Karawanie Uchodźców na Kościanych Pustkowiach.', '', '', '', '', 0),
(10840, 'koKR', 'Grobowiec Świateł', 'Na wschodzie, pogrzebany pod zwęglonym piaskiem, leży Grobowiec Świateł, zapomniane miejsce spoczynku zmarłych. Zanim napadnięto naszą karawanę, zamierzałem udać się do grobowca i oczyścić go ze złych duchów.$B$BNie wiedziałem, że zagnieździło się tam już zło innego rodzaju. Nawet teraz eterycy plądrują ciała poległych w poszukiwaniu błyskotek i pamiątek, które zmarłym ofiarowano przed wiekami.$B$BNiewiele mogę zrobić, gdy nasza karawana walczy o przetrwanie.', 'Arcykapłan Orglum chce, żebyś $gudał:udała; się do Grobowca Świateł, $gzabił:zabiła; 10 eterycznych otchłanomantów i 10 eterycznych łupieżców, a potem $gwrócił:wróciła; do niego przy Karawanie Uchodźców.', '', 'Wróć do arcykapłana Orgluma przy Karawanie Uchodźców na Kościanych Pustkowiach.', '', '', '', '', 0),
(10841, 'koKR', 'Mściwy zwiastun', '', '', '', '', '', '', '', '', 0),
(10842, 'koKR', 'Mściwe dusze', 'Rada Cieni splugawiła Grobowiec Świateł, a zmarli draenei stali się przeklętymi duchami, rozgniewanymi i zagubionymi, pałającymi nienawiścią do żywych.$b$bWejdź do grobowca i odszukaj te tragiczne ofiary. Daj im spoczynek, na który zasługują.', 'Arcykapłan Orglum chce, żebyś $gudał:udała; się do Grobowca Świateł i $gpokonał:pokonała; 5 mściwych draenei.', '', 'Porozmawiaj z arcykapłanem Orglumem przy Karawanie Uchodźców na Kościanych Pustkowiach.', 'Zabici mściwi draenei', '', '', '', 0),
(10848, 'koKR', 'Zasłona Rhaze: Nieżywe zło', 'Zasłona Rhaze była wyjątkowo nikczemną kolonią Skettis.$b$bChoć katastrofa w Auchindoun zmiotła wioskę z powierzchni ziemi, wpływ Terokka przetrwał w tamtejszych złowrogich duchach. Udaj się na zachód do Zasłony Rhaze i zgładź te mordercze kreatury. Znajdziesz je na zachód od Grobowca Cienia, na granicy Kościanych Pustkowi i Puszczy Terokkar.$b$bTo będzie nasz pierwszy cios wymierzony w Terokka i strażników Skettis.', 'Zabij 4 duchy Śmiertelnego Szponu, 4 skrzeczące duchy i 2 duchowe kruki, a potem wróć do Kirrika Przebudzonego przy Karawanie Uchodźców.', '', 'Wróć do Kirrika Przebudzonego przy Karawanie Uchodźców na Kościanych Pustkowiach.', '', '', '', '', 0),
(10852, 'koKR', 'Zaginieni przyjaciele', 'Utknęliśmy tutaj, bo w nocy przyszli jacyś goście i strasznie hałasowali. Bałem się. Nie wiem, kiedy znowu ruszymy w drogę.$B$BAle kilku moich przyjaciół zaginęło. Nie wiem, gdzie są. Chyba ci straszni ptakoludzie zabrali ich na północny zachód. Pewnie siedzą pozamykani w klatkach i w ogóle. Byłoby super, gdyby udało ci się ich znaleźć. Trochę się o nich martwię.', 'Ethan chce, żebyś $godnalazł:odnalazła; 12 jego zaginionych przyjaciół w Zasłonie Skith, a potem $gwrócił:wróciła; do niego przy Karawanie Uchodźców.', '', 'Wróć do Ethana przy Karawanie Uchodźców na Kościanych Pustkowiach.', 'Uratowane dzieci', '', '', '', 0),
(10861, 'koKR', 'Zasłona Lithic: Uderzenie wyprzedzające', 'W nędznej kolonii na południowym zachodzie, zwanej Zasłoną Lithic, sługi Terokka próbują splugawić swoich ptasich pobratymców, zanim ci się wyklują. Mroczni czarownicy z Lithic spowijają jaja cienistą klątwą. Pisklęta, które się z nich wyklują, bezmyślnie służą Terokkowi.$b$bUdaj się do Zasłony Lithic i rozbij jaja przedwcześnie, zanim klątwa zdąży w nie przeniknąć. Nawet jeśli nie zdążysz, możesz zgładzić te skażone.$b$bPamiętaj, Światłość jaśnieje najmocniej w ciemności.', 'Rozbij przeklęte jaja w Zasłonie Lithic. Odkup 3 pisklęta i zabij 3 złowrogie pisklęta, a potem wróć do Kirrika Przebudzonego przy Karawanie Uchodźców.', '', 'Wróć do Kirrika Przebudzonego przy Karawanie Uchodźców na Kościanych Pustkowiach.', 'Odkupione pisklęta', '', '', '', 0),
(10868, 'koKR', 'Na wojennej ścieżce z arakkoa', 'Arakkoa znów nas zaatakowali, tym razem uderzając nocą, a potem uciekli za pomocą mrocznej magii, zanim zdążyliśmy ruszyć na nich większymi siłami. Używają swoich kręgów przywołań, by ratować wojowników przed pewną śmiercią, ale nie uciekną przed nami, jeśli zaatakujemy ich domy. Zasłona Reskk i Zasłona Shienor leżą na północy i północnym wschodzie.$B$BZnajdź te gniazda arakkoa i zabij, ilu tylko zdołasz.', 'Doradczyni Faila prosi, żebyś $gzabił:zabiła; 14 szponowców z Shienor i 6 czarowników z Shienor, a potem $gwrócił:wróciła; do niej w Warowni Kamieniołamaczy.', '', 'Wróć do Doradczyni Faili w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(10869, 'koKR', 'Przetrzebić stado', 'Arakkoa znów nas zaatakowali, tym razem uderzając nocą, a potem uciekli za pomocą mrocznej magii, zanim zdążyliśmy zebrać żołnierzy.$B$BZasłona Reskk i Zasłona Shienor leżą na północy i północnym zachodzie. Znajdź te gniazda arakkoa i zabij, ilu tylko zdołasz. Może się nas nie boją, ale przynajmniej przetrzebimy ich szeregi.', 'Porucznik Żwiromłot prosi, żebyś $gzabił:zabiła; 14 szponowców z Shienor i 6 czarowników z Shienor, a potem $gwrócił:wróciła; do niego w Forcie Alleriańskim.', '', '', '', '', '', '', 0),
(10873, 'koKR', 'Porwani w nocy', 'Nasz mały posterunek jest nieustannie atakowany. Kilka nocy temu napadły na nas pająki z Grani Sieci Otchłani, na południowo-wschodnim skraju Kościanych Pustkowi. Otruły wielu naszych, owinęły ich w sieci i uniosły ze sobą. Część naszych wojowników chwyciła za broń i niemal bez przygotowania ruszyła w pościg za pająkami.$B$BOd tamtej pory nie widzieliśmy ani porwanych, ani grup pościgowych. Mamy nadzieję, że niektórzy wciąż żyją, może uwięzieni przez pająki. Jest nas niewielu. Czy odszukasz naszych ludzi?$B', 'Zwiadowca Navrin chce, żebyś $gudał:udała; się na Grań Sieci Otchłani, $guwolnił:uwolniła; 6 oplątanych siecią wojowników Sha\'tar, a potem $gwrócił:wróciła; do niego w Obozie Sha\'tari.', '', 'Wróć do zwiadowcy Navrina w Obozie Sha\'tari na Kościanych Pustkowiach.', 'Uwolniony wojownik Sha\'tar', '', '', '', 0),
(10874, 'koKR', 'Zasłona Shalas: Ogniska sygnałowe', 'Grzęda Terokka, Skettis, góruje nad Kościanymi Pustkowiami na wschodzie. U podnóża Skettis leży Zasłona Shalas, najgroźniejsza z kolonii Terokka. To z twierdzy w Zasłonie Shalas wysunięci mędrcy Terokka prowadzą wojnę przeciw Światłości.$b$bZłoczyńcy z Shalas porozumiewają się ze swoim panem za pomocą złożonego systemu magicznych ognisk sygnałowych. Udaj się na wschód i zgaś te ogniska. Gdy Zasłona Shalas zamilknie, będziemy mogli zacząć planować upadek Skettis.$b$bAle wybiegam zbyt daleko naprzód.', 'Kirrik Przebudzony przy Karawanie Uchodźców chce, żebyś $gzgasił:zgasiła; cztery ogniska sygnałowe w Zasłonie Shalas.', '', 'Wróć do Kirrika Przebudzonego przy Karawanie Uchodźców na Kościanych Pustkowiach.', 'Szafirowe ognisko zgaszone', 'Szmaragdowe ognisko zgaszone', 'Fioletowe ognisko zgaszone', 'Krwawnikowe ognisko zgaszone', 0),
(10877, 'koKR', 'Relikwia grozy', 'Dawno temu pewna karawana wyruszyła do Auchindoun, by zabrać Relikwię grozy ze starożytnych grobowców pod nekropolią. Uciekli z nią, lecz relikwia ich zgubiła. Relikwia jest zła i przyzywa zło, gdy ktoś jej dotknie. Ich karawanę zniszczono gdzieś na wschodzie.$B$BTen mroczny artefakt jest kluczem do strasznego planu pokonania Teribusa Przeklętego, stwora, który lata nad Kościanymi Pustkowiami. Pomóż mi, jeśli chcesz, ale narazisz życie, a nawet duszę.', 'Oakun chce, żebyś $gudał:udała; się na wschód do Porzuconej Karawany i $godzyskał:odzyskała; Relikwię grozy. Po wykonaniu zadania wróć do Oakuna.', '', 'Wróć do Oakuna w Obozie Sha\'tari na Kościanych Pustkowiach.', '', '', '', '', 0),
(10878, 'koKR', 'Zanim zapadnie ciemność', 'Gdy naszą karawanę napadli kabaliści z Rady Cieni, wysłano zwiadowców do Shattrath po pomoc. Strażnicy uważają, że na razie jesteśmy bezpieczni, ale nie doceniają tych szaleńców.$B$BJa w każdym razie nie mam ochoty, żeby jakiś nowicjusz kabalistów poderżnął mi gardło w środku nocy. Zrób nam wszystkim przysługę i uderz na nich, zanim oni przyjdą do nas.$B$BNapastników znajdziesz na południe stąd, przy północnym wejściu do Auchindoun.', 'Mekeda przy Karawanie Uchodźców chce, żebyś $gzabił:zabiła; 8 harcowników kabalistów, 4 tkaczy zaklęć kabalistów i 2 nowicjuszy kabalistów.', '', 'Wróć do Mekedy przy Karawanie Uchodźców na Kościanych Pustkowiach.', '', '', '', '', 0),
(10880, 'koKR', 'Rozkazy kabalistów', 'Wiadomość nosi mroczną pieczęć i choć język wydaje się dość znajomy, tekst wygląda na zaszyfrowany.$B$BMoże ktoś przy Karawanie Uchodźców będzie coś o tym wiedział.', 'Zanieś rozkazy kabalistów Mekedzie przy Karawanie Uchodźców na Kościanych Pustkowiach.', '', '', '', '', '', '', 0),
(10881, 'koKR', 'Grobowiec Cienia', 'Wielu uważa, że to Rada Cieni spowodowała wybuch, który rozdarł Auchindoun. Podobno obudzili w środku wielkie zło.$B$BJeśli to prawda, to zło musiało zwrócić się przeciwko nim. Według tych rozkazów część Rady Cieni ucieka z Auchindoun. Przechowują w Grobowcu Cienia potężne artefakty z Auchindoun.$B$BTrzy z nich są święte, bo należały do potężnych patriarchów: Arunena, K\'alena i Atalora. Muszę cię prosić, żebyś je $godzyskał:odzyskała;.', 'Wejdź do Grobowca Cienia na zachód od Karawany Uchodźców i odzyskaj Opończę Arunena, Młotek K\'alena i Zwój Atalora. Po wykonaniu zadania wróć do Mekedy przy Karawanie Uchodźców.', '', 'Wróć do Mekedy przy Karawanie Uchodźców na Kościanych Pustkowiach.', '', '', '', '', 0),
(10887, 'koKR', 'Ucieczka z grobowca', 'Dziękuję za pomoc, $N. Byłem pewien, że mnie zabiją.$B$BZmywajmy się stąd, i to szybko. Niedługo przyjdą po nas kolejni kultyści.', 'Pomóż Akunowi dotrzeć do Karawany Uchodźców. Po wykonaniu zadania porozmawiaj z Mekedą.', 'Eskortuj Akuna', 'Wróć do Mekedy przy Karawanie Uchodźców na Kościanych Pustkowiach.', '', '', '', '', 0),
(10896, 'koKR', 'Zarażeni obrońcy', 'Drzewa tej krainy ucierpiały od mocy, która wyrwała się z Auchindoun. Plugawa magia, która się wtedy uwolniła, zmieniła ziemię w pustkowia, które widzisz wokół. Drzewa, które przetrwały, są teraz zarażone paskudnymi drzewnymi roztoczami, które wpełzają pod ich korę i wgryzają się w ich ciało.$B$BGnijący leśni szaleńcy i zarażone korzeniochody są wylęgarniami roztoczy. Znajdziesz je na skraju lasu na wschodzie. Zniszcz te stwory, a potem zabij roztocza, które uciekną z ich łupin.', 'Lakotae chce, żebyś $gzabił:zabiła; 25 drzewnych roztoczy, a potem $gwrócił:wróciła; do niego przy Karawanie Uchodźców. Roztocza żyją w ciałach gnijących leśnych szaleńców i zarażonych korzeniochodów.', '', 'Wróć do Lakotae przy Karawanie Uchodźców na Kościanych Pustkowiach.', '', '', '', '', 0),
(10913, 'koKR', 'Niegodny pochówek', 'Czy nic nie powstrzyma tej fali zepsucia? Moi żołnierze od wielu dni walczą z Auchenai i nie widać końca. Każdy poległy, czy to Auchenai, czy Sha\'tar, zostaje porwany z pola bitwy – jego dusza zostaje uniesiona i zabrana w nieznane.$B$BNie pozwolę na to! O godnym pochówku nie ma mowy, ale te potwory nie dostaną ich dusz! Weź tę pochodnię i udaj się na pole bitwy, prosto na wschód stąd. Spal każde ciało, jakie zobaczysz! Nie będziemy podsycać ich rytuałów.', 'Dowódca Ra\'vaj w Posterunku Sha\'tari na Kościanych Pustkowiach w Puszczy Terokkar chce, żebyś $gspalił:spaliła; 8 zabitych wojowników Auchenai i 8 zabitych obrońców Sha\'tar.', '', 'Wróć do dowódcy Ra\'vaja na Kościanych Pustkowiach w Puszczy Terokkar.', 'Spalone zwłoki zabitych obrońców Sha\'tar', 'Spalone zwłoki zabitych wojowników Auchenai', '', '', 0),
(10914, 'koKR', 'Potrzebny bohater', 'To za mało. Potrzebny jest bohater. Nasze siły są przytłoczone, a Auchenai wciąż przybywa.$B$B<Dowódca Ra\'vaj patrzy na ciebie.>$B$BCzy to ty będziesz $gtym bohaterem:tą bohaterką;? Wróć na pole bitwy i uderz na ich żołnierzy. Zajmij ich, żeby moi zwiadowcy mogli przedostać się za ich linie i zobaczyć, co tworzą.', 'Dowódca Ra\'vaj w Posterunku Sha\'tari na Kościanych Pustkowiach w Puszczy Terokkar chce, żebyś $gzabił:zabiła; 12 nowicjuszy Auchenai i 5 proroków zagłady Auchenai.', '', 'Wróć do dowódcy Ra\'vaja na Kościanych Pustkowiach w Puszczy Terokkar.', '', '', '', '', 0),
(10915, 'koKR', 'Upadły egzarcha', 'Karmią skradzionymi duszami trumnę, którą wywlekli z Krypt Auchenai. Moi zwiadowcy sądzą, że w trumnie spoczywa pierwszy egzarcha krypt. Chcą wskrzesić pradawnego!$B$BMusisz przebić się na zachodnią stronę Auchindoun i naruszyć zawartość tej trumny, zanim nakarmią ją dostateczną liczbą dusz. Jeśli zgubisz drogę, idź za wędrującymi duszami.$B$BZniszcz to, co jest w tej trumnie!', 'Dowódca Ra\'vaj w Posterunku Sha\'tari na Kościanych Pustkowiach w Puszczy Terokkar chce, żebyś $gzniszczył:zniszczyła; zawartość trumny Auchenai.', '', 'Wróć do dowódcy Ra\'vaja na Kościanych Pustkowiach w Puszczy Terokkar.', 'Zawartość trumny Auchenai zniszczona', '', '', '', 0),
(10920, 'koKR', 'Za poległych', 'Gdy straszliwokłe wdowy zaatakowały nasz posterunek, usłyszeliśmy głos naaru wzywający nas do walki. Ścigaliśmy te stwory w ciemną noc. Niektórych naszych znaleźliśmy martwych w ciemności, innych słyszeliśmy, jak walczą z porywaczami.$B$BO świcie dotarliśmy w to miejsce i stoczyliśmy zaciekłą bitwę, ale przegraliśmy. Jad straszliwokłych wkrótce zabierze moich towarzyszy, a i ja długo nie wytrzymam. Zanim umrę, muszę wiedzieć, że straszliwokłe wdowy zostały pokonane.', 'Obrońca Haylen chce, żebyś $gzabił:zabiła; 20 straszliwokłych wdów, a potem $gwrócił:wróciła; do niego, tuż na zachód od Grani Sieci Otchłani.', '', 'Wróć do obrońcy Haylena na skraju Grani Sieci Otchłani na Kościanych Pustkowiach.', '', '', '', '', 0),
(10921, 'koKR', 'Terokkarantula', '$GZabiłeś:Zabiłaś; wiele straszliwokłych wdów, ale wciąż będą się lęgnąć i wkrótce znów nas zaatakują. Głęboko w Grani Sieci Otchłani znajduje się leże Terokkarantuli, matki miotu tych ohydnych stworzeń. Jeśli mamy być bezpieczni, ona musi zginąć.', 'Obrońca Haylen chce, żebyś $gzabił:zabiła; Terokkarantulę, a potem $gwrócił:wróciła; do niego na zachód od Grani Sieci Otchłani.', '', 'Wróć do obrońcy Haylena tuż przed Granią Sieci Otchłani na Kościanych Pustkowiach.', '', '', '', '', 0),
(10922, 'koKR', 'Grzebanie w kościach', 'Hej! Wyglądasz na kogoś, kto umie o siebie zadbać. Szukamy z ekipą ochroniarza, który będzie nas pilnował, kiedy ruszymy na wykopalisko na północy. Płacą całkiem nieźle, a ty musisz tylko dopilnować, żeby żadne paskudne stwory nie zabiły mnie ani moich pracowników.$B$BJeśli wrócimy bez strat, Dwarfowitz, o tam, ci zapłaci.', 'Eskortuj Letolla i jego ekipę i chroń ich podczas wykopalisk. Jeśli ci się uda, wróć do Dwarfowitza w Posterunku Sha\'tari.$B', 'Ochroń odkrywców', 'Wróć do Dwarfowitza na Kościanych Pustkowiach w Puszczy Terokkar.', '', '', '', '', 0),
(10923, 'koKR', 'Zło nadciąga', 'Teraz, jeśli chcesz rzucić wyzwanie Teribusowi Przeklętemu, musisz użyć Relikwii grozy w plugawym rytuale nekromanckim. Na północnym wschodzie, za Auchindoun, leży Wijący się Kopiec, miejsce, gdzie zbierają się nekromanci.$B$BMówcy umarłych i prorocy zagłady Auchenai noszą czaszki zagłady nasycone potężnymi zaklęciami nekromanckimi. Jeśli zbierzesz dość czaszek, możesz połączyć ich moc z mocą Relikwii grozy i zmusić Teribusa, by stanął do walki.', 'Oakun chce, żebyś $gzaniósł:zaniosła; Relikwię grozy na Wijący się Kopiec. Na miejscu zabijaj mówców umarłych i proroków zagłady Auchenai, by zebrać 20 czaszek zagłady. Następnie odszukaj Krąg przywołań przy Wijącym się Kopcu i użyj Relikwii grozy, by przywołać i zniszczyć Teribusa Przeklętego. Gdy tego dokonasz, wróć do Oakuna.', '', 'Wróć do Oakuna w Obozie Sha\'tari na Kościanych Pustkowiach.', '', '', '', '', 0),
(10925, 'koKR', 'Zło nadciąga', '', '', '', '', '', '', '', '', 0),
(10926, 'koKR', 'Powrót do Obozu Sha\'tari', 'Sami nie damy rady wrócić. Jad straszliwokłych jest zbyt silny. Musisz za nas wrócić do Obozu Sha\'tari. Zwiadowca Navrin wyśle ekipę ratunkową, która nas odnajdzie.', 'Obrońca Haylen chce, żebyś $gwrócił:wróciła; do Obozu Sha\'tari na Kościanych Pustkowiach i $gporozmawiał:porozmawiała; ze zwiadowcą Navrinem.', '', '', '', '', '', '', 0),
(10929, 'koKR', 'Fumpowanie', 'Może zrobisz coś jeszcze dla Ligi Odkrywców? Te kościane czerwie bardzo nas zaintrygowały.$B$BMam tu bęben, którego możesz użyć na Kościanych Pustkowiach. Po prostu wal w to cholerstwo i zobacz, co wylezie. Jeśli to będzie czerw, zabij go i przynieś nam truchło do zbadania. Potrzebujemy sporo trucheł, żeby mieć wiarygodną próbkę badawczą.', 'Dwarfowitz w Obozie Sha\'tari na Kościanych Pustkowiach chce, żebyś $gprzyniósł:przyniosła; mu 8 trucheł dorosłych kościanych przesiewaczy.', '', 'Wróć do Dwarfowitza na Kościanych Pustkowiach w Puszczy Terokkar.', '', '', '', '', 0),
(10930, 'koKR', 'Wielki kościany czerw', 'Miałem rację! Truchła, które $gprzyniosłeś:przyniosłaś;, należą do młodych kościanych czerwi. Wiesz, co to znaczy? Że gdzieś tam jest duży! Chyba zdołamy go wywabić, jeśli podsuniemy mu odpowiednie jedzenie. Zobaczmy... coś dużego! Tak!$B$BPamiętam, że widziałem rozłupokopyty na wschód stąd, po drugiej stronie Kościanych Pustkowi. Idź tam i zabij rozłupokopyta. Gdy padnie, użyj bębnów. Miejmy nadzieję, że duży wyjdzie się pożywić. Jeśli uda ci się go zabić, przynieś mi jego narządy!', 'Dwarfowitz w Obozie Sha\'tari na Kościanych Pustkowiach chce, żebyś $gzdobył:zdobyła; ogromne narządy kościanego czerwia.$B$BChce też odzyskać swój Dudnik.$B', '', 'Wróć do Dwarfowitza na Kościanych Pustkowiach w Puszczy Terokkar.', '', '', '', '', 0),
(10997, 'koKR', 'Nawet gronnowie mają standardy', 'Znasz Shattrath? Nad nim, na północnym zachodzie, leży miejsce zwane Wzgórzami Bariery, na które można się dostać tylko na latającym wierzchowcu.$B$BJeden z synów Gruula, Slaag, udał się na wygnanie i przejął władzę nad mieszkającymi tam ogrami Gordunni. Choć jest tak daleko, nie możemy zostawić go w spokoju, bo mógłby wrócić, gdy reszta jego braci zostanie zabita.$B$B$N, musisz się tam udać i przynieść jego sztandar na dowód, że się z nim rozprawiono.', 'Zdobądź sztandar Slaaga.', '', 'Wróć do Mog\'dorga Sędziwego na szczycie wieży w Krwawym Kręgu w Górach Klingi.$B', '', '', '', '', 0),
(11004, 'koKR', 'Świat cieni', 'Podniebny dowódca Adaris został ciężko ranny podczas najazdu ze Skettis. Od tamtej pory co chwilę traci przytomność.$B$BObawiam się, że popadł w gorączkowe majaczenie. W krótkich chwilach jasności umysłu żąda, żebym przygotował eliksir z pyłu cienia, który noszą przy sobie arakkoa. Wydaje się wierzyć, że dzięki niemu zajrzy do „świata cieni”, w którym przebywają prawdziwi przywódcy arakkoa.$B$BAni przez chwilę nie wierzę w te bzdury, ale obawiam się, że nie spocznie, dopóki nie zdobędę takiego eliksiru. Pomożesz?', 'Severin chce, żebyś $gwyprawił:wyprawiła; się do Skettis i $gzdobył:zdobyła; 6 porcji pyłu cienia od mieszkających tam arakkoa.', '', 'Wróć do Severina na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11005, 'koKR', 'Sekrety szponokapłanów', 'Dziękuję, że $gwysłuchałeś:wysłuchałaś; moich gorączkowych majaczeń. Przez cały czas próbowaliśmy rozpoznać i zniszczyć dowództwo Skettis; dowiedzieliśmy się o trzech duchownych zwanych szponokapłanami, ale nigdy nie widzieliśmy ich na własne oczy. Teraz wiemy dlaczego.$B$BPorozmawiaj z Severinem, by zdobyć więcej eliksiru, który odkrył. Użyj go, by odnaleźć i zabić trzech szponokapłanów: Ishaala, Skizzika i Zelleka. Podobno przebywają w Zasłonie Ala\'rak, przy wschodnim brzegu Jeziora Czarnego Wiatru.', 'Zdobądź eliksir cieni od Severina i użyj go, by odnaleźć i zabić szponokapłana Ishaala, szponokapłana Skizzika i szponokapłana Zelleka w Skettis. Po wykonaniu zadania wróć do dowódcy Adarisa.', '', 'Wróć do podniebnego dowódcy Adarisa na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11006, 'koKR', 'Więcej pyłu cienia', '', '', '', 'Wróć do Severina na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11008, 'koKR', 'Ogień nad Skettis', 'Myślisz, że masz to, czego trzeba, żeby wstąpić do Podniebnej Straży? Zobaczymy, jak sobie radzisz w powietrzu.$B$BArakkoa hodują gigantyczną odmianę swoich bojowych zwierząt i używają jej przeciwko naszym zwiadowcom. Weź te ładunki wybuchowe i zniszcz nimi wylęgarnie nad siedzibami arakkoa. Unikaj potwornych kaliri, które strzegą wylęgarni. Strącą cię z wierzchowca, zanim się zorientujesz, co cię trafiło.', 'Odszukaj jaja potwornych kaliri na dachach siedzib w Skettis i użyj na nich ładunków wybuchowych Podniebnej Straży. Wróć do podniebnego sierżanta Doryna.', '', 'Wróć do podniebnego sierżanta Doryna na Przystani Czarnego Wiatru w Puszczy Terokkar.', 'Zniszczone jaja potwornego kaliri', '', '', '', 0),
(11021, 'koKR', 'Almanach Ishaala', 'Ten tajemniczy tom miał przy sobie szponokapłan Ishaal. Zawiera tajemne symbole i mapy ciał niebieskich, które przekraczają twoje pojmowanie.$B$BCałość spisano w języku, którego nie rozumiesz – zapewne w starożytnej odmianie pisma arakkoa. Może warto zanieść to podniebnemu dowódcy Adarisowi.', 'Zanieś Almanach Ishaala podniebnemu dowódcy Adarisowi na północ od Skettis.', '', 'Wróć do podniebnego dowódcy Adarisa na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11029, 'koKR', 'Nędzne przebranie', 'Otwórz paczkę, $N. To przebranie. Nie wygląda zbyt przekonująco, prawda?$B$BRobię je dla eterycznych przemytników, którzy szukają rzadkich ksiąg. Na centralnej wyspie Skettis, w Spoczynku Terokka, mieszka skryba arakkoa imieniem Sahaak. Jest stary i prawie ślepy.$B$BW przebraniu porozmawiaj z nim i zdobądź księgę znaną jako Wrogie rody. Uważaj, $N. Przebranie nie oszuka innych arakkoa.', 'Użyj nędznego przebrania arakkoa, by zdobyć od Sahaaka Wrogie rody, i wróć do Hazzika.', '', 'Wróć do Hazzika na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11056, 'koKR', 'Układ Hazzika', 'Nie ściągaj uwagi na naszą rozmowę. Adaris by tego nie pochwalił.$B$BNależę do najniższej kasty arakkoa, $N. Za rządów Terokka złożono by mnie w ofierze mrocznym mocom, którym oddają cześć jego szponokapłani. Jeśli to, co mówisz, jest prawdą i szponokapłani dążą do powrotu Terokka, musisz im w tym przeszkodzić – bez względu na to, co mówi twój przywódca!$B$BMam dla ciebie coś, co ci się przyda. W moim dawnym domu w Górnej Zasłonie Shil\'ak jest paczka. Przynieś mi ją!', 'Zdobądź paczkę Hazzika z jego domu we wschodniej części Skettis i wróć z nią do niego.', '', 'Wróć do Hazzika na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11072, 'koKR', 'Wroga krew', 'W tej księdze wymieniono potomków więzionych przez szponokapłanów Skettis: Gezzarak Łowczynię, kryształowego olbrzyma Karroga, heretyka zwanego Mrocznym Skrzekaczem Akkaraiem i Vakkiza Wściekłego Wichra. Wszyscy muszą zginąć, zanim Terokk powróci na ten świat.$B$BAby ich przywołać w kręgach przywołań w Skettis, potrzebne ci będą zwoje noszone przez zgubionych w czasie arakkoa. Przynieś mi trofeum od każdego z nich. Zmierzysz się z potężnymi istotami; dobrze byłoby zabrać przyjaciół.', 'Odszukaj stosy czaszek pośrodku kręgów przywołań w Skettis. Przywołaj i pokonaj każdego z potomków, używając 10 zgubionych w czasie zwojów przy stosie czaszek. Wróć do Hazzika na Przystani Czarnego Wiatru z trofeum od każdego z nich.', '', 'Wróć do Hazzika na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11073, 'koKR', 'Upadek Terokka', 'Ja... przymykałem oko na twoje układy z więźniem arakkoa, $N. Wygląda na to, że instynkt, który podpowiadał ci współpracę z nim, cię nie zawiódł.$B$BMusisz zrozumieć... W moim obecnym stanie groziłby mi bunt, gdybym poparł twoje starania o sprowadzenie Terokka na ten świat.$B$BWeź przedmioty, które przygotował dla ciebie Hazzik, i realizuj swój plan. Rozkażę moim ludziom, by cię wsparli, gdy nadejdzie czas. Radzę ci też zebrać własny oddział. Obawiam się, że będziesz mieć tylko jedną szansę.', 'Zanieś zgubioną w czasie ofiarę przygotowaną przez Hazzika do stosu czaszek w centrum Skettis, przywołaj Terokka i go pokonaj. Po wykonaniu zadania wróć do podniebnego dowódcy Adarisa.', '', 'Wróć do podniebnego dowódcy Adarisa na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11074, 'koKR', 'Trofea potomków', 'W tej księdze wymieniono potomków więzionych przez szponokapłanów Skettis. To Gezzarak Łowczyni, kryształowy olbrzym Karrog, heretyk zwany Mrocznym Skrzekaczem Akkaraiem i Vakkiz Wściekły Wicher. Wszyscy muszą zginąć, zanim Terokk powróci na ten świat.$B$BBędą ci potrzebne zwoje noszone przez zgubionych w czasie arakkoa – spal je w kręgach przywołań w całym Skettis. Przynieś mi trofeum od każdego z nich. Zmierzysz się z potężnymi istotami; dobrze byłoby zabrać przyjaciół.', 'Zbierz zgubione w czasie zwoje od zgubionych w czasie arakkoa w Skettis i zanieś je do stosu czaszek w jednym z kręgów przywołań w Skettis. Przywołaj i pokonaj potomków wrogów Terokka, a potem wróć do Hazzika ze szponami Akkaraia, kręgosłupem Karroga, łuską Vakkiza i pazurami Gezzarak.', '', 'Wróć do Hazzika na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11085, 'koKR', 'Ucieczka ze Skettis', 'Witaj, $N. Dziękuję, że $gprzybyłeś:przybyłaś; mi na ratunek.$B$BPodczas zwiadu potworne ptaszyska arakkoa strąciły mnie z płaszczki Otchłani.$B$BWynośmy się stąd, póki możemy.', 'Eskortuj więźnia Podniebnej Straży w bezpieczne miejsce i zamelduj się u podniebnego sierżanta Doryna.', 'Uratuj więźnia Podniebnej Straży.', 'Wróć do podniebnego sierżanta Doryna na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0),
(11093, 'koKR', 'Głodne płaszczki Otchłani', 'Płaszczki Otchłani są zaskakująco lojalne i posłuszne, jeśli się je odpowiednio wytresuje. Niestety wojna ze Skettis daje im się we znaki.$B$BLatamy dziesiątki wypadów dziennie – biedaczki rzadko mają chwilę wytchnienia. A przy ostatnich brakach paszy, jeśli nie zabiją ich na misji ci przeklęci ptakoludzie, to wykończy je głód.$B$BJeśli możesz pomóc, zabierz jedną z naszych płaszczek do lasu na południu. Nie pogardzą mięsem ścigacza wypaczenia, byle było świeżo upolowane.', 'Użyj klatki płaszczki Otchłani w lesie na południe od Przystani Czarnego Wiatru i zabijaj ścigacze wypaczenia Czarnego Wiatru w pobliżu głodnej płaszczki Otchłani. Po wykonaniu zadania wróć do tresera Podniebnej Straży Deesaka.', '', 'Wróć do tresera Podniebnej Straży Deesaka na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', 'Posiłek płaszczki Otchłani', '', '', 0),
(11505, 'koKR', 'Duchy Auchindoun', 'Duchy Auchindoun nie mają żadnego interesu w konflikcie między Przymierzem a Hordą, ale zyskanie ich przychylności da naszej stronie przewagę w tym regionie.$B$BZgodnie z pradawnym zwyczajem żywi oddają cześć zmarłym przy wieżach duchów na Kościanych Pustkowiach – choć tylko o określonych porach dnia. Jeśli pomożesz zająć wieżę w tych porach, przyczynisz się do przeciągnięcia duchów na naszą stronę.$B$BJeśli zdobędziemy przychylność duchów, obdarzą nas łaską, która wesprze nasze starania.', 'Pomóż Przymierzu zająć wieżę na Kościanych Pustkowiach.', 'Zajmij Wieżę Duchów', 'Wróć do egzorcysty Sullivana w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', 0),
(11506, 'koKR', 'Duchy Auchindoun', 'Draenei mogą być naszymi wrogami, ale duchy ich przodków w Auchindoun są niespokojne i nikomu nie są wierne.$B$BZwyczaj nakazywał draenei oddawać cześć zmarłym przy wieżach duchów o różnych porach dnia. Jeśli pomożesz zająć wieżę w tych porach, pomożesz duchom Auchindoun odzyskać spokój.$B$BPrzymierze będzie próbowało zająć wieże, by zyskać przychylność zmarłych. Musimy dopilnować, żeby to nasza strona odniosła sukces.', 'Pomóż Hordzie zająć Wieżę Duchów na Kościanych Pustkowiach.', 'Zajmij Wieżę Duchów', 'Wróć do egzorcystki Vaishy w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', 0),
(11520, 'koKR', 'Odkryj swoje korzenie', 'Witaj.$b$bObawiam się, że niewiele mogę ci zaoferować, dopóki nie uzupełnię zapasów odczynników.$b$bWśród potrzebnych mi materiałów jest specjalny odczynnik, korzeń Brzytwocierni, który szczególnie trudno zebrać.$b$bNa szczęście znam pewien sekret...$b$bZa pomocą gruczołów obdzieraczy Brzytwocierni można przejąć kontrolę nad tamtejszym pustoszycielem i kazać mu odsłonić korzeń.$b$bAby znaleźć korzenie, udaj się na Rubież i leć na północny wschód od Shattrath, aż dotrzesz do Wzniesienia Brzytwocierni.', 'Mar\'nah w Porcie Słonecznego Zasięgu chce, żebyś $gudał:udała; się na Wzniesienie Brzytwocierni na Rubieży, $gzebrał:zebrała; 5 korzeni Brzytwocierni i $gwrócił:wróciła; do niej.', '', 'Wróć do Mar\'nah w Porcie Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11521, 'koKR', 'Powrót do korzeni', 'Na razie mam dość zapasów, ale będę potrzebować mnóstwa korzeni Brzytwocierni, by nadążyć z popytem.$b$bZbieranie korzeni jest trudne, ale znam specjalną metodę ich wydobycia.$b$bZa pomocą gruczołów obdzieraczy Brzytwocierni można przejąć kontrolę nad tamtejszym pustoszycielem i kazać mu odsłonić korzeń.$b$bAby znaleźć korzenie, udaj się na Rubież i leć na północny wschód od Shattrath, aż dotrzesz do Wzniesienia Brzytwocierni.$b$bWróć do mnie, $n, gdy zbierzesz pięć korzeni.', 'Mar\'nah w Porcie Słonecznego Zasięgu chce, żebyś $gudał:udała; się na Wzniesienie Brzytwocierni na Rubieży, $gzebrał:zebrała; 5 korzeni Brzytwocierni i $gwrócił:wróciła; do niej.', '', 'Wróć do Mar\'nah w Porcie Słonecznego Zasięgu na Wyspie Quel\'Danas.', '', '', '', '', 0),
(11665, 'koKR', 'Krokoliszki w mieście', 'Witaj, $gchłopcze:dziewczyno;. Cieszę się, że $gwpadłeś:wpadłaś; pogadać ze starym człowiekiem – w domu są kłopoty.$b$bWędrowny kupiec sprzedał niedawno partię młodych krokoliszków kilku łatwowiernym dzieciakom. Krokoliszki to dzikie zwierzęta, więc wiele z nich uciekło i teraz czai się w miejskich kanałach.$b$bWeź swoją najmocniejszą wędkę, zarzuć ją w Wichrogrodzie albo Orgrimmarze i przynieś mi jednego z tych małych diabłów. Nie mogę się doczekać, żeby go zobaczyć.', 'Przynieś młodego krokoliszka Staremu Barlowi. Znajdziesz go przy wędkowaniu na północny wschód od Shattrath, nad Jeziorem Silmyr.', '', 'Wróć do Starego Barla nad Jeziorem Silmyr w Puszczy Terokkar.', '', '', '', '', 0),
(11666, 'koKR', 'Złodzieje przynęty', 'Pewnie wiesz wszystko o złotym strzelczyku – jest dość pospolity w rzekach Puszczy Terokkar i uchodzi za przysmak kapłanów. Ale o tym na pewno nie $gsłyszałeś:słyszałaś;: czarnopłetwy strzelczyk.$b$bTa ryba słynie z przebiegłości i trudno ją złowić. Musisz zaciąć w ostatniej możliwej chwili, bo najpierw skubie przynętę, a dopiero potem ją połyka.$b$bZarzuć wędkę w rzekach Terokkar i przynieś mi czarnopłetwego strzelczyka. Omijaj jeziora, bo czarnopłetwe dobrze się mają tylko w płynącej wodzie.', 'Przynieś czarnopłetwego strzelczyka Staremu Barlowi. Znajdziesz go przy wędkowaniu na północny wschód od Shattrath, nad Jeziorem Silmyr.', '', 'Wróć do Starego Barla nad Jeziorem Silmyr w Puszczy Terokkar.', '', '', '', '', 0),
(11667, 'koKR', 'Ta, co się urwała', 'Błotniarka Figlustera to zaskakująco szybka ryba denna, żyjąca w wodach Nagrandu. Rośnie przez całe życie i słynie z tego, że zawzięcie walczy.$b$bLata temu złowiłem największą błotniarkę na świecie – jestem tego pewien... ale zerwała żyłkę i uciekła.$b$bKomuś, kto łowi tak dobrze jak ty, nie trzeba mówić, co robić – twoje przeznaczenie czeka w jeziorach Nagrandu.', 'Złów największą błotniarkę świata i przynieś ją Staremu Barlowi. Znajdziesz go przy wędkowaniu na północny wschód od Shattrath, nad Jeziorem Silmyr.', '', 'Wróć do Starego Barla nad Jeziorem Silmyr w Puszczy Terokkar.', '', '', '', '', 0),
(11668, 'koKR', 'Z krewetkami nie ma lekko', 'W jeziorach Moczarów Zangarskich pływa mnóstwo dużych ryb. $GZastanawiałeś:Zastanawiałaś; się kiedyś, co jedzą?$b$bKrewetki. Olbrzymie krewetki słodkowodne. Rokk mówi, że dań z krewetek jest prawie nieskończenie wiele.$b$bAle krewetki są za małe, żeby łowić je na wędkę. Więc sztuczka jest taka: rozetnij rozdętego pstrąga kolczastoskrzelnego, a jak dopisze ci szczęście, znajdziesz w środku krewetkę czy dwie.', 'Przynieś 10 olbrzymich krewetek słodkowodnych Staremu Barlowi. Znajdziesz go przy wędkowaniu na północny wschód od Shattrath, nad Jeziorem Silmyr.', '', 'Wróć do Starego Barla nad Jeziorem Silmyr w Puszczy Terokkar.', '', '', '', '', 0),
(11669, 'koKR', 'Filet z lucjana spaczonej krwi', 'Ten staruszek wkrótce wybiera się na polowanie. Zamierzam upolować rekina mamuciego u wybrzeży Aszary.$b$bRzecz w tym, że potrzebuję trucizny, która utrzyma się na grocie włóczni pod wodą. Żeby zrobić coś takiego, potrzebuję gruczołów trującej ryby: lucjana spaczonej krwi.$b$bTa podła ryba dobrze się ma tylko w wodach Półwyspu Piekielnego Ognia i Doliny Cienistego Księżyca. Przynieś mi prawdziwego olbrzyma, a będę szczęśliwym staruszkiem.', 'Przynieś potwornego lucjana spaczonej krwi Staremu Barlowi. Znajdziesz go przy wędkowaniu na północny wschód od Shattrath, nad Jeziorem Silmyr.', '', 'Wróć do Starego Barla nad Jeziorem Silmyr w Puszczy Terokkar.', '', '', '', '', 0),
(11885, 'koKR', 'Wroga krew', 'W tej księdze wymieniono potomków więzionych przez szponokapłanów Skettis: Gezzarak Łowczynię, kryształowego olbrzyma Karroga, heretyka zwanego Mrocznym Skrzekaczem Akkaraiem i Vakkiza Wściekłego Wichra. Wszyscy muszą zginąć, zanim Terokk powróci na ten świat.$B$BAby ich przywołać w kręgach przywołań w Skettis, potrzebne ci będą zwoje noszone przez zgubionych w czasie arakkoa. Zmierzysz się z potężnymi istotami; dobrze byłoby zabrać przyjaciół.', 'Odszukaj stosy czaszek pośrodku kręgów przywołań w Skettis. Przywołaj i pokonaj każdego z potomków, używając 10 zgubionych w czasie zwojów przy stosie czaszek. Wróć do Hazzika na Przystani Czarnego Wiatru.', '', 'Wróć do Hazzika na Przystani Czarnego Wiatru w Puszczy Terokkar.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9888, 'koKR', '<Kilrath mówi przyciszonym głosem.>$B$BTe ogry są wyjątkowo osobliwe. I wyjątkowo głupie. Popatrz, jak ten gruby każe tańczyć tym, hm, mniej grubym. To hipnotyzujące.', 0),
(9889, 'koKR', 'Daruj mi życie, a powiem ci wszystko, co chcesz wiedzieć!', 0),
(9890, 'koKR', 'Zwolnij, $N. Jestem tylko skromnym łotrzykiem. Nie mam pojęcia, co zrobić z takimi informacjami.', 0),
(9891, 'koKR', 'Czyli uważają, że mają prawo przepędzać i wyrzynać orków, kiedy przyjdzie im ochota, co? Pewnie nie miało to nic wspólnego z tym, że nasz przywódca to bezsilny szczeniak... Gdyby tylko miał choć ułamek zapału swojego ojca...', 0),
(9929, 'koKR', 'Wśród szczątków wozu kupca i jego towarów widać odciski dziwnych stóp. Wyglądają, jakby zostawił je jakiś przerośnięty ptak.$BPrzypominając sobie, co wiesz o arakkoa, dochodzisz do wniosku, że ślad jest dość duży, by należał do jednego z rozumnych ptasich ludzi zamieszkujących puszczę. Dlaczego mieliby zacząć napadać na kupców Hordy?', 0),
(9930, 'koKR', 'Wśród szczątków wozu kupca i jego towarów widać odciski dziwnych stóp. Wyglądają, jakby zostawił je jakiś przerośnięty ptak.$BPrzypominając sobie, co wiesz o arakkoa, dochodzisz do wniosku, że ślad jest dość duży, by należał do jednego z rozumnych ptasich ludzi zamieszkujących puszczę. Dlaczego mieliby zacząć napadać na kupców Przymierza?', 0),
(9941, 'koKR', 'Przyglądając się napisom na workach, odczytujesz imię Deiroma. Arakkoa najwyraźniej zależało na ładunku kupca na tyle, że zabrali go od wozu – ale gdzie jest zaginiony kupiec?', 0),
(9942, 'koKR', 'Przyglądając się napisom na workach, odczytujesz imię Dugara. Arakkoa najwyraźniej zależało na ładunku kupca na tyle, że zabrali go od wozu – ale gdzie jest zaginiony kupiec?', 0),
(9943, 'koKR', '<Thander kiwa głową, gdy opowiadasz mu, co $gznalazłeś:znalazłaś; w osadzie arakkoa.>$BA więc nie ma wątpliwości, że to ich sprawka. Ale dlaczego?$BDeirom od dawna jeździ do Shattrath bez żadnych przygód. Czemu arakkoa postanowili pojmać go właśnie podczas tej podróży?', 0),
(9947, 'koKR', '<Rokag kiwa głową, gdy opowiadasz mu, co $gznalazłeś:znalazłaś; w osadzie arakkoa.>$BA więc nie ma wątpliwości, że to ich sprawka. Ale dlaczego?$BDugar od dawna jeździ do Shattrath bez żadnych przygód. Czemu arakkoa postanowili pojmać go właśnie podczas tej podróży?', 0),
(9949, 'koKR', 'Dziwne, te oczy nie całkiem przypominają to, z czym zwykle pracuję. Arakkoa posługują się magią nieco inaczej niż my.$B$BWygląda na to, że będzie potrzebna jeszcze jedna rzecz, jeśli mam wywróżyć, gdzie szukać Deiroma.', 0),
(9950, 'koKR', 'Dziwne, te oczy nie całkiem przypominają to, z czym zwykle pracuję. Arakkoa posługują się magią nieco inaczej niż my.$B$BWygląda na to, że będzie potrzebna jeszcze jedna rzecz, jeśli mam wywróżyć, gdzie szukać Dugara.', 0),
(9951, 'koKR', 'Tak będzie najlepiej, naprawdę. Skoro nie potrafi grzecznie przyjąć zaproszenia, to nie ma tu czego szukać.$B$B<Strażnik Treelos przez chwilę wygląda na zdezorientowanego.>$B$BKim jesteś i co tu robisz? Musisz szybko stąd uciekać, zanim będzie za późno!', 0),
(9952, 'koKR', 'No, znam Zasłonę Shalas. Paskudne miejsce. Ale skoro trzymają tam twojego przyjaciela, to chyba będziemy musieli znaleźć sposób na obejście ich zabezpieczeń.', 0),
(9953, 'koKR', 'Zasłona Shalas panuje nad tymi stronami. Skoro trzymają tam twojego przyjaciela, to chyba będziemy musieli znaleźć sposób na obejście ich zabezpieczeń.', 0),
(9958, 'koKR', 'Ich obrona jest dużo bardziej wyrafinowana, niż sądziłem, $N. To zły znak. Na szczęście na każde dobre zaklęcie jest przeciwzaklęcie. Chodzi tylko o to, żeby je zdobyć.', 0),
(9959, 'koKR', 'Ich obrona jest dużo bardziej wyrafinowana, niż sądziłem, $N. To zły znak. Na szczęście na każde dobre zaklęcie jest przeciwzaklęcie. Chodzi tylko o to, żeby je zdobyć.', 0),
(9960, 'koKR', 'Dobrze, że Warownia Kamieniołamaczy cię przysłała. Druidzi z gąszczu zostali wymordowani! Przeżyłem tylko ja i jeszcze jeden, który postradał zmysły.$B$BNie wiem, co się stało, ale zamierzam dojść do sedna sprawy. Cokolwiek to było, stało się szybko i wydaje się nienaturalne.$B$BPomożesz mi?', 0),
(9961, 'koKR', 'Dobrze, że Warownia Kamieniołamaczy cię przysłała. Druidzi z gąszczu zostali wymordowani! Przeżyłem tylko ja i jeszcze jeden, który postradał zmysły.$B$BNie wiem, co się stało, ale zamierzam dojść do sedna sprawy. Cokolwiek to było, stało się szybko i wydaje się nienaturalne.$B$BPomożesz mi?', 0),
(9968, 'koKR', 'Dziwne. Próbki okrutnej teroćmy są nasycone czymś, co wydaje mi się czystą maną.$B$BWygląda na to, że cokolwiek sprowadziło całą tę śmierć, pozostawiło też silne pole szczątkowej energii. Ale z jakiegoś powodu teroćmy od niego nie zginęły, tylko wpadły w stan pobudzenia.$B$BWydaje się oczywiste, że ta dziwna energia jest produktem ubocznym tego, co zaatakowało gąszcz.', 0),
(9969, 'koKR', 'Doskonale. To potrwa tylko chwilkę.', 0),
(9971, 'koKR', 'A więc miałem rację. To były zwłoki jednego ze Złamanych? I potwierdzasz, że obok niego na ziemi leżał dziwny przedmiot?$B$BTo nie ma sensu. Co Złamany miałby tu robić? I czym jest ta rzecz, którą miał przy sobie?$B$BCzy to ona sprowadziła całą tę śmierć?', 0),
(9974, 'koKR', 'Doskonale. To potrwa tylko chwilkę.', 0),
(9975, 'koKR', 'Jeśli zaklęcie z talizmanu zadziałało, możesz już wyruszyć do Zasłony Shalas. Mam nadzieję, że twój mędrzec arakkoa mówił prawdę, twierdząc, że jego magia jest silniejsza od tej osłony. Jeśli nas zwodzi, i ty, i Deirom macie kłopoty.', 0),
(9976, 'koKR', 'Jeśli zaklęcie z talizmanu zadziałało, możesz już wyruszyć do Zasłony Shalas. Mam nadzieję, że twój mędrzec arakkoa mówił prawdę, twierdząc, że jego magia jest silniejsza od tej osłony. Jeśli nas zwodzi, i ty, i Dugar macie kłopoty.', 0),
(9978, 'koKR', 'Dobra, dobra... Powiem ci, co wiem, ale to niewiele!', 0),
(9980, 'koKR', 'Muszę przyznać, $N, że jestem mile zaskoczona. Kiedy Thander powiedział mi, że Deirom jest więziony w Zasłonie Shalas, zaczęłam się zastanawiać, czy nie straciliśmy go na dobre.$B$BTym razem bardzo się cieszę, że się myliłam.$B$BMożesz być $gpewien:pewna;, że od tej pory będziemy uważniej patrzeć arakkoa na ręce.', 0),
(9981, 'koKR', 'Muszę przyznać, $N, że jestem zaskoczony. Kiedy się dowiedzieliśmy, że Dugar jest więziony w Zasłonie Shalas, zacząłem się zastanawiać, czy nie straciliśmy go na dobre.$B$BTym razem cieszę się, że się myliłem.$B$BMożesz być $gpewien:pewna;, że od tej pory będziemy uważniej patrzeć arakkoa na ręce.', 0),
(9984, 'koKR', 'Większość z tego potrafię odczytać, dość, by zrozumieć ogólny sens. Ktokolwiek to napisał, chwali „postępy” Luangi i zachęca go do dalszego przesłuchiwania jego „gości”.$b$bJednocześnie pisze, że „przygotowania w Skettis przebiegają zgodnie z planem” i że wkrótce „będą gotowi odzyskać ziemie przodków”.$b$bNie wiem, czym jest to „Skettis”, o którym pisze autor, ale gdziekolwiek to jest, wygląda na to, że arakkoa gromadzą tam armię! Trzeba natychmiast powiadomić o tym Thandera.', 0),
(9985, 'koKR', 'Większość z tego potrafię odczytać, dość, by zrozumieć ogólny sens. Ktokolwiek to napisał, chwali „postępy” Luangi i zachęca go do dalszego przesłuchiwania jego „gości”.$b$bJednocześnie pisze, że „przygotowania w Skettis przebiegają zgodnie z planem” i że wkrótce „będą gotowi odzyskać ziemie przodków”.$b$bNie wiem, czym jest to „Skettis”, o którym pisze autor, ale gdziekolwiek to jest, wygląda na to, że arakkoa gromadzą tam armię! Trzeba natychmiast powiadomić o tym Rokaga.', 0),
(9986, 'koKR', 'Dobra robota, $N. Mamy dość zmartwień i bez zastanawiania się, kiedy arakkoa znów napadną na naszych kupców i posłańców.', 0),
(9987, 'koKR', 'Dobra robota, $N. Mamy dość zmartwień i bez zastanawiania się, kiedy arakkoa znów napadną na naszych kupców i posłańców.', 0),
(9988, 'koKR', 'Nadadzą się, choć jestem pewna, że chłopcy niedługo zaczną narzekać na brak różnorodności. Niech Światłość broni, żeby wyglądali tak samo!$B$B<Ros\'eleth udaje przerażenie.>$B$BO nie, do tego nie możemy dopuścić!', 0),
(9989, 'koKR', 'Świetnie się nadadzą. Im od większej liczby arakkoa je $gzebrałeś:zebrałaś;, tym bardziej mi pomogą, gdy spróbuję nawiązać kontakt z duchami arakkoa. Dziękuję za pomoc, $N.', 0),
(9992, 'koKR', 'Dziękuję, że $gprzyniosłeś:przyniosłaś; te nasiona. Mam już prawie dość, żeby wysłać pierwszą partię!', 0),
(9993, 'koKR', 'Dobry początek, ale będzie nam potrzeba więcej, jeśli mamy wytłoczyć porządną ilość oleju!', 0),
(9994, 'koKR', 'O nie! To straszne wieści! Nie mogę uwierzyć, że nie żyją wszyscy nasi przyjaciele z Kręgu Cenariona poza dwoma.$B$BDobrze, pokaż mi te części. Mam tylko nadzieję, że to nie jest to, co podejrzewam.$B$BTak, jak się obawiałam, to chyba części bomby. Nasze oczy i uszy w Shattrath donoszą nam, że niektórzy eterycy sprowadzają zakazane towary z innych wymiarów, z którymi utrzymują kontakt.', 0),
(9995, 'koKR', 'O nie! To straszne wieści! Nie mogę uwierzyć, że nie żyją wszyscy nasi przyjaciele z Kręgu Cenariona poza dwoma.$B$BDobrze, pokaż mi te części. Mam tylko nadzieję, że to nie jest to, co podejrzewam.', 0),
(9996, 'koKR', 'Dobry początek, ale sądząc po tym, co $gwidziałeś:widziałaś; tam na dziedzińcu, i po informacjach, które do mnie dotarły, mamy na głowie znacznie pilniejszą sprawę!', 0),
(9997, 'koKR', 'Dobry początek, ale sądząc po tym, co $gwidziałeś:widziałaś; tam na dziedzińcu, i po informacjach, które do mnie dotarły, mamy na głowie znacznie pilniejszą sprawę!', 0),
(9998, 'koKR', '<Wysoka elfka kiwa głową.>$B$BTo dobry początek, ale Bertelm słusznie przysłał cię do mnie. Dokonałam odkrycia, które może wyjaśnić obecność spaczonych orków w tej okolicy.', 0),
(10000, 'koKR', 'Obawiam się, że do powstrzymania spaczonych orków nie wystarczy samo nękanie ich robotników. Dokonałem odkrycia, które rzuca nieco światła na powód ich obecności tutaj, i utwierdziło mnie ono w przekonaniu, że musimy działać szybko.', 0),
(10002, 'koKR', '<Theloria kiwa ci głową.>$B$BDobra robota. Zyskaliśmy trochę czasu. Krwawe elfy zaczną się zastanawiać, co się stało z ich przyjaciółką. Miejmy nadzieję, że do tego czasu lepiej zrozumiemy ich zamiary.', 0),
(10003, 'koKR', '<Kaide kiwa ci głową.>$B$BDobra robota. Zyskaliśmy trochę czasu. Krwawe elfy zaczną się zastanawiać, co się stało z ich przyjaciółką. Miejmy nadzieję, że do tego czasu lepiej zrozumiemy ich zamiary.$B$BGdy przyjdzie pora, powiadomię Rokaga o naszych postępach.', 0),
(10005, 'koKR', 'Bomba wykorzystująca czystą manę, zdolna zmieść z powierzchni ziemi całe miasta! Ale dlaczego? Czemu krwawe elfy miałyby stworzyć coś takiego i użyć tego przeciw nam? Gąszcz Cenariona był miejscem pokoju i wytchnienia.$B$BJakikolwiek był powód, musi być zamknięty w głowie Strażnika Treelosa, a ja nie mam pojęcia, jak go wyleczyć. Może jego umysł z czasem się zagoi?$B$BTak czy inaczej, chcę ci podziękować za pomoc w wyjaśnieniu, co się stało. Mogę tylko mieć nadzieję, że taka tragedia już nigdy nikogo nie spotka!', 0),
(10006, 'koKR', 'Bomba wykorzystująca czystą manę, zdolna zmieść z powierzchni ziemi całe miasta! Ale dlaczego? Czemu krwawe elfy miałyby stworzyć coś takiego i użyć tego przeciw nam? Gąszcz Cenariona był miejscem pokoju i wytchnienia.$B$BJakikolwiek był powód, musi być zamknięty w głowie Strażnika Treelosa, a ja nie mam pojęcia, jak go wyleczyć. Może jego umysł z czasem się zagoi?$B$BTak czy inaczej, chcę ci podziękować za pomoc w wyjaśnieniu, co się stało. Mogę tylko mieć nadzieję, że taka tragedia już nigdy nikogo nie spotka!', 0),
(10007, 'koKR', 'Sytuacja zaczyna się poprawiać. Myślę, że jeśli nie dopuścimy, by do spaczonych orków dotarły tu posiłki, utrzymamy ten posterunek w ryzach.', 0),
(10008, 'koKR', 'Wiem, że dużo $gpodróżowałeś:podróżowałaś;, ale zrozum, $N, niektóre historie najlepiej zostawić tam, gdzie się wydarzyły. Rozumiemy się?', 0),
(10012, 'koKR', '<Bertelm bierze od ciebie plany i przegląda je.>$B$BGdybyś nie $gprzyniósł:przyniosła; tej mapy, powiedziałbym, że $gpostradałeś:postradałaś; rozum, ale oto jest, czarno na białym. Spaczone orki nie tylko służą tu krwawym elfom, ale najwyraźniej mają też rozkaz zajmować nas sobą.$B$BTa mapa rodzi więcej pytań, niż daje odpowiedzi, ale lepiej teraz wiemy, z czym mamy tu do czynienia.', 0),
(10013, 'koKR', '<Rokag bierze od ciebie plany i przegląda je.>$B$BA więc Kaide miał rację! Te spaczone orkowe szumowiny coś knują. Nigdy bym jednak nie zgadł, że zmówiły się z krwawymi elfami.$B$BWedług tej mapy spaczone orki mają nas czymś zająć... ale po co? To niepokojące wieści, $N. Dobrze $gzrobiłeś:zrobiłaś;, że od razu mi je $gprzyniosłeś:przyniosłaś;.', 0),
(10014, 'koKR', 'Dobra robota!$B$BPokaż mi te arkusze kodów. Mam pomysł, który może być na tyle szalony, że się uda!', 0),
(10015, 'koKR', 'Dobra robota!$B$BPokaż mi te arkusze kodów. Mam pomysł, który może być na tyle szalony, że się uda!', 0),
(10016, 'koKR', 'Ach, dobra robota, przyjacielu. Są piękniejsze, niż się spodziewałem. Będzie z nich wspaniały płaszcz.$B$B<Bertelm zerka w stronę gospody.>$B$BTak, to będzie wspaniały płaszcz.', 0),
(10018, 'koKR', 'Są doskonałe, $N! Nie mógłbym prosić o lepsze.', 0),
(10022, 'koKR', 'Chylę czoła przed twoimi umiejętnościami, $N. $GOkazałeś:Okazałaś; się lepszym łowcą.$B$BNie zapomnę ci pomocy przy tym płaszczu. Będzie naprawdę jedyny w swoim rodzaju i będę go nosił z dumą.', 0),
(10023, 'koKR', 'Ta skóra jest jeszcze wspanialsza, niż się spodziewałem! To dobry znak, $N, a duchy będą ci sprzyjać za twój wkład w tę ceremonię.$B$BZ pozostałych skór zrobiłem dla ciebie hełm, $N. Oznacza cię jako potężnego łowcę i sojusznika wielkiego wilczego ducha Puszczy Terokkar.', 0),
(10026, 'koKR', '<Andarl ociera czoło rękawem szaty.>$B$BChwała niebiosom. Zaczynałem się już zastanawiać, czy te stwory nie wyparły z puszczy wszystkich innych stworzeń.', 0),
(10027, 'koKR', 'Keb\'ezilowi ulżyło, że $gzająłeś:zajęłaś; się tym drobnym problemem, prawda, Keb?$B$B<Chochlik ignoruje swojego pana, zapewne z oburzenia.>$B$BMusisz mu wybaczyć złe maniery. Wiesz, jakie potrafią być demony...', 0),
(10028, 'koKR', 'Mam nadzieję, że to nie jedyne nienaruszone naczynia w mieście. To dobry początek, ale podejrzewam, że będziemy potrzebować znacznie więcej.', 0),
(10030, 'koKR', 'Świetnie, tego mi było trzeba... więcej kości.$B$B<Ramdor wzdycha.>$B$BTak, tak, dopilnuję, żeby te szczątki naszych czcigodnych przodków zostały godnie pochowane, nie obawiaj się.$B$BJest jeszcze coś, co możesz zrobić, jeśli naprawdę chcesz pomóc zmarłym.', 0),
(10031, 'koKR', '$GZrobiłeś:Zrobiłaś; to, co trzeba było zrobić, i nie ma czego wybaczać. Choć smuci mnie wieść, że zostały splugawione i obrócone w straszliwe nieżycie, twoje czyny pozwoliły im spocząć.$B$BDziękuję, że je $guwolniłeś:uwolniłaś;, $N. Musisz przyjąć skromny dowód mojego uznania dla ciebie i twojej bezinteresowności.', 0),
(10033, 'koKR', 'Jasne, na pewno $gzabiłeś:zabiłaś; wszystkie te kościosmagacze. To oczywiste, skoro kapitan kazał ci przynieść dowód z tego listu gończego.$B$B<Taela rzuca ci sarkastyczne spojrzenie.>$B$BWierzę ci na słowo. Nie wiem, komu się naraziłam, że dostałam tę służbę, ale dzięki za twój wysiłek dla Przymierza. Masz tu drobiazg za wszystkie trudy.', 0),
(10034, 'koKR', '$gMusiałeś:Musiałaś; zabić mnóstwo tych kościosmagaczy! Dobrze, nienawidzę ich! Odkąd jeden mnie ugryzł, ciągle mdleję.$B$BWiesz, jakie to upokarzające? Masz, weź to w podzięce za to, że trochę mnie $gpomściłeś:pomściłaś;.', 0),
(10035, 'koKR', 'No, no, $N, jestem pod wrażeniem. Torgos był jednym z najtwardszych stworzeń, jakie znam po tej stronie Nagrandu.$B$BCóż, to chyba wystarczy na coś ze skarbca Fortu Alleriańskiego. Wybierz sobie.', 0),
(10036, 'koKR', 'Dziękuję ci, $N! $GPomściłeś:Pomściłaś; mnie i zgodnie z obietnicą dostaniesz nagrodę!$B$BWybierz sobie jedną z tych rzeczy i dobrze jej używaj!', 0),
(10039, 'koKR', 'Najwyższy czas, żeby ktoś się tu zjawił. Wysłałam ten meldunek do Warowni Kamieniołamaczy ponad tydzień temu!$B$BKrwawe elfy i ta ich biurokracja!', 0),
(10043, 'koKR', 'To niepomyślne wieści! Ale oczywiście słusznie zrobiłam, wysyłając cię na pomoc Neftis. Ostatnie, czego nam trzeba, to Rada Cieni urządzająca sobie twierdzę tuż pod naszym progiem!$B$B$N, $gzasłużyłeś:zasłużyłaś; na coś ładnego. Śmiało, wybierz sobie.', 0),
(10048, 'koKR', 'Wygląda na to, że masz wszystko, czego nam trzeba. Za chwilę będę gotów zaczynać.$B$BNie mogę zagwarantować, że wymyślę coś użytecznego, ale spróbuję wywróżyć, dokąd arakkoa zabrali Deiroma.', 0),
(10049, 'koKR', 'Wygląda na to, że masz wszystko, czego nam trzeba. Za chwilę będę gotów zaczynać.$B$BNie mogę zagwarantować, że wymyślę coś użytecznego, ale spróbuję wywróżyć, dokąd arakkoa zabrali Dugara.', 0),
(10051, 'koKR', 'Isla Gwiezdna Grzywa właśnie wyszła, ale zdała mi pełną relację z tego, co się dzieje w Punkcie Ognistego Skrzydła. Nic dziwnego, że jest bardzo wstrząśnięta tym, co spotkało Gąszcz Cenariona. Podłe krwawe elfy!$B$BOpowiedziała mi, jak bardzo się $gprzyczyniłeś:przyczyniłaś; do jej ocalenia, dzięki czemu mogliśmy zdobyć te informacje. Fort Alleriański ma wobec ciebie dług wdzięczności za twoją służbę.$B$BProszę, przyjmij ten dar od nas wszystkich.', 0),
(10052, 'koKR', 'Isla Gwiezdna Grzywa właśnie wyszła, ale zdała mi pełną relację z tego, co się dzieje w Punkcie Ognistego Skrzydła. Nic dziwnego, że jest bardzo wstrząśnięta tym, co spotkało Gąszcz Cenariona.$B$BOpowiedziała mi, jak bardzo się $gprzyczyniłeś:przyczyniłaś; do jej ocalenia, dzięki czemu mogliśmy zdobyć te informacje. Warownia Kamieniołamaczy ma wobec ciebie dług wdzięczności za twoją służbę.$B$BProszę, przyjmij ten dar od nas wszystkich.', 0),
(10094, 'koKR', 'Gdy otwierasz tom zawieszony w powietrzu za sprawą magii, ogarnia cię przerażenie.$B$BCoś tu jest bardzo nie w porządku!$B$BCzytasz dalej, ale to, co czytasz, wydaje się niewiarygodne!', 0),
(10097, 'koKR', 'Nie potrafię ci dość podziękować, $N. Skoro Lakka jest wolna, mogę zerwać resztę więzi z Sethekk.$B$BCząstka mnie nigdy sobie nie wybaczy śmierci Sytha, ale tak musiało być. Kiedy dotrę do Skettis, odprawię za niego obrzędy pogrzebowe. Może jego duch zazna spokoju, gdy odpokutuje za to, że sprowadził nasz lud na manowce.', 0),
(10098, 'koKR', 'Może nigdy nie zostanie mi naprawdę wybaczony mój udział w zbrodniach Sethekk, ale być może zwracając relikwie Terokka mojemu ludowi, zacznę odkupywać swoje winy.$B$BDziękuję, że mi w tym $gpomogłeś:pomogłaś;, $N. Nie masz pojęcia, jak doniosłe jest to, czego dziś $gdokonałeś:dokonałaś;.', 0),
(10164, 'koKR', 'Udało ci się, $N! Duchy są wolne!$B$BChoć nie mam materialnej postaci, wciąż mogę nagrodzić cię przedmiotami ze świata duchów. Używaj ich ostrożnie, bo takie przedmioty często są niestabilne i mogą wyrządzić wielką krzywdę temu, kto ich używa.', 0),
(10165, 'koKR', 'Kolejny konkurent plajtuje... Dobrze pracujesz jak na bestię z mięsa, $N. Jeśli kiedyś będziesz w Burzy Otchłani, odwiedź mnie. Mieszkam w Burzowej Iglicy.', 0),
(10178, 'koKR', 'Co? Grik\'tha przysłała cię tu po mnie?$B$BSam nie wiem, czy się wzruszyć, czy nazwać ją głupią!$B$BMyślisz, że pomożesz mi wydostać się z tej klatki? Trochę tu ciasno.', 0),
(10195, 'koKR', 'Wspaniałe! Nie zdziw się, jeśli niedługo zobaczysz gromadę mężczyzn przechadzających się w kapeluszach z piórami!', 0),
(10196, 'koKR', 'Dziękuję, $N. Zrobię z nich dobry użytek.', 0),
(10201, 'koKR', '<Opowiadasz Rakorii o wynikach próby, a ona odrzuca głowę do tyłu i wybucha śmiechem.>', 0),
(10216, 'koKR', '<Zamykasz oczy i wciskasz guzik.>', 0),
(10218, 'koKR', 'Skoro to był pomysł Morphaliusa, postanowiłem przywrócić go na dawne stanowisko. Dobra robota, mała bestio z mięsa. Doprawdy, dobra robota!$B$BPamiętaj, jeśli kiedyś będziesz szukać pracy i zdarzy ci się być w Burzy Otchłani, znajdziesz mnie w Burzowej Iglicy.', 0),
(10227, 'koKR', 'Dziecko ma rację. Byłem kiedyś „kapłanem śmierci”.$B$B<Ramdor się krzywi.>$B$BCóż za niesmaczny tytuł.$B$BTym korytarzem dojdziesz do Krypt Auchenai. W środku znajdziesz resztki mojego klasztoru. Oczywiście wszyscy już oszaleli. Obłąkani co do jednego! Chyba się wyróżniałem, bo jako ostatni z nich zachowałem choć odrobinę zdrowego rozsądku. Rzecz jasna, za moje przekonania mnie ekskomunikowano.$B$BJakie to przekonania, pytasz?', 0),
(10253, 'koKR', 'Skoro stary draenei kazał zniszczyć księgę, czemu tego nie $gzrobiłeś:zrobiłaś;?$B$B<Ramdor patrzy na ciebie spode łba.>$B$BEch, co za różnica. Może i jesteś $gchciwy:chciwa;, ale przynajmniej $guczciwy:uczciwa;.$B$BZa to ja... Skłamałem, żeby zdobyć tę księgę. Nie mam pojęcia, gdzie te biedne zagubione dusze trzymały swoje skarby, a nawet gdybym wiedział, nie powiedziałbym ci. Mam jednak coś dla ciebie. $gZrobiłeś:Zrobiłaś; dziś dobry uczynek. Może nawet wielki... Należy ci się nagroda.$B$BA tak przy okazji: witaj w klubie.$B$B<Ramdor wskazuje na duchy.>', 0),
(10444, 'koKR', 'Części bomby. A więc moje podejrzenia się potwierdziły. Wolałbym się mylić.$B$BDobrze, w takim razie czeka nas ponura robota.', 0),
(10446, 'koKR', 'UDAŁO CI SIĘ! $GURATOWAŁEŚ:URATOWAŁAŚ; NAS! $GURATOWAŁEŚ:URATOWAŁAŚ; FORT ALLERIAŃSKI!!$B$BIch siły są zdziesiątkowane, przywódca nie żyje, a bomba many zniszczona – wszyscy możemy wreszcie odetchnąć z ulgą.$B$B$N, nigdy nie widziałam takiej ofiarności... takiego bohaterstwa! Proszę, przyjmij to w imieniu nas wszystkich.', 0),
(10447, 'koKR', 'UDAŁO CI SIĘ! $GURATOWAŁEŚ:URATOWAŁAŚ; NAS! $GURATOWAŁEŚ:URATOWAŁAŚ; WAROWNIĘ KAMIENIOŁAMACZY!!$B$BIch siły są zdziesiątkowane, przywódca nie żyje, a bomba many zniszczona – wszyscy możemy wreszcie odetchnąć z ulgą.$B$B$N, nigdy nie widziałem takiej ofiarności... takiego bohaterstwa! Proszę, przyjmij to w imieniu nas wszystkich.', 0),
(10448, 'koKR', 'Części bomby. A więc moje podejrzenia się potwierdziły. Wolałabym się mylić.$B$BDobra, w takim razie czeka nas ponura robota.', 0),
(10649, 'koKR', 'Wyczuwałem moc tej księgi z odległości wielu jardów. Pokusa, by ją zatrzymać, jest... bardzo silna.', 0),
(10662, 'koKR', 'Ordinn przysłał cię z tym?$B$B<Kowal ogląda sztabki.>$B$BMiał rację. Większość magii zniknęła, ale wciąż wyczuwam jej ślady. Przy odrobinie pracy i kilku „egzotycznych” surowcach wykuję ci z tego metalu potężny miecz przeciw demonom.', 0),
(10663, 'koKR', '<Kowal marszczy brwi i ogląda sztabki.>$B$BPowiem ci szczerze, $N. Jestem reliktem czasów, gdy współpraca z Hordą była nie do pomyślenia.$B$BNie jestem jednak aż tak ślepy, by nie widzieć, że mamy wspólnych wrogów. Pomogę ci przekuć broń przeciw demonom, ale będzie to wymagało mnóstwa ciężkiej pracy i kilku „egzotycznych” surowców.', 0),
(10664, 'koKR', '<Kowal przyjmuje materiały i kiwa głową z aprobatą.>$B$BTo wystarczy. O resztę potrzebnych materiałów nie będzie już tak łatwo.', 0),
(10665, 'koKR', 'Jest nawet potężniejsze, niż się spodziewałem! Przy takiej mocy mógłbym wykuć tuzin ostrzy!', 0),
(10666, 'koKR', '<David kartkuje księgę i wzdryga się.>$B$BZ tym nie ma żartów, $N. Gdy broń będzie gotowa, zniszczę ją. Na świecie jest dość demonicznej mocy i bez tego tekstu w niepowołanych rękach.', 0),
(10667, 'koKR', 'To powinno wystarczyć. Liczyłem na trochę więcej, ale szczerze mówiąc, i tak mieliśmy szczęście, że w ogóle udało się ją tu zdobyć.', 0),
(10670, 'koKR', '<David Wayne unosi klejnot pod światło i go podziwia.>$B$BJest absolutnie bez skazy, a właśnie tego nam trzeba. Klejnot ze skazą zagroziłby temu, kto dzierży broń, bo obróciłby magię przeciwko niemu.', 0),
(10676, 'koKR', '<David ociera pot z czoła.>$B$BNajwiększa część pracy za nami, ale żeby utrwalić magię, ostrze trzeba teraz zahartować.', 0),
(10679, 'koKR', 'Dobra robota!$B$B<Kowal uważnie ogląda ostrze.>$B$BPowiedziałbym, że to spory postęp w porównaniu z prymitywną bronią Legionu, od której $gzaczynałeś:zaczynałaś;. To ostrze nie tylko posieka demony Illidari, ale sprawdzi się też przeciwko sługom Legionu.', 0),
(10791, 'koKR', 'To niewiarygodne! Wyruszałem w tę podróż, nie wiedząc, czy wilczy duch odpowie na nasze wezwanie, a teraz mam wrażenie, jakby był tu od zawsze. Może i był, $N.$B$BMoże czekał, aż orkowie zrozumieją, do czego doprowadziły ich wybory.', 0),
(10839, 'koKR', 'Wybuch dotarł aż tutaj. Nie do moich uszu, lecz do serca.$B$BJeśli dotyk błogosławionego naaru A\'dala nie wystarczy, by przywieść arakkoa do odkupienia, nic nie wystarczy. Ci, którzy nie oddali się Światłości, są jedynie sługami zła.$B$BTrzeba ich zniszczyć.', 0),
(10840, 'koKR', 'Tu, w dzikich ostępach Rubieży, jesteśmy słabi i niewielu bohaterów broni naszych praw, ale ty $gdałeś:dałaś; im powód do strachu. Nie sądzę, by eterycy prędko zapomnieli, jak silną prawicę ma $N.', 0),
(10842, 'koKR', 'Nie wiesz, czego tu $gdokonałeś:dokonałaś;, $N. $GOcaliłeś:Ocaliłaś; tak wielu z nas przed wiecznością w ciemności. Niewiele mogę zrobić dla żywych i nie mam nic, czym mógłbym ci należycie podziękować. Weź to, co wyda ci się przydatne.', 0),
(10848, 'koKR', 'Te plugawe duchy zasłużyły na śmierć. Wystarczy pomyśleć o śmierci, jaką zgotowałyby innym.$B$BNie możemy liczyć na odkupienie tych, których Terokk trzyma w szponach. Ale w imię Światłości zadamy im druzgocący cios.', 0),
(10852, 'koKR', '$GZnalazłeś:Znalazłaś; wszystkich moich przyjaciół! Teraz mam się z kim bawić. Dziękuję, $gpanie:pani; $N.$B$BSkoro mam już z kim się bawić, może chcesz jedną z moich zabawek? Wtedy ty też będziesz $gmiał:miała; czym się bawić.', 0),
(10861, 'koKR', 'Mordęga z cudzymi pisklętami to ponura robota, ale ignorowanie narastającego zła byłoby równie ponure. Dobrze się $gspisałeś:spisałaś;. Łaska A\'dala jaśnieje w twoim sercu.', 0),
(10868, 'koKR', 'Dobra robota, $N. Arakkoa nauczyli się bać potęgi Hordy.', 0),
(10869, 'koKR', 'Dobra robota, $N. Arakkoa nauczyli się bać potęgi Przymierza.', 0),
(10873, 'koKR', '$GOcaliłeś:Ocaliłaś; tak wielu. Nie sądziłem, że jeszcze kiedyś ich zobaczymy. Nie potrafimy ci się dość odwdzięczyć, $N.', 0),
(10874, 'koKR', 'Widzieliśmy stąd, jak unosi się przeklęty dym. Wielka w tobie odwaga, $N.', 0),
(10877, 'koKR', 'To niewiarygodne, że ci się udało. Relikwia grozy jest znacznie potężniejsza, niż się obawiałem. Tylko potężny bohater mógł przetrwać długą drogę powrotną, niosąc tak bluźniercze zło.', 0),
(10878, 'koKR', 'Na razie mogę odetchnąć z ulgą, $N. Rada Cieni zostanie na jakiś czas powstrzymana.$b$bTo mordercy i tchórze, a twoja odwaga będzie trzymać ich na dystans.', 0),
(10880, 'koKR', 'A, tak... to napisano podstawową odmianą szyfru cienia. Nie znam go doskonale, ale powinienem dać radę to przetłumaczyć.$B$BGdy mieszka się wśród wyrzutków i uchodźców w Dolnym Mieście, można się sporo dowiedzieć o podejrzanych sprawach.', 0),
(10881, 'koKR', 'Światłość mogła o mnie zapomnieć, ale ja nie zapomniałem o Światłości. Te relikwie były niegdyś bardzo święte dla mojego ludu.$B$BPozwolić Radzie Cieni używać ich mocy do złych celów to... nie do pomyślenia!', 0),
(10887, 'koKR', '$GUratowałeś:Uratowałaś; Akuna, mojego drogiego przyjaciela. Za to jestem twoim dłużnikiem, $N.', 0),
(10896, 'koKR', 'Wiele $gzrobiłeś:zrobiłaś; dla Puszczy Terokkar, $N. Teraz, gdy najgorsze kolonie roztoczy zostały zniszczone, może jeszcze uda nam się odzyskać tę spustoszoną ziemię.', 0),
(10913, 'koKR', '<Dowódca Ra\'vaj chowa twarz w dłoniach.>$B$BTo za mało... Po prostu za mało.', 0),
(10914, 'koKR', 'Udało ci się, $N! Dzięki tobie dokonaliśmy nowego odkrycia...', 0),
(10915, 'koKR', 'Zwycięstwo jest nasze! Ta porażka cofnie Auchenai o kilka tygodni.', 0),
(10920, 'koKR', 'Słyszałem stąd odgłosy twojej walki, $N. Odgłosy twojego zwycięstwa napełniły moje serce nadzieją. Skoro potrafisz zwyciężyć wbrew tak strasznej przewadze wroga, może i ja znajdę siłę, by wyciągnąć towarzyszy z tego okropnego miejsca.', 0),
(10921, 'koKR', 'Straszliwokłe zostały pokonane. $GZabiłeś:Zabiłaś; wiele z nich, a nawet ich plugawa matka padła przed tobą. Jestem zbyt zatruty, by wywalczyć sobie drogę na wolność.$B$BProszę, weź część mojego ekwipunku. Mnie ulży w dźwiganiu, a tobie da to, czego potrzebujesz na drogę powrotną do Posterunku Sha\'tari.', 0),
(10922, 'koKR', 'Kościany czerw! Fantastycznie! To chyba pierwszy raz w spisanych dziejach, kiedy Letoll naprawdę coś odkrył.', 0),
(10923, 'koKR', 'Wielkie zło zostało usunięte z Terokkar. Sha\'tarowie są twoimi dłużnikami.', 0),
(10926, 'koKR', 'Dobrze wiedzieć, że niektórzy z naszych wojowników dzielnie walczyli ze straszliwokłymi wdowami. Natychmiast wyślemy ekipę ratunkową.', 0),
(10929, 'koKR', 'Piaskowe gnomy? Jasne, jasne... Pustynia potrafi dziwnie działać na człowieka.$B$BChyba jesteśmy o krok od przełomu w sprawie tych czerwi!', 0),
(10930, 'koKR', 'Niesamowite! Popatrz tylko! To tego-tam ma w swoim jak-mu-tam jakiś pył. Ech! Nie będę cię zanudzał tym całym naukowym żargonem. Udało mi się za to wyrwać tym małym kilka zębów i zrobić z nich te niesamowicie ostre noże. Chcesz jeden?', 0),
(10997, 'koKR', 'Co za ulga, że Slaaga już nie ma. Nie będzie nam już zagrażać widmo jego powrotu!$B$BJeśli nie masz nic przeciwko, zatrzymam sztandar jako symbol nadziei dla wszystkich ogrów z gór.$B$BDziękuję ci, $N.', 0),
(11004, 'koKR', 'Dziękuję ci, $N. Podam dowódcy niewielką ilość... żeby mu dogodzić. Resztę możesz zatrzymać, może znajdziesz dla niej zastosowanie.', 0),
(11005, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. Zabijając szponokapłanów, $gzadałeś:zadałaś; wrogowi potężny cios.', 0),
(11006, 'koKR', 'Przynoś mi dalej pył. Przygotuję tyle eliksirów, ile potrzebujesz.$b$bRozkaz dowódcy.', 0),
(11008, 'koKR', 'Świetna robota, $N! To pokaże tym ptakoludziom, co znaczy przewaga w powietrzu!', 0),
(11021, 'koKR', 'Co mi $gprzyniosłeś:przyniosłaś;? Nie mogę odczytać pisma w tym tomie, $N... Utrata krwi... musiała mi zamglić wzrok.', 0),
(11029, 'koKR', 'Doskonale! Ta księga wymienia potomków dawnych wrogów Terokka. Przepowiednia głosi, że po ich zgubie nastąpi powrót Terokka.', 0),
(11056, 'koKR', 'Doskonale, $N. Przekonasz się, że dotrzymuję słowa.', 0),
(11072, 'koKR', 'Doskonale! Weź to. Przygotowałem ten tobołek z przedmiotów, które $gzdobyłeś:zdobyłaś;. Pozwolą ci przywołać Terokka.$B$BStrzeż się, $N. To najpotężniejszy arakkoa, jaki kiedykolwiek istniał. Nie lekceważ go!', 0),
(11073, 'koKR', 'Wszyscy jesteśmy z ciebie bardzo dumni, $N. Wyślę do Shattrath wieść o twoich czynach. Podniebna Straż zawsze będzie miała wobec ciebie dług wdzięczności.', 0),
(11074, 'koKR', 'Doskonale! Weź to. Przygotowałem ten tobołek z przedmiotów, które $gzdobyłeś:zdobyłaś;. Pozwolą ci przywołać Terokka.$b$bStrzeż się, $N. To najpotężniejszy arakkoa, jaki kiedykolwiek istniał. Nie lekceważ go!', 0),
(11085, 'koKR', 'Dziękuję, że $guratowałeś:uratowałaś; jednego z naszych zwiadowców, $N. Każdego dnia tracimy dobrych ludzi, a nowych rekrutów jest za mało, żeby ich zastąpić.', 0),
(11093, 'koKR', 'Dzięki, że $gzająłeś:zajęłaś; się płaszczką, $N. Wiadomo, że te stworzenia latają dużo lepiej, kiedy są najedzone. Nie chcemy, żeby naszych chłopaków zestrzelono, bo ich płaszczka była za słaba, żeby latać.', 0),
(11505, 'koKR', 'Duchy są o krok bliżej wiecznego odpoczynku. Dobrze jest zyskać ich przychylność, zwłaszcza gdy toczy się wojnę tak blisko miejsca ich spoczynku.', 0),
(11506, 'koKR', 'Duchy są bliżej odnalezienia spokoju i obdarzyły nas swoją przychylnością.$b$bTo upokarzający cios dla wroga, że jego własni przodkowie stanęli przeciw niemu, nawet jeśli tylko na chwilę.', 0),
(11520, 'koKR', 'Te się świetnie nadadzą, $N.$b$bDziękuję za pomoc.', 0),
(11521, 'koKR', 'Świetna robota, $N.$b$bJeszcze raz dziękuję za pomoc!', 0),
(11665, 'koKR', 'Co za wredne małe stworzenie! Jestem pewien, że Rokk przyrządzi z niego coś smacznego.$b$bOczywiście tylko żartuję.$b$b<Stary Barlo chytrze mruga.>', 0),
(11666, 'koKR', 'No proszę... $gzłowiłeś:złowiłaś; dużą sztukę! Dziś wieczorem ten staruszek zje po królewsku.', 0),
(11667, 'koKR', 'To ona! Tę bliznę poznałbym wszędzie.$b$bSzczerze mówiąc, myślałem, że będzie... większa. No cóż, chyba ją wypuszczę i spróbuję innym razem.', 0),
(11668, 'koKR', 'Umiesz się posługiwać i haczykiem, i nożem. Dawaj te smakowite kąski, a dam ci spróbować.', 0),
(11669, 'koKR', 'To największa i najbrzydsza ryba, jaką widziałem. Nawet nie potrafię sobie wyobrazić, czego $gużyłeś:użyłaś; jako przynęty.$b$bPo prostu połóż bestię na ziemi, zajmę się nią, jak tylko będę pewien, że nie żyje.', 0),
(11885, 'koKR', 'Doskonale! Weź to. Przygotowałem ten tobołek z przedmiotów symbolizujących wrogów, których $gpokonałeś:pokonałaś;. Pozwolą ci przywołać Terokka.$b$bStrzeż się, $N. To najpotężniejszy arakkoa, jaki kiedykolwiek istniał. Nie lekceważ go!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9889, 'koKR', 'Poddaję się! Poddaję się!', 0),
(9950, 'koKR', 'Rokag opowiedział mi o swoim planie. Masz te oczy?', 0),
(9951, 'koKR', 'Nigdy nie powinniśmy byli zapraszać ich na kolację. Co do tego nie ma wątpliwości!$B$BAlbo przynajmniej powinniśmy byli nalegać na kilka dań przed deserem, który przynieśli.', 0),
(9968, 'koKR', 'Masz moje próbki?', 0),
(9971, 'koKR', '$GOdkryłeś:Odkryłaś; już coś?', 0),
(9986, 'koKR', 'Dobrze cię znów widzieć, $N. $GZrobiłeś:Zrobiłaś;, o co prosiłem?', 0),
(9987, 'koKR', 'Witaj z powrotem, $N. $GRozprawiłeś:Rozprawiłaś; się z przywódcami arakkoa?', 0),
(9992, 'koKR', 'Zaczęłam zbierać nasiona, ale potrzebuję pomocy, zanim uzbieram dość, żeby wysłać je do parku w Wichrogrodzie.', 0),
(9993, 'koKR', 'Masz dla mnie jakieś nasiona?', 0),
(9994, 'koKR', 'Wyglądasz na $gzaniepokojonego:zaniepokojoną;. Co się stało, $N?', 0),
(9995, 'koKR', 'Wyglądasz na $gzaniepokojonego:zaniepokojoną;. Co się stało, $N?', 0),
(9996, 'koKR', 'Melduj. Jakie wieści przynosisz z Punktu Ognistego Skrzydła?', 0),
(9997, 'koKR', 'Melduj. Jakie wieści przynosisz z Punktu Ognistego Skrzydła?', 0),
(9998, 'koKR', 'Rozumiem, że Bertelm przysłał cię, żebyś $gutrudnił:utrudniła; pracę ich peonom?', 0),
(10000, 'koKR', 'Właśnie miałem wysłać Rokagowi wiadomość z zaleceniem ataku, ale widzę, że to nie będzie konieczne.', 0),
(10002, 'koKR', 'Ruch w obozie wciąż się nasila. $GWykonałeś:Wykonałaś; swoje zadanie?', 0),
(10003, 'koKR', 'Im dłużej pozwolimy im się przygotowywać, tym trudniej będzie ich wykurzyć. $GZabiłeś:Zabiłaś; łączniczkę?', 0),
(10007, 'koKR', 'Twój atak się powiódł?', 0),
(10008, 'koKR', 'Powiedz mi, że nie myliłem się, powierzając ci to zadanie...', 0),
(10015, 'koKR', 'Masz już te kody? $GWidziałeś:Widziałaś;, co się stało z druidami w Gąszczu Cenariona.$B$BChcesz, żeby to samo spotkało Warownię Kamieniołamaczy?', 0),
(10016, 'koKR', 'Widzę, że $gprzetrwałeś:przetrwałaś; trudy puszczy. $GPrzyniosłeś:Przyniosłaś; jakieś ogony do mojego płaszcza?', 0),
(10018, 'koKR', 'Udało ci się znaleźć wszystkie skóry, których potrzebuję?', 0),
(10022, 'koKR', 'Czy stary Żelaznoszczęki ciebie też przechytrzył, przyjacielu? A może udało ci się wywieść w pole starego drania?', 0),
(10023, 'koKR', 'Duch czeka, $N. Masz skórę wilczego patriarchy?', 0),
(10026, 'koKR', '$GOczyściłeś:Oczyściłaś; okolice fortu z tropicieli wypaczenia?', 0),
(10027, 'koKR', 'Keb\'ezil chce wiedzieć, czy może już bezpiecznie ciskać kule ognia, nie robiąc z siebie znowu pośmiewiska.$B$B<Chochlik wydaje kilka klikających dźwięków, a czarnoksiężnik odwraca się do niego.>$B$BNie, to nie był mój pocisk cienia! Odwołaj to, ty przerośnięty skrzacie!', 0),
(10028, 'koKR', 'Udało ci się znaleźć jakieś nienaruszone naczynia?', 0),
(10030, 'koKR', 'Co to? Kim jesteś?', 0),
(10031, 'koKR', '$N? Co cię do mnie sprowadza? $GDostarczyłeś:Dostarczyłaś; kości niespokojnych zmarłych Ramdorowi, tak jak prosiłem?', 0),
(10033, 'koKR', 'Pewnie też $gprzyszedłeś:przyszłaś; po nagrodę za kościosmagacze?', 0),
(10034, 'koKR', 'Czy to krew kościosmagaczy czuję na twoich rękach?', 0),
(10035, 'koKR', 'Masz pióro? Mam cię nagrodzić za twoją brawurę?', 0),
(10036, 'koKR', '$GZabiłeś:Zabiłaś; go? Torgos nie żyje?!$B$BMasz dowód?', 0),
(10043, 'koKR', 'No i czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(10097, 'koKR', '$GZnalazłeś:Znalazłaś; ją, $N? Wciąż więzili ją w salach?', 0),
(10098, 'koKR', 'Relikwii Terokka zbyt długo nie było w Skettis. Udało ci się odzyskać je od Sethekk?', 0),
(10164, 'koKR', 'Ocal duchy, $N.', 0),
(10165, 'koKR', 'Nie lubię się „dzielić”.', 0),
(10201, 'koKR', 'No i jak, masz wyniki próby?', 0),
(10216, 'koKR', 'To urządzenie ma ponad tuzin guzików i żaden nie wygląda znajomo.', 0),
(10218, 'koKR', 'Witaj, mała bestio z mięsa.', 0),
(10253, 'koKR', 'Kim jesteś i czego chcesz? A... To TY.', 0),
(10446, 'koKR', 'Porucznik Meridian na bieżąco informuje nas o sytuacji w Punkcie Ognistego Skrzydła. Wszystko w porządku?', 0),
(10447, 'koKR', 'Sierżant Chawni na bieżąco informuje nas o sytuacji w Punkcie Ognistego Skrzydła. Wszystko w porządku?', 0),
(10649, 'koKR', '$GZdobyłeś:Zdobyłaś; księgę, $N?', 0),
(10662, 'koKR', 'Co cię tu sprowadza? Rzadko miewam gości.', 0),
(10663, 'koKR', 'Co cię tu sprowadza? Rzadko miewam gości.', 0),
(10664, 'koKR', 'Masz te materiały?', 0),
(10665, 'koKR', 'Udało ci się przemycić ogniwo many z Mechanaru?', 0),
(10666, 'koKR', '$GZdobyłeś:Zdobyłaś; księgę?', 0),
(10667, 'koKR', '$GZdobyłeś:Zdobyłaś; ziemię z zaświatów?', 0),
(10670, 'koKR', 'Udało ci się wyrwać klejnot z łap O\'mrogga?', 0),
(10679, 'koKR', '$GZahartowałeś:Zahartowałaś; miecz w lawie Ręki Gul\'dana?', 0),
(10791, 'koKR', 'Odnowienie więzi z wilczym duchem to dopiero początek mojej podróży, a nie jej koniec.', 0),
(10839, 'koKR', 'Otacza nas ciemność. Co masz do powiedzenia o Zasłonie Skith?', 0),
(10840, 'koKR', 'Ilu eteryków $gzniszczyłeś:zniszczyłaś;? Mam nadzieję, że wystarczy, by wypędzić ich z Grobowca Świateł.', 0),
(10842, 'koKR', '$GOcaliłeś:Ocaliłaś; nas wszystkich. Jak możemy ci podziękować?', 0),
(10848, 'koKR', 'W Zasłonie Rhaze rośnie zło. Zdław je.', 0),
(10852, 'koKR', 'Nudzi mi się, nie mam się z kim bawić. $GZnalazłeś:Znalazłaś; moich przyjaciół?', 0),
(10861, 'koKR', '$GWykonałeś:Wykonałaś; swoje zadanie? Zdław zło, zanim będzie za późno!', 0),
(10868, 'koKR', 'Ilu arakkoa $gzabiłeś:zabiłaś;, $N? Uciekali przed tobą? Uciekali i chowali się, gdy $gwpadłeś:wpadłaś; do ich obozu?', 0),
(10869, 'koKR', 'Ilu arakkoa $gzabiłeś:zabiłaś;, $N?', 0),
(10873, 'koKR', '$GZnalazłeś:Znalazłaś; naszych zaginionych?', 0),
(10874, 'koKR', 'Zasłona Shalas musi zamilknąć!', 0),
(10877, 'koKR', 'Masz Relikwię grozy? Musimy ją mieć.', 0),
(10878, 'koKR', '$GZrobiłeś:Zrobiłaś;, o co prosiłem, $N? Boję się o nasze życie.', 0),
(10880, 'koKR', 'Chcesz mi coś pokazać, $N?', 0),
(10881, 'koKR', '$GOdzyskałeś:Odzyskałaś; relikwie, $N? Nie możemy pozwolić, by Rada Cieni użyła ich mocy do mrocznych celów.', 0),
(10896, 'koKR', '$GZniszczyłeś:Zniszczyłaś; najgorsze ogniska zarazy?', 0),
(10913, 'koKR', 'Wiem, że to straszna prośba...', 0),
(10914, 'koKR', 'Nie bierz jeńców!', 0),
(10915, 'koKR', 'Musisz zniszczyć to pradawne zło, zanim odzyska moc.', 0),
(10920, 'koKR', 'Czuję, jak trucizna płynie w moich żyłach. Naaru mnie wzywają, widzę światło. Czy straszliwokłe wdowy zostały pokonane?', 0),
(10921, 'koKR', 'Czy Terokkarantula nie żyje?', 0),
(10922, 'koKR', 'Zapłata będzie, jak robota będzie skończona, $gsynku:panienko;.', 0),
(10923, 'koKR', 'Czy niebo nad Terokkar zostało oczyszczone z Teribusa Przeklętego?', 0),
(10929, 'koKR', 'Wydaje nam się, że ten, który wyskoczył na wykopalisku, był w rzeczywistości młodym czerwiem!', 0),
(10930, 'koKR', 'Weź ze sobą jakiegoś przyjaciela!', 0),
(10997, 'koKR', 'Wracasz ze sztandarem Slaaga w ręku?', 0),
(11004, 'koKR', '$GZdobyłeś:Zdobyłaś; pył, $N?', 0),
(11005, 'koKR', 'Czy to już załatwione, $N? Sam bym pozabijał tych przeklętych ptakoludzi, gdyby nie moje rany.', 0),
(11006, 'koKR', 'Wygląda na to, że dowódca jednak nie majaczył. Przynieś mi więcej pyłu, a przygotuję ci kolejny eliksir.', 0),
(11008, 'koKR', '$GWykonałeś:Wykonałaś; już zadanie?', 0),
(11021, 'koKR', 'Masz mi coś do pokazania?', 0),
(11029, 'koKR', 'Księga, $N. Masz ją?', 0),
(11056, 'koKR', '$GWróciłeś:Wróciłaś;, $N. Zaczynałem już myśleć, że mnie $gzostawiłeś:zostawiłaś;.', 0),
(11073, 'koKR', 'Czy już po wszystkim, $N? Czy Terokk został pokonany?', 0),
(11074, 'koKR', 'Potrzebuję trofeum od każdego z potomków największych wrogów Terokka. Dopiero wtedy będziemy gotowi przywołać Terokka.', 0),
(11093, 'koKR', '$GWróciłeś:Wróciłaś;! Płaszczka dobrze się sprawowała?', 0),
(11505, 'koKR', 'Duchy są niespokojne, $n. $GWykonałeś:Wykonałaś; swoje zadanie?', 0),
(11506, 'koKR', 'Duchy Auchindoun są wokół nas. Czy obdarzą nas swoją łaską?', 0),
(11520, 'koKR', 'Naprawdę, $n, jestem zbyt zajęta na pogaduszki.$b$bDaj znać, gdy zbierzesz te korzenie.', 0),
(11521, 'koKR', 'Naprawdę, $n, jestem zbyt zajęta na pogaduszki.$b$bDaj znać, gdy zbierzesz te korzenie.', 0),
(11665, 'koKR', '$GZłowiłeś:Złowiłaś; już jakiegoś krokoliszka w kanałach?', 0),
(11666, 'koKR', 'Jak tam dziś połów, $gchłopcze:dziewczyno;?', 0),
(11667, 'koKR', 'Powiedz, że ją $gzłowiłeś:złowiłaś;. Błagam, powiedz, że $gzłowiłeś:złowiłaś; tę karpiową zołzę.', 0),
(11668, 'koKR', 'Co dziś złowione, $gchłopcze:dziewczyno;?', 0),
(11669, 'koKR', 'Lucjan spaczonej krwi to cud ewolucji. Przeżyje w każdej wodzie, a nawet w lawie, a jedynym jego naturalnym drapieżnikiem są wędkarze.$b$bUdało ci się złowić zdobycz?', 0);
