INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3029, 'koKR', 'Podczas mojego ostatniego pobytu w salach Szponi Król Ikiss nosił przy sobie Pióro Terokka jako znak swojej władzy. Pewnie nadal je nosi, by przekonać swoich wyznawców, że jest odrodzonym Terokkiem.$B$BMój brat, Tkacz Mroku Syth, nosił Maskę Terokka, gdy przewodził rytuałom Sethekk.$B$BCo do Sagi o Terokku, jest przechowywana w kręgu run w wielkiej sklepionej komnacie tuż obok komnaty Szponiego Króla Ikissa.', 0);
