INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(23383, 0, 0, 'koKR', 'Dzięki za pomoc. Wynośmy się stąd!'),
(23383, 1, 0, 'koKR', 'Idźmy dalej. Nie podoba mi się to miejsce.'),
(23383, 2, 0, 'koKR', 'Jeszcze raz dzięki. Sierżant Doryn ucieszy się, że w tym tygodniu ma o jednego zwiadowcę mniej do zastąpienia.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(15096, 'koKR', 'Czy wiesz, kim jesteśmy, przybyszu? Jesteśmy Mag\'harami – brązowymi orkami, jak nazywają nas podobno tacy jak ty. Mag\'harowie przetrwali: przetrwali upadek dynastii, przetrwali czerwoną ospę, przetrwali rozbicie świata...$B$BJestem Jorin, syn Kilrogga, ostatni z rodu Celnookiego, wodza klanu Krwawiącego Oczodołu.', '', 0),
(15097, 'koKR', 'Poddaję się! Proszę, nie zabijaj mnie!', '', 0),
(15404, 'koKR', 'Kim jesteś? Czego tu chcesz?', '', 0),
(15405, 'koKR', 'Dlaczego nam to $gzrobiłeś:zrobiłaś;?', '', 0),
(15406, 'koKR', 'Są CZTERY światła!', '', 0),
(15407, 'koKR', 'Moje okrutne teroćmy mnie pomszczą!', '', 0),
(15408, 'koKR', 'Gdzie się wszyscy podziali?', '', 0),
(15409, 'koKR', 'Goście na kolacji powinni okazywać więcej szacunku!', '', 0),
(15410, 'koKR', 'Och, jakież to święte miejsce tu upadło!', '', 0),
(15412, 'koKR', 'Namaść mi głowę kojącym balsamem. Podoba ci się moja korona cierniowa?', '', 0),
(15428, 'koKR', 'Ta puszcza to straszne miejsce. Pełno w niej złego dżudżu, nie tylko Przymierza, więc uważaj na siebie.', '', 0),
(15429, 'koKR', '', 'Horda to nie jedyne niebezpieczeństwo w tej puszczy. Nie daj się zwieść jej pozornemu spokojowi.', 0),
(15463, 'koKR', 'Wyłazić, małe ptaszki! Mug\'gok chcieć się bawić!', '', 0),
(15464, 'koKR', 'Nie ranić uczuć Mug\'goka, ptakoludzie!', '', 0),
(15465, 'koKR', 'Dobra! Ptaszki takie być! Mug\'gok znaleźć nowych przyjaciół!', '', 0),
(15471, 'koKR', 'Leżą tu zwłoki jednego ze Złamanych. Co dziwne, przyczyną śmierci nie wydaje się żadna ze zmutowanych ciem.$B$BMoże ma to coś wspólnego z dziwnym przedmiotem leżącym tuż obok jego wyciągniętej dłoni?', '', 0),
(15528, 'koKR', 'To należy do Punktu Ognistego Skrzydła. Nie położysz na tym swoich brudnych łap!', 'To należy do Punktu Ognistego Skrzydła. Nie położysz na tym swoich brudnych łap!', 0),
(15542, 'koKR', 'Przychodzisz do mojego domu i grozisz MNIE? Nie sądzę!', '', 0),
(15553, 'koKR', 'Treelosie, wiem, że prawda jest gdzieś w tobie. Powiedz mi, jaka jest.', 'Treelosie, wiem, że prawda jest gdzieś w tobie. Powiedz mi, jaka jest.', 0),
(15554, 'koKR', '<Strażnik Treelos dziwnie ci się przygląda, a potem na chwilę milknie, wyraźnie się z czymś zmagając.>$B$BMoczary Zangarskie... zbyt blisko prawdy.$B$B<Jego twarz znów wykrzywia szaleństwo.>$B$BCzy on wciąż patrzy!?', '', 0),
(15555, 'koKR', 'Weź się w garść, człowieku! Co z Moczarami Zangarskimi?', 'Weź się w garść, człowieku! Co z Moczarami Zangarskimi?', 0),
(15556, 'koKR', 'Co? Moczary Zangarskie? Po co miałbym tam iść?$B$B<Treelos się zamyśla.>$B$BTak, Moczary Zangarskie... my... tamtejsi druidzi są blisko odkrycia, dlaczego poziom wody opada. To niszczy wszystko!$B$B<Widzisz, jak w oczy strażnika znów wkrada się szaleństwo.>$B$BZniszczyło nas wszystkich! Jasne światło! BUM!!', '', 0),
(15557, 'koKR', 'Nie mam na to czasu! Strażniku, co się stało?!', 'Nie mam na to czasu! Strażniku, co się stało?!', 0),
(15558, 'koKR', 'Krwawe elfy z Ognistego Skrzydła... z jakiegoś powodu chcą nas powstrzymać.$B$B<Strażnik Treelos wyraźnie walczy, by zachować przytomność umysłu jeszcze przez kilka sekund.>$B$BOni... przysłali jednego ze Złamanych jako... jako posła... Ale on miał bombę!$B$BZginęli, wszyscy zginęli! Próbowali uciekać! Ci, którzy mieli szczęście, nawet nie wiedzieli.$B$BMusiałem być na skraju wybuchu. To było straszn... ZNOWU NA NAS PATRZY!$B$B<Treelos popada w apatię i patrzy przez ciebie, jakby cię tu nie było.>', '', 0),
(15562, 'koKR', '<Floon wydaje serię dziwnych klekoczących i gdaczących dźwięków.>', '', 0),
(15563, 'koKR', 'Mówisz poważnie? Przecież już mnie zabił! Czego jeszcze może chcieć?', '', 0),
(15564, 'koKR', 'Chce swoich „złociszy”. Płać albo giń... znowu...', 'Chce swoich „złociszy”. Płać albo giń... znowu...', 0),
(15566, 'koKR', 'Wybieram trzecią opcję: ZABIJĘ CIĘ!', '', 0),
(15689, 'koKR', 'Uważaj, $N. Puszcza jest pełna ukrytych niebezpieczeństw i potencjalnych wrogów.', '', 0),
(15702, 'koKR', 'To po prostu straszne.$B$BNie dbam o nasze własne niewygody, ale musimy coś zrobić, by ulżyć cierpieniu zmarłych na Kościanych Pustkowiach!', '', 0),
(15714, 'koKR', 'Jeśli liczysz na jakieś oficjalne powitanie, to się rozczarujesz, $N. Nie przywiązujemy tu wagi do tradycji. Liczy się to, co działa.', '', 0),
(15715, 'koKR', 'Spośród różnych kawałków pergaminu przypiętych do tego listu gończego wyróżnia się jedna notatka. To wezwanie do zabijania kościosmagaczy z Kościanych Pustkowi.', '', 0),
(15717, 'koKR', '', 'Nie, nie przejmuj się. Często to słyszę.$B$B<Taela wygląda na jednocześnie rozbawioną i zirytowaną.>$B$BJestem WYSOKĄ elfką, nie krwawą. Spokojnie, nie wyssę z ciebie całej magii.', 0),
(15718, 'koKR', 'Kościosmagacze, nienawidzę ich wszystkich!$B$BGdyby nie to, że straciłem oko, i te omdlenia, które czasem mnie łapią, bez przerwy bym tam był i je zestrzeliwał!', '', 0),
(15719, 'koKR', '%s mdleje.', '', 0),
(15723, 'koKR', 'Zanim przeszedłem przez Nagrand i dotarłem do puszczy, obawiałem się, że zbyt wiele z naszej pierwotnej kultury przepadło. Cieszę się, że się myliłem.$B$BTyle jest tu do zrobienia!', '', 0),
(15724, 'koKR', '', 'Otwarcie Mrocznego Portalu przyniosło wieści o losie mojego ludu. W pewnym sensie wygnanie uchroniło mnie przed udziałem w jego upadku, ale widzieć, jak Obieżyświaci wiążą swój los z Kael\'thasem...$B$BNigdy nie przypuszczałam, że moi dawni bracia byliby do czegoś takiego zdolni.$B$BPowrót do domu, o którym kiedyś marzyłam, nigdy nie nastąpi. Ta puszcza to jedyny dom, jaki mi został.', 0),
(15726, 'koKR', '', 'Kiedy tu przybyłam, liczyłam, że poznam tę, od której osada wzięła nazwę.$B$B<Ros\'eleth rozgląda się.>$B$BWiększość młodych wysokich elfów wyrasta z etapu „chcę zostać Obieżyświatem”, zanim trafi na naukę. Potem przychodzi etap „zostanę magistrem”.$B$BSzczerze mówiąc, chyba nigdy do końca nie wyrosłam z etapu Obieżyświata. Nikt nie marzy, że wyrośnie na krawcową, ale jak mawiała moja matka, nie możemy pozwolić, żeby Obieżyświaci biegali nago.', 0),
(15727, 'koKR', '$GWidziałeś:Widziałaś;, jak Ros\'eleth puszcza do mnie oko, ilekroć idę odebrać jakieś ubranie albo kapelusz? Kiedy sytuacja tu się uspokoi, zabiorę ją na miły spacer po lesie.$B$BChoć raz tęsknię za tymi wszystkimi eleganckimi tawernami w Wichrogrodzie.', '', 0),
(15729, 'koKR', 'Może i współpracujemy, ale to tylko zwiększa potrzebę dyskrecji. Powtarzam: uważaj na słowa i czyny.$B$BMogę ci zagwarantować, że z pewnością nie jesteśmy tu jedyni.', '', 0),
(15755, 'koKR', 'No, czego chcesz? Nie widzisz, że jestem zajęty? Rada Cieni nie płaci mi od godziny!', 'No, czego chcesz? Nie widzisz, że jestem zajęty? Rada Cieni nie płaci mi od godziny!', 0),
(15757, 'koKR', 'Czemu to wszystko naprawiasz?', 'Czemu to wszystko naprawiasz?', 0),
(15758, 'koKR', 'A na co to wygląda? Remontuję to miejsce – i to sam, dodam – żebyśmy mogli się wprowadzić!$B$BZ bazą wypadową tutaj, w puszczy, łatwiej będzie śledzić, co knują Shattrath, Fort Alleriański, Warownia Kamieniołamaczy i druidzi cenariońscy. Nasza baza w Auchindoun jest do tego po prostu zbyt niewygodna.$B$BChwileczkę, czy ja cię znam?', 'A na co to wygląda? Remontuję to miejsce – i to sam, dodam – żebyśmy mogli się wprowadzić!$B$BZ bazą wypadową tutaj, w puszczy, łatwiej będzie śledzić, co knują Shattrath, Fort Alleriański, Warownia Kamieniołamaczy i druidzi cenariońscy. Nasza baza w Auchindoun jest do tego po prostu zbyt niewygodna.$B$BChwileczkę, czy ja cię znam?', 0),
(15762, 'koKR', 'Tak? A niech to, teraz będę musiał zaczynać od nowa!', 'Tak? A niech to, teraz będę musiał zaczynać od nowa!', 0),
(15763, 'koKR', 'Co tam robisz?', 'Co tam robisz?', 0),
(15764, 'koKR', 'Ćwiczę! Niedługo będę na tyle dobry, żeby dołączyć do innych przywoływaczy i objąć zmianę w Labiryncie Cieni w Auchindoun.$B$BMam nadzieję, że dostanę szansę przywołać coś wielkiego! Może coś tak wielkiego jak Szmer, tylko że ja nie straciłbym nad nim kontroli!', 'Ćwiczę! Niedługo będę na tyle dobry, żeby dołączyć do innych przywoływaczy i objąć zmianę w Labiryncie Cieni w Auchindoun.$B$BMam nadzieję, że dostanę szansę przywołać coś wielkiego! Może coś tak wielkiego jak Szmer, tylko że ja nie straciłbym nad nim kontroli!', 0),
(15766, 'koKR', 'A co właściwie twoim zdaniem mogę dla ciebie zrobić? Nie widzisz, że jestem bardzo zajęty omawianiem ważnych spraw z naszym znakomitym przywódcą?$B$BZałatwiaj szybko, z czym przychodzisz, albo każę cię wychłostać, psie!', 'A co właściwie twoim zdaniem mogę dla ciebie zrobić? Nie widzisz, że jestem bardzo zajęty omawianiem ważnych spraw z naszym znakomitym przywódcą?$B$BZałatwiaj szybko, z czym przychodzisz, albo każę cię wychłostać, psie!', 0),
(15767, 'koKR', 'Doradco, jakie są najnowsze wieści?', 'Doradco, jakie są najnowsze wieści?', 0),
(15768, 'koKR', 'Cóż, właśnie składałem naszemu przywódcy raport o tym, jak wszystko idzie zgodnie z planem. Jeszcze tylko kilka tygodni i doprowadzimy to miejsce do porządku.$B$BMoże jednak powinniśmy poprosić Radę Cieni, by obsadziła wioskę wyłącznie orkami. Wtedy moglibyśmy powołać się na prawa przodków i działać pod przykrywką.$B$BChwileczkę. Czy ja cię znam? Jak się nazywasz?', 'Cóż, właśnie składałem naszemu przywódcy raport o tym, jak wszystko idzie zgodnie z planem. Jeszcze tylko kilka tygodni i doprowadzimy to miejsce do porządku.$B$BMoże jednak powinniśmy poprosić Radę Cieni, by obsadziła wioskę wyłącznie orkami. Wtedy moglibyśmy powołać się na prawa przodków i działać pod przykrywką.$B$BChwileczkę. Czy ja cię znam? Jak się nazywasz?', 0),
(15792, 'koKR', 'Zwiadowczyni Neftis, potrzebuję kolejnego przebrania.', 'Zwiadowczyni Neftis, potrzebuję kolejnego przebrania.', 0),
(15794, 'koKR', '', 'Musiałam gdzieś popełnić błąd, skoro mnie tu przydzielono.', 0),
(15834, 'koKR', 'Spocznij, poruczniku. Mów dalej.', '', 0),
(15835, 'koKR', 'Co znowu, Żwirku?', '', 0),
(15836, 'koKR', 'Co jeszcze mogłoby pójść nie tak?', '', 0),
(15837, 'koKR', 'Tak, poruczniku? Melduj.', '', 0),
(15849, 'koKR', 'To rzeczywiście niepokojące wieści. Dopilnuj, żeby natychmiast się tym zajęto!', '', 0),
(15850, 'koKR', 'Nie mam na to czasu, poruczniku. Dopilnuj, żeby to zostało załatwione.', '', 0),
(15851, 'koKR', 'Jeśli mamy w jakikolwiek sposób w tym pomóc, potrzebujemy więcej ludzi. Ściągnij do pomocy kilku zwiadowców.', '', 0),
(15852, 'koKR', 'Poruczniku, masz się tym zająć w pierwszej kolejności. Powiadom każdego, kto twoim zdaniem może pomóc.', '', 0),
(15871, 'koKR', 'Tak, $gobywatelu:obywatelko;? Jaką ważną sprawę chcesz mi przedstawić?', '', 0),
(15876, 'koKR', '', 'Cześć! Pomożesz mi się stąd wydostać?', 0),
(15882, 'koKR', '', 'Dobra, wynośmy się stąd!', 0),
(15883, 'koKR', '', 'Na pewno $gjesteś gotowy:jesteś gotowa;? Odetchnij chwilę.', 0),
(15884, 'koKR', '', 'Dobra, do dzieła!', 0),
(15887, 'koKR', '', 'Dobra, dalej chyba dam sobie radę sama. Dziękuję, że $gwyciągnąłeś:wyciągnęłaś; mnie stamtąd!', 0),
(16049, 'koKR', 'Dziękuję za uwolnienie, $n! Idę do Shattrath!', '', 0),
(16053, 'koKR', 'Teraz jest nasza szansa! Wypuść mnie z tej klatki!', '', 0),
(16054, 'koKR', 'Za chwilę cię stamtąd wyciągnę.', 'Za chwilę cię stamtąd wyciągnę.', 0),
(16249, 'koKR', 'Nie ujdziesz z życiem!', 'Nie ujdziesz z życiem!', 0),
(16250, 'koKR', 'Zabić ich, zanim uciekną!', 'Zabić ich, zanim uciekną!', 0),
(16251, 'koKR', 'Za dużo wiesz!', 'Za dużo wiesz!', 0),
(16252, 'koKR', 'Za Kael\'thasa!', 'Za Kael\'thasa!', 0),
(16253, 'koKR', 'Nie mogą uciec!', 'Nie mogą uciec!', 0),
(16254, 'koKR', 'Najpierw wezmę twoją energię, a potem życie!', 'Najpierw wezmę twoją energię, a potem życie!', 0),
(16414, 'koKR', '', 'Witaj. Odpoczniesz tu, a może coś zjesz?', 0),
(16721, 'koKR', 'Cóż przyniosły nam wiatry Otchłani?', '', 0),
(16722, 'koKR', 'Jesteś daleko od domu, przybyszu.', '', 0),
(16723, 'koKR', 'Witaj w Pustce...', '', 0),
(16724, 'koKR', 'Jeśli słyszysz szept, to umierasz...', '', 0),
(16798, 'koKR', 'Zguba dosięga nas wszystkich!', 'Zguba dosięga nas wszystkich!', 0),
(16799, 'koKR', 'W imię Sargerasa!', 'W imię Sargerasa!', 0),
(16800, 'koKR', 'Nadchodzi twój koniec!', 'Nadchodzi twój koniec!', 0),
(16801, 'koKR', 'Robię, co muszę!', 'Robię, co muszę!', 0),
(16802, 'koKR', 'Legion panuje!', 'Legion panuje!', 0),
(16803, 'koKR', 'Zostanę nagrodzony!', 'Zostanę nagrodzony!', 0),
(16868, 'koKR', '', 'Wstrzymaj atak, to tylko przebranie! Jestem szpiegiem pracującym dla koalicji Dolnego Miasta z Shattrath.$B$BMam nadzieję, że przybywasz z pomocą!', 0),
(16969, 'koKR', 'Hej, czytałeś o nagrodzie z tego listu gończego?', 'Hej, czytałeś o nagrodzie z tego listu gończego?', 0),
(16970, 'koKR', 'Na tym liście gończym piszą, że oferują złoto tak zwanym poszukiwaczom przygód za zabijanie różnych stworów. Czy to nie tym my się zajmujemy? Chyba za mało mi płacą!', 'Na tym liście gończym piszą, że oferują złoto tak zwanym poszukiwaczom przygód za zabijanie różnych stworów. Czy to nie tym my się zajmujemy? Chyba za mało mi płacą!', 0),
(16971, 'koKR', 'Na tym liście gończym jest nagroda za kościosmagacze. Myślisz, że powinienem się tym zająć?', 'Na tym liście gończym jest nagroda za kościosmagacze. Myślisz, że powinienem się tym zająć?', 0),
(16972, 'koKR', 'Kościane Pustkowia! Nieważne, jaką nagrodę oferują, nie pójdę na Kościane Pustkowia!', 'Kościane Pustkowia! Nieważne, jaką nagrodę oferują, nie pójdę na Kościane Pustkowia!', 0),
(16974, 'koKR', 'Chcesz po zmianie pójść po nagrodę z tego listu gończego?', 'Chcesz po zmianie pójść po nagrodę z tego listu gończego?', 0),
(16975, 'koKR', 'Nie wiem i nic mnie to nie obchodzi.', 'Nie wiem i nic mnie to nie obchodzi.', 0),
(16976, 'koKR', 'Czy o tym liście gończym zamierzasz dziś gadać przez cały czas?', 'Czy o tym liście gończym zamierzasz dziś gadać przez cały czas?', 0),
(16977, 'koKR', 'Chętnie przyjrzę się tej nagrodzie po zmianie.', 'Chętnie przyjrzę się tej nagrodzie po zmianie.', 0),
(16978, 'koKR', 'Z kościosmagaczami z pustkowi nie ma żartów. Słyszałem, że roznoszą choroby!', 'Z kościosmagaczami z pustkowi nie ma żartów. Słyszałem, że roznoszą choroby!', 0),
(16979, 'koKR', 'Przydałyby mi się dodatkowe pieniądze.', 'Przydałyby mi się dodatkowe pieniądze.', 0),
(16984, 'koKR', 'Ty czytać list gończy dla Greka?$B$BGrek chcieć pomóc!', '', 0),
(16985, 'koKR', 'Niech ktoś przyjść przeczytać Grekowi ten list gończy. Grek nie umieć czytać!', '', 0),
(17039, 'koKR', '%s zakłada szaty z wilczego futra.', '', 0),
(17044, 'koKR', 'Wilczy duchu puszczy, usłysz mnie!', '', 0),
(17046, 'koKR', 'Dawno temu byłeś towarzyszem mojego ludu. Oddaliśmy się złu i o tobie zapomniano.', '', 0),
(17047, 'koKR', 'Ale powróciliśmy, duchu! Powróciliśmy, by znów oddawać ci cześć. Obdarz nas raz jeszcze swoją obecnością.', '', 0),
(17055, 'koKR', 'Oby nasza więź z tobą już nigdy nie została zerwana, duchu.', '', 0),
(17066, 'koKR', 'Udało się! Thrall byłby dumny.', '', 0),
(17068, 'koKR', 'Greku, wypróbujesz nowy olej do broni, który zrobiła Rakoria?', 'Greku, wypróbujesz nowy olej do broni, który zrobiła Rakoria?', 0),
(17069, 'koKR', 'Grek spróbować!', '', 0),
(17070, 'koKR', 'Ten olej nie dobry dla Greka! Grek wyglądać jak jakiś cherlak w szacie?', '', 0),
(17219, 'koKR', 'Co to jest „olog”? Lepiej zapytać, czym „olog” nie jest. To znaczy, że badam wszystko! Właściwie tak dobrze znam się na „wszystkim”, że gwarantuję, iż jestem najinteligentniejszym eterykiem, jakiego kiedykolwiek spotkasz – albo zwrot pieniędzy.$B$BWybacz. To przemawia przeze mnie handlarz...', '', 0),
(17220, 'koKR', 'Nie jestem ani chudy, ani podejrzany. Prawdę mówiąc, oba te określenia uważam za obraźliwe.$B$BA teraz zejdź mi z oczu, zanim wsadzę ci tę laskę tam, gdzie słońce nie dochodzi.', '', 0),
(17221, 'koKR', 'Ach, widzę, że jesteś $gprzyjacielem:przyjaciółką; Konsorcjum. Może zechcesz coś kupić?', '', 0),
(17222, 'koKR', 'Pokaż, co masz na sprzedaż, „Chudy”.', 'Pokaż, co masz na sprzedaż, „Chudy”.', 0),
(17223, 'koKR', 'Ten Shaffar to spryciarz. Zabezpieczył wejście jakąś barierą, żeby nie wpuścić innych grup eteryków. Pracujemy nad przełamaniem jego zabezpieczeń, żeby wejść do środka i zabrać to, co nasze. Najlepsi eterycy pracują nad tym dzień i noc. Lada chwila będzie otwarte. Czuję to...', '', 0),
(17228, 'koKR', '%s sprawdza, czy jego ciało jest w całości.', '', 0),
(17229, 'koKR', 'Udało ci się! Dobra robota. A teraz wybacz, muszę wprowadzić do środka resztę naszej ekipy.', '', 0),
(17230, 'koKR', '%s zręcznie obsługuje panel sterowania.', '', 0),
(17231, 'koKR', 'Nie traćmy czasu! Bierzcie wszystko, co nie jest przybite do podłogi, i teleportujcie się prosto do Burzowej Iglicy! Migiem!', '', 0),
(17246, 'koKR', 'To nie powinno długo potrwać. Pilnuj tylko moich pleców, kiedy będę opróżniał te kolektory Otchłani.', '', 0),
(17248, 'koKR', 'Fantastycznie! Idziemy dalej, dobrze?', '', 0),
(17249, 'koKR', 'Sądząc po tych poziomach energii, Shaffar miał zbić fortunę!', '', 0),
(17251, 'koKR', 'To powinno wystarczyć...', '', 0),
(17252, 'koKR', 'Hmm, gdzie jest następny kolektor?', '', 0),
(17254, 'koKR', 'A, tu jest. Za mną, istoto z mięsa.', '', 0),
(17255, 'koKR', 'Nie może być już wielu tych kolektorów. Po prostu chroń mnie, kiedy wykonuję swoją pracę.', '', 0),
(17256, 'koKR', 'Co my tu mamy? Zdawało mi się, że $gmówiłeś:mówiłaś;, że teren jest bezpieczny? To już trzeci atak! Jeśli stąd wyjdziemy, na pewno potrącę ci to z nagrody. No nie stój tak, zniszcz ich, żebym mógł dostać się do tego kolektora.', '', 0),
(17258, 'koKR', 'Jesteśmy blisko wyjścia. Dam ci jakieś trzydzieści sekund odpoczynku, ale potem się stąd zmywamy.', '', 0),
(17260, 'koKR', '$GGotowy:Gotowa; do drogi?', '', 0),
(17261, 'koKR', 'Dobra, przerwa SKOŃCZONA. Ruszamy!', '', 0),
(17263, 'koKR', 'Doprawdy? A cóż to takiego?', '', 0),
(17264, 'koKR', 'Wiesz, miał rację. Muszę przejąć to hasło dla siebie... I tak już mu się nie przyda!', '', 0),
(17265, 'koKR', 'Dzięki i powodzenia!', '', 0),
(17293, 'koKR', 'Jeśli przysłano cię, żebyś mnie $gzabił:zabiła;, weź numerek i czekaj na swoją kolej.', '', 0),
(17297, 'koKR', '', 'Proszę, zostaw mnie z moim smutkiem.', 0),
(17351, 'koKR', 'Witaj, $gprzyjacielu:przyjaciółko; wolnego ludu Dolnego Miasta, ale nie zwlekaj długo.$B$BZe środka dochodzą odgłosy walki. Moim towarzyszom przydałaby się twoja pomoc!', '', 0),
(17352, 'koKR', 'Jeśli zostaniesz $gprzyjacielem:przyjaciółką; Dolnego Miasta, może ubijemy jakiś interes?', '', 0),
(17412, 'koKR', 'Mówi się, że ci, których pobłogosławiły duchy Auchindoun, potrafią chwytać potężne dusze w postaci odłamków ducha. Podczas swoich podróży natrafiłem na kilka takich odłamków ducha, ale wciąż nie odkryłem ich tajemnic.\nZdołałem ustalić tylko tyle, że najwyraźniej pochodzą z głębin samego Auchindoun. Jeśli natrafisz na któryś z tych odłamków ducha, z pewnością zdołam ci to wynagrodzić, jeśli pozwolisz mi je od ciebie odkupić...', '', 0),
(17446, 'koKR', '%s czyta z księgi umarłych.', '', 0),
(17447, 'koKR', 'Jeffrey Kaplan! Tom Chilton! Rob Pardo!', '', 0),
(17448, 'koKR', 'Justin Thavirat! Roman Kenney! Cały nasz niesamowity zespół grafików i animatorów!', '', 0),
(17449, 'koKR', 'CHRIS METZEN!', '', 0),
(17450, 'koKR', 'Pat Nagle! Zespół projektowania świata! Cory Stockton, Paul C., Jim Chadwick, Staats, Ed Hanes, Morris, Gotcher, Jesse!, Sarah B., Victor C., Dave A.! Wszyscy nasi niesamowici graficy od plenerów!', '', 0),
(17451, 'koKR', 'Scott Mercer! Geoff, Wyatt, Joe, Travis, Kris, Steven! Brazie!', '', 0),
(17452, 'koKR', 'Luis, Brianna i Eric! Zespół testerów Blizzarda! No i oczywiście nasi fani!', '', 0),
(17453, 'koKR', 'Kevin Jordan i Jonathan LeCraft!', '', 0),
(17454, 'koKR', 'Shane Dabiri, Lee, Alex T., Rob F., J. A. B., A. Mayberry!', '', 0),
(17480, 'koKR', 'To moja pasja, wiesz. Za życia i po śmierci kocham płatnerstwo. Proszę, traktuj mnie tak, jakbym był żywym draenei, przybyszu. Pozwól mi znów poczuć, co znaczy czuć... Zaszczyć mnie i pozwól naprawić swoje rzeczy.', '', 0),
(17733, 'koKR', 'Ja też mam – kra-kra! – swoje zwierzątka!', '', 0),
(17734, 'koKR', 'Mmm... czas na mój ruch!', '', 0),
(17735, 'koKR', 'Ładne zwierzątka, tak... raa-a-ak!', '', 0),
(17736, 'koKR', 'Ładne zwierzątka mają broń. Nie tak – ra-ak – ładnie.', '', 0),
(17737, 'koKR', 'Tak, ulotne jest życie, rak-a-kak!', '', 0),
(17738, 'koKR', 'Mmmm... wolność. Kra!', '', 0),
(17739, 'koKR', 'Mmm... koniec życia. Koniec bólu. A-ak!', '', 0),
(18659, 'koKR', 'Fort Alleriański jest otoczony wrogami ze wszystkich stron, więc czas, byśmy to my ruszyli na nich.', '', 0),
(18661, 'koKR', '', 'Skoro już tu jesteś, przydaj się na coś, bo tamten skrytotropiciel niewiele robi.', 0),
(18676, 'koKR', '5...', '', 0),
(18820, 'koKR', 'Zagrożenie minąć! $n ocalić nas wszystkich!', '', 0),
(18845, 'koKR', 'Miejcie się na baczności! Wróg krąży w pobliżu.', '', 0),
(18846, 'koKR', 'Tam są!', '', 0),
(19051, 'koKR', '%s wie, że nie ma już czasu, i nawet nie próbuje uciekać.', '%s wie, że nie ma już czasu, i nawet nie próbuje uciekać.', 0),
(19063, 'koKR', '', 'Od nauki czytania chce się pić. Wzniesiemy toast, co?', 0),
(19073, 'koKR', 'Grek dostać picie!', '', 0),
(19075, 'koKR', '', 'Radujcie się, przyjaciele! $n $gocalił:ocaliła; nas przed cieniem, który zagrażał samemu naszemu życiu!', 0),
(19076, 'koKR', 'Jesteśmy uratowani? Naprawdę uratowani?! JUHUU!', '', 0),
(19077, 'koKR', 'Czas na IMPREZĘ!', '', 0),
(19078, 'koKR', '%s z uśmiechem lekko klaszcze.', '', 0),
(19079, 'koKR', 'Cóż za szczęśliwy zbieg okoliczności. Sądzę, że to wymaga wina.', '', 0),
(19080, 'koKR', 'Szlachetny rocznik dla uczczenia naszego ocalenia!', '', 0),
(19156, 'koKR', 'Mój panie, twoja obecność to dla nas zaszczyt. Jak mogę ci służyć?', '', 0),
(19159, 'koKR', 'Wszystko idzie nadzwyczaj dobrze, mój panie. Test mniejszego prototypu w Gąszczu Cenariona zakończył się pełnym sukcesem. Druga bomba jest właśnie rytualnie zasilana na dziedzińcu poniżej. Wysłałem też kuriera do Tuurem, by przywiózł nam tu resztę części.', '', 0),
(19160, 'koKR', 'Jesteś zadowolony?', '', 0),
(19164, 'koKR', 'Zapewniam cię, że nie zawiedziemy, mój panie. Osobiście nadzoruję każdy etap budowy, a ostatnie kody trzymam u siebie. W ciągu doby zdetonuję bombę nad tymi pobliskimi szkodnikami.', '', 0),
(19463, 'koKR', 'Trzeba naostrzyć ostrze, a może potrzebujesz nowej broni? Lepiej dmuchać na zimne...', '', 0),
(19465, 'koKR', 'Jeśli szukasz młota, $gtrafiłeś:trafiłaś; we właściwe miejsce.', '', 0),
(19586, 'koKR', 'Można wyciągnąć człowieka z Synów Lothara, ale nie da się wyciągnąć Synów Lothara z człowieka.$B$B<Kowal wzrusza ramionami.>$B$BTrudno to wyjaśnić, ale po prostu nie czuję, żebym w tej chwili był na swoim miejscu w Warowni Honoru.$B$BMoże mam być częścią czegoś większego.', '', 0),
(20109, 'koKR', 'Hura! Jesteśmy wolni!', 'Hura! Jesteśmy wolni!', 0),
(20110, 'koKR', 'Juhu!', 'Juhu!', 0),
(20111, 'koKR', 'Hura! Kochamy cię! $GUratowałeś:Uratowałaś; nas!', 'Hura! Kochamy cię! $GUratowałeś:Uratowałaś; nas!', 0),
(20114, 'koKR', 'Chyba ci dziwni ptasi goście chcieli nas zjeść. Fuj!', 'Chyba ci dziwni ptasi goście chcieli nas zjeść. Fuj!', 0),
(20115, 'koKR', 'Fuj!', 'Fuj!', 0),
(20143, 'koKR', 'Chwała naaru, jestem ocalony. Spróbuję sam się stąd wydostać.', 'Chwała naaru, jestem ocalony. Spróbuję sam się stąd wydostać.', 0),
(20144, 'koKR', 'Jestem ranny, ale wciąż mogę biec. Dziękuję, przybyszu.', 'Jestem ranny, ale wciąż mogę biec. Dziękuję, przybyszu.', 0),
(20145, 'koKR', 'Dziękuję, przybyszu.', 'Dziękuję, przybyszu.', 0),
(20146, 'koKR', 'Jestem zbyt słaby, by walczyć u twego boku. Proszę, odnajdź moich przyjaciół.', 'Jestem zbyt słaby, by walczyć u twego boku. Proszę, odnajdź moich przyjaciół.', 0),
(20160, 'koKR', 'Mów, parszywy uchodźco! Co twoja karawana robiła na Kościanych Pustkowiach?', 'Mów, parszywy uchodźco! Co twoja karawana robiła na Kościanych Pustkowiach?', 0),
(20161, 'koKR', 'Opuśćmy to miejsce. Mam dość tych szaleńców!', '', 0),
(20162, 'koKR', 'Uważaj! Nadchodzą kolejni kultyści!', '', 0),
(20163, 'koKR', 'Stąd trafię sam. Mój przyjaciel Mekeda wynagrodzi cię za twoją życzliwość.', '', 0),
(20164, 'koKR', 'Nigdzie nie pójdziesz, głupcze!', 'Nigdzie nie pójdziesz, głupcze!', 0),
(20165, 'koKR', 'Tak łatwo nam nie uciekniesz!', 'Tak łatwo nam nie uciekniesz!', 0),
(20166, 'koKR', '', 'Nieudolni głupcy! Auchindoun miało być nasze... Spójrzcie na siebie, miotacie się jak szczury!', 0),
(20169, 'koKR', 'Auchindoun to dom duchów moich przodków. Może na to nie wyglądamy, ale wszyscy Złamani byli kiedyś draenei... nasze duchy są takie same.', '', 0),
(20245, 'koKR', 'Te pustkowia są naznaczone straszliwą magią. Musimy zrobić, co w naszej mocy, by uleczyć tę wielką ranę.', '', 0),
(20252, 'koKR', 'Przybyłem do tej krainy, by oczyszczać niespokojne duchy, ale po ataku obawiam się, że moja misja się nie powiodła. Tak wielu pochłonęły pustkowia. Proszę, musisz im pomóc.', '', 0),
(20283, 'koKR', 'Podniebne Skrzydło, uwolnię cię od klątwy – po moim trupie!', '', 0),
(20298, 'koKR', 'Za wcześnie mnie przywróciliście! Wciąż jestem słaby... Co to ma być! Kto... Nieważne! GIŃ!', 'Za wcześnie mnie przywróciliście! Wciąż jestem słaby... Co to ma być! Kto... Nieważne! GIŃ!', 0),
(20314, 'koKR', 'Dobra, słuchajcie! Otoczcie mnie kręgiem i ruszamy!', '', 0),
(20328, 'koKR', 'Dobra, pilnuj tylko, żeby nic nam się nie stało, kiedy będziemy pracować. Zapłacimy ci, jak wrócimy.', '', 0),
(20329, 'koKR', 'Wykopalisko jest tuż na północ stąd.', '', 0),
(20330, 'koKR', 'Jesteśmy na miejscu! Kopać!', '', 0),
(20331, 'koKR', 'Chyba coś tu jest zakopane, pod piaskiem!', '', 0),
(20332, 'koKR', 'Już prawie!', '', 0),
(20333, 'koKR', 'Na brodate banany Branna! Co to jest!? To... To wygląda jak bęben.', '', 0),
(20334, 'koKR', 'Rany... bęben.', 'Rany... bęben.', 0),
(20335, 'koKR', 'To odkrycie z pewnością wstrząśnie fundamentami współczesnej archeologii.', 'To odkrycie z pewnością wstrząśnie fundamentami współczesnej archeologii.', 0),
(20336, 'koKR', 'No, super. Możemy już iść? Od tej pustyni dostaję pokrzywki.', 'No, super. Możemy już iść? Od tej pustyni dostaję pokrzywki.', 0),
(20337, 'koKR', 'Odbiło wam? Myślicie, że zostawię bęben, zanim w niego nie walnę? Nie ten syn Żelaznej Kuźni! O nie!', '', 0),
(20339, 'koKR', 'Przypomina mi to ten raz, kiedy kazałeś nam przeszukiwać Silithus w poszukiwaniu śladów piaskowych gnomów.', 'Przypomina mi to ten raz, kiedy kazałeś nam przeszukiwać Silithus w poszukiwaniu śladów piaskowych gnomów.', 0),
(20340, 'koKR', 'Albo kiedy nam powiedziałeś, że odkryłeś lekarstwo na zarazę dwudziestego wieku. Co to w ogóle jest? Dwudziesty wiek?', 'Albo kiedy nam powiedziałeś, że odkryłeś lekarstwo na zarazę dwudziestego wieku. Co to w ogóle jest? Dwudziesty wiek?', 0),
(20342, 'koKR', 'Chyba nic nie przebije tego razu, kiedy powiedział nam, że słyszał, jakoby szkielet „kuzyna” Arthasa był zamrożony pod lodowcem w Zimozdroju. Nigdy ci tego nie wybaczę, Letoll. No naprawdę... Kuzyn Arthasa?', 'Chyba nic nie przebije tego razu, kiedy powiedział nam, że słyszał, jakoby szkielet „kuzyna” Arthasa był zamrożony pod lodowcem w Zimozdroju. Nigdy ci tego nie wybaczę, Letoll. No naprawdę... Kuzyn Arthasa?', 0),
(20343, 'koKR', 'Nie wiem. Nic chyba nie przebije tego, jak próbował nas przekonać, że wszyscy tak naprawdę jesteśmy wytworem wyobraźni jakiejś istoty, która używa nas tylko dla własnej rozrywki. Świetnie to przyjęto przy rodzinnym obiedzie.', 'Nie wiem. Nic chyba nie przebije tego, jak próbował nas przekonać, że wszyscy tak naprawdę jesteśmy wytworem wyobraźni jakiejś istoty, która używa nas tylko dla własnej rozrywki. Świetnie to przyjęto przy rodzinnym obiedzie.', 0),
(20344, 'koKR', 'Zamknąć jadaczki! Walnę w ten bęben i koniec!', '', 0),
(20346, 'koKR', 'Ej, słyszycie to?', 'Ej, słyszycie to?', 0),
(20348, 'koKR', 'A NIE MÓWIŁEM! Mówiłem, że coś tu jest!', '', 0),
(20361, 'koKR', 'Nie stójcie tak! Pomóżcie $gmu:jej;!', '', 0),
(20362, 'koKR', '%s podnosi bęben.', '', 0),
(20363, 'koKR', 'Bardzo nam $gpomogłeś:pomogłaś;! Zmywajmy się stąd, zanim pojawi się więcej tych stworów! Powiem Dwarfowitzowi, że $gwykonałeś:wykonałaś; zadanie znakomicie.', '', 0),
(20431, 'koKR', 'Widziałem na tych pustkowiach wiele niebezpieczeństw. Kto wie, jakie stwory jeszcze czają się w pyle, by napaść na nieostrożnych?', '', 0),
(20675, 'koKR', '%s przeszukuje ziemię w poszukiwaniu zakopanych Kruczych Kamieni.', '', 0),
(20676, 'koKR', '%s znajduje zakopany Kruczy Kamień.', '', 0),
(20689, 'koKR', '%s przygląda ci się przez chwilę, po czym daje ci znak, żeby iść za nim.', '', 0),
(21065, 'koKR', 'Wygląda na to, że w pobliżu nie ma Kruczych Kamieni – %s niczego nie znajduje.', '', 0),
(21074, 'koKR', '%s skupia się na celu: $n.', '', 0),
(21075, 'koKR', '%s wpada w nieziemski szał, a jego ciało pęka!', '', 0),
(21076, 'koKR', 'Dzieci moje, oto $n – pożryjcie!', '', 0),
(21077, 'koKR', '%s skupia się na celu: $n.', '', 0),
(21281, 'koKR', 'Od stosu czaszek bije smród zgnilizny. Obawiasz się, że arakkoa całkiem niedawno coś do niego dołożyli.', '', 0),
(21282, 'koKR', '<Przywołaj Gezzarak Łowczynię.>', '<Przywołaj Gezzarak Łowczynię.>', 0),
(21287, 'koKR', '<Przywołaj Vakkiza Wściekłego Wichra.>', '<Przywołaj Vakkiza Wściekłego Wichra.>', 0),
(21288, 'koKR', '<Przywołaj Karroga.>', '<Przywołaj Karroga.>', 0),
(21289, 'koKR', '<Przywołaj Mrocznego Skrzekacza Akkaraia.>', '<Przywołaj Mrocznego Skrzekacza Akkaraia.>', 0),
(21327, 'koKR', 'Pokaż, na co cię stać, $n!', '', 0),
(21328, 'koKR', '%s wpada w szał, gdy jego tarcza pęka.', '', 0),
(21340, 'koKR', 'Tysiąc przekleństw na ciebie! To więzienie nie zatrzyma mnie na długo!', '', 0),
(21412, 'koKR', 'Przybywasz mnie skrzywdzić? Nie mam nic wspólnego z wojną.$B$BJestem tylko chorowitym uczonym, proszę, zostaw mnie w spokoju!', '', 0),
(21495, 'koKR', 'Skwak!', 'Skwak!', 0),
(21496, 'koKR', 'Jesteś młodym pisklęciem, prawda? Oczy mnie zawodzą.$B$BZakładam, że chcesz kupić któryś z moich egzotycznych tekstów?', '', 0),
(21551, 'koKR', 'Dzień dobry, $gproszę pana:proszę pani;! Jeśli chcesz, mam płaszczkę Otchłani gotową, by zabrać cię do Posterunku Podniebnej Straży na szczycie Gór Klingi.$B$BDaj tylko znać.', '', 0),
(21552, 'koKR', 'Dzień dobry. Gdy awansujesz nieco wyżej w szeregach Podniebnej Straży Sha\'tari, będę mógł zaoferować ci bezpośredni lot do Posterunku Podniebnej Straży, naszej bazy na szczycie Gór Klingi.', '', 0),
(21553, 'koKR', 'Jasne! Wyślij mnie do Posterunku Podniebnej Straży.', 'Jasne! Wyślij mnie do Posterunku Podniebnej Straży.', 0),
(21626, 'koKR', 'Czego chcesz?', '', 0),
(21627, 'koKR', 'Jestem $gwysłannikiem:wysłanniczką; Balthasa. Przysłał mnie po nieskazitelną tajemną esencję.', 'Jestem $gwysłannikiem:wysłanniczką; Balthasa. Przysłał mnie po nieskazitelną tajemną esencję.', 0),
(21634, 'koKR', '<Przywołaj Terokka.>', '<Przywołaj Terokka.>', 0),
(21639, 'koKR', 'Kto wzywa mnie na ten świat? Gwiazdy nie są jeszcze w odpowiednim położeniu... moc mnie zawodzi! Zapłacisz za to!', '', 0),
(21801, 'koKR', 'Od stosu czaszek bije smród zgnilizny. Obawiasz się, że arakkoa całkiem niedawno coś do niego dołożyli.\nAby przywołać potomków wrogów Terokka, potrzebujesz 10 zgubionych w czasie zwojów.', '', 0),
(21806, 'koKR', 'Od tego stosu czaszek bije straszliwa, mroczna energia.', '', 0),
(21883, 'koKR', 'Hej, to nasz as przestworzy, $n!', 'Hej, to nasz as przestworzy, $n!', 0),
(21885, 'koKR', 'Patrzcie, kto przyszedł. To $n, $gnasz najlepszy pilot:nasza najlepsza pilotka;.', 'Patrzcie, kto przyszedł. To $n, $gnasz najlepszy pilot:nasza najlepsza pilotka;.', 0),
(21886, 'koKR', '$n, czujesz potrzebę... potrzebę prędkości?', '$n, czujesz potrzebę... potrzebę prędkości?', 0),
(21889, 'koKR', 'Znów $gprzeleciałeś:przeleciałaś; z hukiem tuż nad lądowiskiem, $n?', 'Znów $gprzeleciałeś:przeleciałaś; z hukiem tuż nad lądowiskiem, $n?', 0),
(21890, 'koKR', '$GPan:Pani; $n! Cóż za niespodziewana przyjemność, $gproszę pana:proszę pani;.', '$GPan:Pani; $n! Cóż za niespodziewana przyjemność, $gproszę pana:proszę pani;.', 0),
(21891, 'koKR', 'BACZNOŚĆ! Oficer $n na pokładzie!', 'BACZNOŚĆ! Oficer $n na pokładzie!', 0),
(21893, 'koKR', '$n, postrach przestworzy! Jak się masz?', '$n, postrach przestworzy! Jak się masz?', 0),
(21895, 'koKR', 'Heh, niebo nie jest takie przyjazne, kiedy lata po nim $n!', 'Heh, niebo nie jest takie przyjazne, kiedy lata po nim $n!', 0),
(21896, 'koKR', 'Jedno jest pewne: $n to już nie żółtodziób!', 'Jedno jest pewne: $n to już nie żółtodziób!', 0),
(21897, 'koKR', '$n, jak się trzyma twój wierzchowiec? Ciężko tam ostatnio w górze?', '$n, jak się trzyma twój wierzchowiec? Ciężko tam ostatnio w górze?', 0),
(21898, 'koKR', 'No proszę, czy to nie $gnasz etatowy lotnik:nasza etatowa lotniczka;, $n? Jak leci, asie?', 'No proszę, czy to nie $gnasz etatowy lotnik:nasza etatowa lotniczka;, $n? Jak leci, asie?', 0),
(21902, 'koKR', '%s obnaża kły i groźnie syczy na wszystkich wokół.', '', 0),
(21903, 'koKR', 'Ty złapać Karroga! Karrog cię zmiażdżyć!', '', 0),
(21904, 'koKR', 'Słuchaj głosów spod ziemi! Wołają o twoją krew!', '', 0),
(21905, 'koKR', 'Wściekłe wichry otaczają Vakkiza, który groźnie wije się w twoją stronę.', '', 0),
